INSERT INTO public.academy_lessons (id, level_number, lesson_number, title, summary, content, published) VALUES ('l1-01', 1, 1, '{"en":"Introduction to Chess and Board Setup","fr":"Introduction aux échecs et installation de l’échiquier","ar":"مقدمة في الشطرنج وإعداد الرقعة"}'::jsonb, '{"en":"Set up the board correctly, identify the pieces, and understand how a game begins.","fr":"Installez correctement l’échiquier, identifiez les pièces et comprenez le début d’une partie.","ar":"تعلّم إعداد الرقعة والتعرّف على القطع وكيفية بدء المباراة."}'::jsonb, '{"objectives":[{"en":"The board","fr":"L’échiquier","ar":"الرقعة"},{"en":"Board orientation","fr":"L’orientation de l’échiquier","ar":"اتجاه الرقعة"},{"en":"The back rank","fr":"La première rangée","ar":"الصف الخلفي"},{"en":"The armies","fr":"Les armées","ar":"الجيشان"},{"en":"Starting the game","fr":"Le début de la partie","ar":"بدء المباراة"}],"sections":[{"title":{"en":"The board","fr":"L’échiquier","ar":"الرقعة"},"paragraphs":[{"en":"The chessboard has eight files and eight ranks, creating 64 squares.","fr":"L’échiquier compte huit colonnes et huit rangées, soit 64 cases.","ar":"تتكوّن رقعة الشطرنج من ثمانية أعمدة وثمانية صفوف، أي 64 مربعاً."},{"en":"Files run from a to h and ranks from 1 to 8. Every square is named by combining its file and rank.","fr":"Les colonnes vont de a à h et les rangées de 1 à 8. Chaque case est nommée en combinant sa colonne et sa rangée.","ar":"تُسمّى الأعمدة من a إلى h والصفوف من 1 إلى 8. يُحدَّد اسم كل مربع بضم اسم العمود إلى رقم الصف."},{"en":"Practice checkpoint: identify The board on a board, explain the rule, and check how the opponent could respond.","fr":"Mise en pratique : repérez L’échiquier sur un échiquier, expliquez la règle et vérifiez la réponse possible de l’adversaire.","ar":"تطبيق عملي: حدّد الرقعة على الرقعة، واشرح القاعدة، ثم تحقّق من رد الخصم الممكن."}]},{"title":{"en":"Board orientation","fr":"L’orientation de l’échiquier","ar":"اتجاه الرقعة"},"paragraphs":[{"en":"Place the board with a light-colored square at each player’s lower-right corner.","fr":"Placez l’échiquier avec une case claire dans le coin inférieur droit de chaque joueur.","ar":"ضع الرقعة بحيث يكون المربع الفاتح في الزاوية اليمنى السفلية لكل لاعب."},{"en":"The rule is “light on right.” From White’s side, h1 is light and a1 is dark. Correct orientation makes the ranks and files line up.","fr":"La règle est « case claire à droite ». Du côté des Blancs, h1 est claire et a1 est foncée. La bonne orientation aligne correctement rangées et colonnes.","ar":"القاعدة هي «الفاتح على اليمين». من جهة الأبيض، يكون h1 فاتحاً وa1 داكناً. الاتجاه الصحيح يجعل الصفوف والأعمدة في مواضعها."},{"en":"Practice checkpoint: identify Board orientation on a board, explain the rule, and check how the opponent could respond.","fr":"Mise en pratique : repérez L’orientation de l’échiquier sur un échiquier, expliquez la règle et vérifiez la réponse possible de l’adversaire.","ar":"تطبيق عملي: حدّد اتجاه الرقعة على الرقعة، واشرح القاعدة، ثم تحقّق من رد الخصم الممكن."}]},{"title":{"en":"The back rank","fr":"La première rangée","ar":"الصف الخلفي"},"paragraphs":[{"en":"Each back rank starts rook, knight, bishop, queen, king, bishop, knight, rook.","fr":"Chaque première rangée commence par tour, cavalier, fou, dame, roi, fou, cavalier, tour.","ar":"يبدأ الصف الخلفي بالترتيب: رخ، حصان، فيل، وزير، ملك، فيل، حصان، رخ."},{"en":"The major pieces occupy the back rank while pawns stand directly in front. The queen starts on her own color: White queen on d1, Black queen on d8.","fr":"Les pièces majeures occupent la première rangée et les pions se placent devant elles. La dame commence sur sa couleur : dame blanche en d1, dame noire en d8.","ar":"تقف القطع الرئيسية في الصف الخلفي والبيادق أمامها. تبدأ الملكة على مربع من لونها: البيضاء على d1 والسوداء على d8."},{"en":"Practice checkpoint: identify The back rank on a board, explain the rule, and check how the opponent could respond.","fr":"Mise en pratique : repérez La première rangée sur un échiquier, expliquez la règle et vérifiez la réponse possible de l’adversaire.","ar":"تطبيق عملي: حدّد الصف الخلفي على الرقعة، واشرح القاعدة، ثم تحقّق من رد الخصم الممكن."}]},{"title":{"en":"The armies","fr":"Les armées","ar":"الجيشان"},"paragraphs":[{"en":"Each player begins with one king, one queen, two rooks, two bishops, two knights, and eight pawns.","fr":"Chaque joueur commence avec un roi, une dame, deux tours, deux fous, deux cavaliers et huit pions.","ar":"يبدأ كل لاعب بملك وملكة ورخّين وفيلين وحصانين وثمانية بيادق."},{"en":"That is 16 pieces per side. The king is the piece that must be protected; the other pieces help attack, defend, and control squares.","fr":"Cela représente 16 pièces par camp. Le roi doit être protégé ; les autres pièces attaquent, défendent et contrôlent les cases.","ar":"المجموع 16 قطعة لكل لاعب. يجب حماية الملك، بينما تساعد القطع الأخرى على الهجوم والدفاع والسيطرة على المربعات."},{"en":"Practice checkpoint: identify The armies on a board, explain the rule, and check how the opponent could respond.","fr":"Mise en pratique : repérez Les armées sur un échiquier, expliquez la règle et vérifiez la réponse possible de l’adversaire.","ar":"تطبيق عملي: حدّد الجيشان على الرقعة، واشرح القاعدة، ثم تحقّق من رد الخصم الممكن."}]},{"title":{"en":"Starting the game","fr":"Le début de la partie","ar":"بدء المباراة"},"paragraphs":[{"en":"White makes the first move, then the players alternate one move at a time.","fr":"Les Blancs jouent en premier, puis les joueurs jouent chacun leur tour.","ar":"يلعب الأبيض أولاً، ثم يتناوب اللاعبان على نقلة واحدة في كل دور."},{"en":"A move is a legal action by one player. A turn is not complete until the move is made and the opponent is next to play.","fr":"Un coup est une action légale d’un joueur. Une fois le coup joué, c’est à l’adversaire de jouer.","ar":"النقلة هي حركة قانونية للاعب. بعد تنفيذها، ينتقل الدور إلى الخصم."},{"en":"Practice checkpoint: identify Starting the game on a board, explain the rule, and check how the opponent could respond.","fr":"Mise en pratique : repérez Le début de la partie sur un échiquier, expliquez la règle et vérifiez la réponse possible de l’adversaire.","ar":"تطبيق عملي: حدّد بدء المباراة على الرقعة، واشرح القاعدة، ثم تحقّق من رد الخصم الممكن."}]}],"terminology":[{"term":{"en":"The board","fr":"L’échiquier","ar":"الرقعة"},"definition":{"en":"The chessboard has eight files and eight ranks, creating 64 squares.","fr":"L’échiquier compte huit colonnes et huit rangées, soit 64 cases.","ar":"تتكوّن رقعة الشطرنج من ثمانية أعمدة وثمانية صفوف، أي 64 مربعاً."}},{"term":{"en":"Board orientation","fr":"L’orientation de l’échiquier","ar":"اتجاه الرقعة"},"definition":{"en":"Place the board with a light-colored square at each player’s lower-right corner.","fr":"Placez l’échiquier avec une case claire dans le coin inférieur droit de chaque joueur.","ar":"ضع الرقعة بحيث يكون المربع الفاتح في الزاوية اليمنى السفلية لكل لاعب."}},{"term":{"en":"The back rank","fr":"La première rangée","ar":"الصف الخلفي"},"definition":{"en":"Each back rank starts rook, knight, bishop, queen, king, bishop, knight, rook.","fr":"Chaque première rangée commence par tour, cavalier, fou, dame, roi, fou, cavalier, tour.","ar":"يبدأ الصف الخلفي بالترتيب: رخ، حصان، فيل، وزير، ملك، فيل، حصان، رخ."}},{"term":{"en":"The armies","fr":"Les armées","ar":"الجيشان"},"definition":{"en":"Each player begins with one king, one queen, two rooks, two bishops, two knights, and eight pawns.","fr":"Chaque joueur commence avec un roi, une dame, deux tours, deux fous, deux cavaliers et huit pions.","ar":"يبدأ كل لاعب بملك وملكة ورخّين وفيلين وحصانين وثمانية بيادق."}},{"term":{"en":"Starting the game","fr":"Le début de la partie","ar":"بدء المباراة"},"definition":{"en":"White makes the first move, then the players alternate one move at a time.","fr":"Les Blancs jouent en premier, puis les joueurs jouent chacun leur tour.","ar":"يلعب الأبيض أولاً، ثم يتناوب اللاعبان على نقلة واحدة في كل دور."}}],"example":{"fen":"rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1","solutionMoves":["e4"],"annotation":{"en":"e4 is a legal opening move that advances a central pawn and begins the alternating move sequence.","fr":"e4 est un coup d’ouverture légal qui avance un pion central et lance l’alternance des coups.","ar":"e4 نقلة افتتاحية قانونية تحرّك بيدقاً مركزياً وتبدأ تبادل النقلات."}},"commonMistakes":[{"en":"The board has 64 files and 8 ranks.","fr":"L’échiquier compte 64 colonnes et 8 rangées.","ar":"تحتوي الرقعة على 64 عموداً وثمانية صفوف."},{"en":"The lower-right square should be dark.","fr":"La case inférieure droite doit être foncée.","ar":"يجب أن يكون المربع الأيمن السفلي داكناً."},{"en":"The queen starts on the opposite color and the king takes the d-file.","fr":"La dame commence sur la couleur opposée et le roi occupe la colonne d.","ar":"تبدأ الملكة على مربع من اللون المقابل ويقف الملك على عمود d."},{"en":"Each side starts with two queens and one rook.","fr":"Chaque camp commence avec deux dames et une tour.","ar":"يبدأ كل لاعب بملكتين ورخ واحد."},{"en":"Black moves first, and White moves twice before Black can reply.","fr":"Les Noirs jouent en premier et les Blancs jouent deux fois avant leur réponse.","ar":"يلعب الأسود أولاً، ثم يلعب الأبيض مرتين قبل أن يرد الأسود."}],"professionalTips":[{"en":"Before moving, pause and ask how The board affects your king safety and your opponent’s best reply.","fr":"Avant de jouer, demandez-vous comment L’échiquier influence la sécurité de votre roi et la meilleure réponse adverse.","ar":"قبل أن تلعب، فكّر كيف يؤثر الرقعة في أمان ملكك وفي أفضل رد للخصم."},{"en":"Before moving, pause and ask how Board orientation affects your king safety and your opponent’s best reply.","fr":"Avant de jouer, demandez-vous comment L’orientation de l’échiquier influence la sécurité de votre roi et la meilleure réponse adverse.","ar":"قبل أن تلعب، فكّر كيف يؤثر اتجاه الرقعة في أمان ملكك وفي أفضل رد للخصم."},{"en":"Before moving, pause and ask how The back rank affects your king safety and your opponent’s best reply.","fr":"Avant de jouer, demandez-vous comment La première rangée influence la sécurité de votre roi et la meilleure réponse adverse.","ar":"قبل أن تلعب، فكّر كيف يؤثر الصف الخلفي في أمان ملكك وفي أفضل رد للخصم."},{"en":"Before moving, pause and ask how The armies affects your king safety and your opponent’s best reply.","fr":"Avant de jouer, demandez-vous comment Les armées influence la sécurité de votre roi et la meilleure réponse adverse.","ar":"قبل أن تلعب، فكّر كيف يؤثر الجيشان في أمان ملكك وفي أفضل رد للخصم."},{"en":"Before moving, pause and ask how Starting the game affects your king safety and your opponent’s best reply.","fr":"Avant de jouer, demandez-vous comment Le début de la partie influence la sécurité de votre roi et la meilleure réponse adverse.","ar":"قبل أن تلعب، فكّر كيف يؤثر بدء المباراة في أمان ملكك وفي أفضل رد للخصم."}],"exercises":[{"en":"Set up a position that demonstrates The board. Name the legal choices and explain why one choice follows the rule.","fr":"Préparez une position illustrant L’échiquier. Indiquez les choix légaux et expliquez lequel respecte la règle.","ar":"أنشئ وضعية توضّح الرقعة. اذكر النقلات القانونية واشرح لماذا تتبع إحداها القاعدة."},{"en":"Set up a position that demonstrates Board orientation. Name the legal choices and explain why one choice follows the rule.","fr":"Préparez une position illustrant L’orientation de l’échiquier. Indiquez les choix légaux et expliquez lequel respecte la règle.","ar":"أنشئ وضعية توضّح اتجاه الرقعة. اذكر النقلات القانونية واشرح لماذا تتبع إحداها القاعدة."},{"en":"Set up a position that demonstrates The back rank. Name the legal choices and explain why one choice follows the rule.","fr":"Préparez une position illustrant La première rangée. Indiquez les choix légaux et expliquez lequel respecte la règle.","ar":"أنشئ وضعية توضّح الصف الخلفي. اذكر النقلات القانونية واشرح لماذا تتبع إحداها القاعدة."},{"en":"Set up a position that demonstrates The armies. Name the legal choices and explain why one choice follows the rule.","fr":"Préparez une position illustrant Les armées. Indiquez les choix légaux et expliquez lequel respecte la règle.","ar":"أنشئ وضعية توضّح الجيشان. اذكر النقلات القانونية واشرح لماذا تتبع إحداها القاعدة."},{"en":"Set up a position that demonstrates Starting the game. Name the legal choices and explain why one choice follows the rule.","fr":"Préparez une position illustrant Le début de la partie. Indiquez les choix légaux et expliquez lequel respecte la règle.","ar":"أنشئ وضعية توضّح بدء المباراة. اذكر النقلات القانونية واشرح لماذا تتبع إحداها القاعدة."}],"takeaways":[{"en":"The chessboard has eight files and eight ranks, creating 64 squares.","fr":"L’échiquier compte huit colonnes et huit rangées, soit 64 cases.","ar":"تتكوّن رقعة الشطرنج من ثمانية أعمدة وثمانية صفوف، أي 64 مربعاً."},{"en":"Place the board with a light-colored square at each player’s lower-right corner.","fr":"Placez l’échiquier avec une case claire dans le coin inférieur droit de chaque joueur.","ar":"ضع الرقعة بحيث يكون المربع الفاتح في الزاوية اليمنى السفلية لكل لاعب."},{"en":"Each back rank starts rook, knight, bishop, queen, king, bishop, knight, rook.","fr":"Chaque première rangée commence par tour, cavalier, fou, dame, roi, fou, cavalier, tour.","ar":"يبدأ الصف الخلفي بالترتيب: رخ، حصان، فيل، وزير، ملك، فيل، حصان، رخ."},{"en":"Each player begins with one king, one queen, two rooks, two bishops, two knights, and eight pawns.","fr":"Chaque joueur commence avec un roi, une dame, deux tours, deux fous, deux cavaliers et huit pions.","ar":"يبدأ كل لاعب بملك وملكة ورخّين وفيلين وحصانين وثمانية بيادق."},{"en":"White makes the first move, then the players alternate one move at a time.","fr":"Les Blancs jouent en premier, puis les joueurs jouent chacun leur tour.","ar":"يلعب الأبيض أولاً، ثم يتناوب اللاعبان على نقلة واحدة في كل دور."}]}'::jsonb, TRUE) ON CONFLICT (id) DO UPDATE SET level_number = EXCLUDED.level_number, lesson_number = EXCLUDED.lesson_number, title = EXCLUDED.title, summary = EXCLUDED.summary, content = EXCLUDED.content, published = TRUE, updated_at = NOW();
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-01-q01', 'l1-01', 1, 'easy', 'multiple_choice', '{"en":"Which statement correctly describes The board?","fr":"Quelle affirmation décrit correctement L’échiquier ?","ar":"أي عبارة تصف الرقعة بشكل صحيح؟"}'::jsonb, '[{"id":"a","label":{"en":"Each player begins with one king, one queen, two rooks, two bishops, two knights, and eight pawns.","fr":"Chaque joueur commence avec un roi, une dame, deux tours, deux fous, deux cavaliers et huit pions.","ar":"يبدأ كل لاعب بملك وملكة ورخّين وفيلين وحصانين وثمانية بيادق."}},{"id":"b","label":{"en":"The chessboard has eight files and eight ranks, creating 64 squares.","fr":"L’échiquier compte huit colonnes et huit rangées, soit 64 cases.","ar":"تتكوّن رقعة الشطرنج من ثمانية أعمدة وثمانية صفوف، أي 64 مربعاً."}},{"id":"c","label":{"en":"Place the board with a light-colored square at each player’s lower-right corner.","fr":"Placez l’échiquier avec une case claire dans le coin inférieur droit de chaque joueur.","ar":"ضع الرقعة بحيث يكون المربع الفاتح في الزاوية اليمنى السفلية لكل لاعب."}},{"id":"d","label":{"en":"Each back rank starts rook, knight, bishop, queen, king, bishop, knight, rook.","fr":"Chaque première rangée commence par tour, cavalier, fou, dame, roi, fou, cavalier, tour.","ar":"يبدأ الصف الخلفي بالترتيب: رخ، حصان، فيل، وزير، ملك، فيل، حصان، رخ."}}]'::jsonb, 'b', '{"en":"Files run from a to h and ranks from 1 to 8. Every square is named by combining its file and rank.","fr":"Les colonnes vont de a à h et les rangées de 1 à 8. Chaque case est nommée en combinant sa colonne et sa rangée.","ar":"تُسمّى الأعمدة من a إلى h والصفوف من 1 إلى 8. يُحدَّد اسم كل مربع بضم اسم العمود إلى رقم الصف."}'::jsonb, '{"en":"Review the rule and compare it with the position. The board","fr":"Relisez la règle et comparez-la à la position. L’échiquier","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. الرقعة"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-01-q02', 'l1-01', 2, 'medium', 'multiple_choice', '{"en":"You are teaching a beginner about The board. Which rule should they apply?","fr":"Vous expliquez L’échiquier à un débutant. Quelle règle doit-il appliquer ?","ar":"تشرح الرقعة لمبتدئ. ما القاعدة التي ينبغي تطبيقها؟"}'::jsonb, '[{"id":"a","label":{"en":"Each back rank starts rook, knight, bishop, queen, king, bishop, knight, rook.","fr":"Chaque première rangée commence par tour, cavalier, fou, dame, roi, fou, cavalier, tour.","ar":"يبدأ الصف الخلفي بالترتيب: رخ، حصان، فيل، وزير، ملك، فيل، حصان، رخ."}},{"id":"b","label":{"en":"Each player begins with one king, one queen, two rooks, two bishops, two knights, and eight pawns.","fr":"Chaque joueur commence avec un roi, une dame, deux tours, deux fous, deux cavaliers et huit pions.","ar":"يبدأ كل لاعب بملك وملكة ورخّين وفيلين وحصانين وثمانية بيادق."}},{"id":"c","label":{"en":"The chessboard has eight files and eight ranks, creating 64 squares.","fr":"L’échiquier compte huit colonnes et huit rangées, soit 64 cases.","ar":"تتكوّن رقعة الشطرنج من ثمانية أعمدة وثمانية صفوف، أي 64 مربعاً."}},{"id":"d","label":{"en":"Place the board with a light-colored square at each player’s lower-right corner.","fr":"Placez l’échiquier avec une case claire dans le coin inférieur droit de chaque joueur.","ar":"ضع الرقعة بحيث يكون المربع الفاتح في الزاوية اليمنى السفلية لكل لاعب."}}]'::jsonb, 'c', '{"en":"Files run from a to h and ranks from 1 to 8. Every square is named by combining its file and rank.","fr":"Les colonnes vont de a à h et les rangées de 1 à 8. Chaque case est nommée en combinant sa colonne et sa rangée.","ar":"تُسمّى الأعمدة من a إلى h والصفوف من 1 إلى 8. يُحدَّد اسم كل مربع بضم اسم العمود إلى رقم الصف."}'::jsonb, '{"en":"Review the rule and compare it with the position. The board","fr":"Relisez la règle et comparez-la à la position. L’échiquier","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. الرقعة"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-01-q03', 'l1-01', 3, 'medium', 'true_false', '{"en":"True or false: The chessboard has eight files and eight ranks, creating 64 squares.","fr":"Vrai ou faux : L’échiquier compte huit colonnes et huit rangées, soit 64 cases.","ar":"صح أم خطأ: تتكوّن رقعة الشطرنج من ثمانية أعمدة وثمانية صفوف، أي 64 مربعاً."}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'true', '{"en":"Files run from a to h and ranks from 1 to 8. Every square is named by combining its file and rank.","fr":"Les colonnes vont de a à h et les rangées de 1 à 8. Chaque case est nommée en combinant sa colonne et sa rangée.","ar":"تُسمّى الأعمدة من a إلى h والصفوف من 1 إلى 8. يُحدَّد اسم كل مربع بضم اسم العمود إلى رقم الصف."}'::jsonb, '{"en":"Review the rule and compare it with the position. The board","fr":"Relisez la règle et comparez-la à la position. L’échiquier","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. الرقعة"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-01-q04', 'l1-01', 4, 'hard', 'identify_mistake', '{"en":"A student claims: “The board has 64 files and 8 ranks.” Is the claim correct?","fr":"Un élève affirme : « L’échiquier compte 64 colonnes et 8 rangées. » Cette affirmation est-elle correcte ?","ar":"يقول طالب: «تحتوي الرقعة على 64 عموداً وثمانية صفوف.» هل قوله صحيح؟"}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'false', '{"en":"Files run from a to h and ranks from 1 to 8. Every square is named by combining its file and rank.","fr":"Les colonnes vont de a à h et les rangées de 1 à 8. Chaque case est nommée en combinant sa colonne et sa rangée.","ar":"تُسمّى الأعمدة من a إلى h والصفوف من 1 إلى 8. يُحدَّد اسم كل مربع بضم اسم العمود إلى رقم الصف."}'::jsonb, '{"en":"Review the rule and compare it with the position. The board","fr":"Relisez la règle et comparez-la à la position. L’échiquier","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. الرقعة"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-01-q05', 'l1-01', 5, 'easy', 'multiple_choice', '{"en":"Which statement correctly describes Board orientation?","fr":"Quelle affirmation décrit correctement L’orientation de l’échiquier ?","ar":"أي عبارة تصف اتجاه الرقعة بشكل صحيح؟"}'::jsonb, '[{"id":"a","label":{"en":"Each player begins with one king, one queen, two rooks, two bishops, two knights, and eight pawns.","fr":"Chaque joueur commence avec un roi, une dame, deux tours, deux fous, deux cavaliers et huit pions.","ar":"يبدأ كل لاعب بملك وملكة ورخّين وفيلين وحصانين وثمانية بيادق."}},{"id":"b","label":{"en":"White makes the first move, then the players alternate one move at a time.","fr":"Les Blancs jouent en premier, puis les joueurs jouent chacun leur tour.","ar":"يلعب الأبيض أولاً، ثم يتناوب اللاعبان على نقلة واحدة في كل دور."}},{"id":"c","label":{"en":"Place the board with a light-colored square at each player’s lower-right corner.","fr":"Placez l’échiquier avec une case claire dans le coin inférieur droit de chaque joueur.","ar":"ضع الرقعة بحيث يكون المربع الفاتح في الزاوية اليمنى السفلية لكل لاعب."}},{"id":"d","label":{"en":"Each back rank starts rook, knight, bishop, queen, king, bishop, knight, rook.","fr":"Chaque première rangée commence par tour, cavalier, fou, dame, roi, fou, cavalier, tour.","ar":"يبدأ الصف الخلفي بالترتيب: رخ، حصان، فيل، وزير، ملك، فيل، حصان، رخ."}}]'::jsonb, 'c', '{"en":"The rule is “light on right.” From White’s side, h1 is light and a1 is dark. Correct orientation makes the ranks and files line up.","fr":"La règle est « case claire à droite ». Du côté des Blancs, h1 est claire et a1 est foncée. La bonne orientation aligne correctement rangées et colonnes.","ar":"القاعدة هي «الفاتح على اليمين». من جهة الأبيض، يكون h1 فاتحاً وa1 داكناً. الاتجاه الصحيح يجعل الصفوف والأعمدة في مواضعها."}'::jsonb, '{"en":"Review the rule and compare it with the position. Board orientation","fr":"Relisez la règle et comparez-la à la position. L’orientation de l’échiquier","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. اتجاه الرقعة"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
