اكناً. الاتجاه الصحيح يجعل الصفوف والأعمدة في مواضعها."}'::jsonb, '{"en":"Review the rule and compare it with the position. Board orientation","fr":"Relisez la règle et comparez-la à la position. L’orientation de l’échiquier","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. اتجاه الرقعة"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
