INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-01-q11', 'l1-01', 11, 'medium', 'true_false', '{"en":"True or false: Each back rank starts rook, knight, bishop, queen, king, bishop, knight, rook.","fr":"Vrai ou faux : Chaque première rangée commence par tour, cavalier, fou, dame, roi, fou, cavalier, tour.","ar":"صح أم خطأ: يبدأ الصف الخلفي بالترتيب: رخ، حصان، فيل، وزير، ملك، فيل، حصان، رخ."}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'true', '{"en":"The major pieces occupy the back rank while pawns stand directly in front. The queen starts on her own color: White queen on d1, Black queen on d8.","fr":"Les pièces majeures occupent la première rangée et les pions se placent devant elles. La dame commence sur sa couleur : dame blanche en d1, dame noire en d8.","ar":"تقف القطع الرئيسية في الصف الخلفي والبيادق أمامها. تبدأ الملكة على مربع من لونها: البيضاء على d1 والسوداء على d8."}'::jsonb, '{"en":"Review the rule and compare it with the position. The back rank","fr":"Relisez la règle et comparez-la à la position. La première rangée","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. الصف الخلفي"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-01-q12', 'l1-01', 12, 'hard', 'identify_mistake', '{"en":"A student claims: “The queen starts on the opposite color and the king takes the d-file.” Is the claim correct?","fr":"Un élève affirme : « La dame commence sur la couleur opposée et le roi occupe la colonne d. » Cette affirmation est-elle correcte ?","ar":"يقول طالب: «تبدأ الملكة على مربع من اللون المقابل ويقف الملك على عمود d.» هل قوله صحيح؟"}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'false', '{"en":"The major pieces occupy the back rank while pawns stand directly in front. The queen starts on her own color: White queen on d1, Black queen on d8.","fr":"Les pièces majeures occupent la première rangée et les pions se placent devant elles. La dame commence sur sa couleur : dame blanche en d1, dame noire en d8.","ar":"تقف القطع الرئيسية في الصف الخلفي والبيادق أمامها. تبدأ الملكة على مربع من لونها: البيضاء على d1 والسوداء على d8."}'::jsonb, '{"en":"Review the rule and compare it with the position. The back rank","fr":"Relisez la règle et comparez-la à la position. La première rangée","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. الصف الخلفي"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-01-q13', 'l1-01', 13, 'easy', 'multiple_choice', '{"en":"Which statement correctly describes The armies?","fr":"Quelle affirmation décrit correctement Les armées ?","ar":"أي عبارة تصف الجيشان بشكل صحيح؟"}'::jsonb, '[{"id":"a","label":{"en":"Each player begins with one king, one queen, two rooks, two bishops, two knights, and eight pawns.","fr":"Chaque joueur commence avec un roi, une dame, deux tours, deux fous, deux cavaliers et huit pions.","ar":"يبدأ كل لاعب بملك وملكة ورخّين وفيلين وحصانين وثمانية بيادق."}},{"id":"b","label":{"en":"White makes the first move, then the players alternate one move at a time.","fr":"Les Blancs jouent en premier, puis les joueurs jouent chacun leur tour.","ar":"يلعب الأبيض أولاً، ثم يتناوب اللاعبان على نقلة واحدة في كل دور."}},{"id":"c","label":{"en":"The chessboard has eight files and eight ranks, creating 64 squares.","fr":"L’échiquier compte huit colonnes et huit rangées, soit 64 cases.","ar":"تتكوّن رقعة الشطرنج من ثمانية أعمدة وثمانية صفوف، أي 64 مربعاً."}},{"id":"d","label":{"en":"Place the board with a light-colored square at each player’s lower-right corner.","fr":"Placez l’échiquier avec une case claire dans le coin inférieur droit de chaque joueur.","ar":"ضع الرقعة بحيث يكون المربع الفاتح في الزاوية اليمنى السفلية لكل لاعب."}}]'::jsonb, 'a', '{"en":"That is 16 pieces per side. The king is the piece that must be protected; the other pieces help attack, defend, and control squares.","fr":"Cela représente 16 pièces par camp. Le roi doit être protégé ; les autres pièces attaquent, défendent et contrôlent les cases.","ar":"المجموع 16 قطعة لكل لاعب. يجب حماية الملك، بينما تساعد القطع الأخرى على الهجوم والدفاع والسيطرة على المربعات."}'::jsonb, '{"en":"Review the rule and compare it with the position. The armies","fr":"Relisez la règle et comparez-la à la position. Les armées","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. الجيشان"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
