INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-01-q17', 'l1-01', 17, 'easy', 'multiple_choice', '{"en":"Which statement correctly describes Starting the game?","fr":"Quelle affirmation décrit correctement Le début de la partie ?","ar":"أي عبارة تصف بدء المباراة بشكل صحيح؟"}'::jsonb, '[{"id":"a","label":{"en":"Each back rank starts rook, knight, bishop, queen, king, bishop, knight, rook.","fr":"Chaque première rangée commence par tour, cavalier, fou, dame, roi, fou, cavalier, tour.","ar":"يبدأ الصف الخلفي بالترتيب: رخ، حصان، فيل، وزير، ملك، فيل، حصان، رخ."}},{"id":"b","label":{"en":"White makes the first move, then the players alternate one move at a time.","fr":"Les Blancs jouent en premier, puis les joueurs jouent chacun leur tour.","ar":"يلعب الأبيض أولاً، ثم يتناوب اللاعبان على نقلة واحدة في كل دور."}},{"id":"c","label":{"en":"The chessboard has eight files and eight ranks, creating 64 squares.","fr":"L’échiquier compte huit colonnes et huit rangées, soit 64 cases.","ar":"تتكوّن رقعة الشطرنج من ثمانية أعمدة وثمانية صفوف، أي 64 مربعاً."}},{"id":"d","label":{"en":"Place the board with a light-colored square at each player’s lower-right corner.","fr":"Placez l’échiquier avec une case claire dans le coin inférieur droit de chaque joueur.","ar":"ضع الرقعة بحيث يكون المربع الفاتح في الزاوية اليمنى السفلية لكل لاعب."}}]'::jsonb, 'b', '{"en":"A move is a legal action by one player. A turn is not complete until the move is made and the opponent is next to play.","fr":"Un coup est une action légale d’un joueur. Une fois le coup joué, c’est à l’adversaire de jouer.","ar":"النقلة هي حركة قانونية للاعب. بعد تنفيذها، ينتقل الدور إلى الخصم."}'::jsonb, '{"en":"Review the rule and compare it with the position. Starting the game","fr":"Relisez la règle et comparez-la à la position. Le début de la partie","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. بدء المباراة"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
