"راجع القاعدة وقارنها بالوضع على الرقعة. الصفوف"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-02-q07', 'l1-02', 7, 'medium', 'true_false', '{"en":"True or false: Ranks are the eight horizontal rows numbered 1 through 8 from White’s side toward Black.","fr":"Vrai ou faux : Les rangées sont les huit lignes horizontales numérotées de 1 à 8 depuis le côté blanc vers les Noirs.","ar":"صح أم خطأ: الصفوف هي الخطوط الأفقية الثمانية المرقّمة من 1 إلى 8 من جهة الأبيض نحو الأسود."}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'true', '{"en":"White’s pieces begin on ranks 1 and 2; Black’s begin on ranks 8 and 7. A rank keeps the same number across the board.","fr":"Les pièces blanches commencent aux rangées 1 et 2 ; les noires aux rangées 8 et 7. Une rangée garde le même numéro sur toute sa largeur.","ar":"تبدأ قطع الأبيض في الصفين 1 و2، وقطع الأسود في 8 و7. يحتفظ الصف بالرقم نفسه عبر الرقعة."}'::jsonb, '{"en":"Review the rule and compare it with the position. Ranks","fr":"Relisez la règle et comparez-la à la position. Les rangées","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. الصفوف"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-02-q08', 'l1-02', 8, 'hard', 'identify_mistake', '{"en":"A student claims: “Ranks are vertical lines named a through h.” Is the claim correct?","fr":"Un élève affirme : « Les rangées sont verticales et nommées de a à h. » Cette affirmation est-elle correcte ?","ar":"يقول طالب: «الصفوف خطوط رأسية تُسمّى من a إلى h.» هل قوله صحيح؟"}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'false', '{"en":"White’s pieces begin on ranks 1 and 2; Black’s begin on ranks 8 and 7. A rank keeps the same number across the board.","fr":"Les pièces blanches commencent aux rangées 1 et 2 ; les noires aux rangées 8 et 7. Une rangée garde le même numéro sur toute sa largeur.","ar":"تبدأ قطع الأبيض في الصفين 1 و2، وقطع الأسود في 8 و7. يحتفظ الصف بالرقم نفسه عبر الرقعة."}'::jsonb, '{"en":"Review the rule and compare it with the position. Ranks","fr":"Relisez la règle et comparez-la à la position. Les rangées","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. الصفوف"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-02-q09', 'l1-02', 9, 'easy', 'multiple_choice', '{"en":"Which statement correctly describes Naming a square?","fr":"Quelle affirmation décrit correctement Nommer une case ?","ar":"أي عبارة تصف تسمية المربع بشكل صحيح؟"}'::jsonb, '[{"id":"a","label":{"en":"From White’s side, a1 is at the lower-left and h1 is at the lower-right.","fr":"Du côté des Blancs, a1 se trouve en bas à gauche et h1 en bas à droite.","ar":"من جهة الأبيض، يقع a1 أسفل اليسار وh1 أسفل اليمين."}},{"id":"b","label":{"en":"The four central squares are d4, e4, d5, and e5.","fr":"Les quatre cases centrales sont d4, e4, d5 et e5.","ar":"مربعات الوسط الأربعة هي d4 وe4 وd5 وe5."}},{"id":"c","label":{"en":"Files are the eight vertical columns named a through h from White’s left to right.","fr":"Les colonnes sont les huit lignes verticales nommées de a à h, de gauche à droite depuis le côté blanc.","ar":"الأعمدة هي الخطوط الرأسية الثمانية من a إلى h، من اليسار إلى اليمين من جهة الأبيض."}},{"id":"d","label":{"en":"A square is written with its file letter first and its rank number second, such as e4.","fr":"Une case s’écrit avec la lettre de sa colonne puis le numéro de sa rangée, par exemple e4.","ar":"يُكتب اسم المربع بحرف العمود أولاً ثم رقم الصف، مثل e4."}}]'::jsonb, 'd', '{"en":"Coordinates identify one exact square. “e4” means the intersection of the e-file and fourth rank, not a move or a piece.","fr":"Les coordonnées désignent une seule case précise. « e4 » est l’intersection de la colonne e et de la quatrième rangée, pas un coup ni une pièce.","ar":"تحدّد الإحداثيات مربعاً واحداً بالضبط. «e4» هو تقاطع العمود e والصف الرابع، وليس نقلة أو قطعة."}'::jsonb, '{"en":"Review the rule and compare it with the position. Naming a square","fr":"Relisez la règle et comparez-la à la position. Nommer une case","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. تسمية المربع"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-02-q10', 'l1-02', 10, 'medium', 'multiple_choice', '{"en":"You are teaching a beginner about Naming a square. Which rule should they apply?","fr":"Vous expliquez Nommer une case à un débutant. Quelle règle doit-il appliquer ?","ar":"تشرح تسمية المربع لمبتدئ. ما القاعدة التي ينبغي تطبيقها؟"}'::jsonb, '[{"id":"a","label":{"en":"A square is written with its file letter first and its rank number second, such as e4.","fr":"Une case s’écrit avec la lettre de sa colonne puis le numéro de sa rangée, par exemple e4.","ar":"يُكتب اسم المربع بحرف العمود أولاً ثم رقم الصف، مثل e4."}},{"id":"b","label":{"en":"From White’s side, a1 is at the lower-left and h1 is at the lower-right.","fr":"Du côté des Blancs, a1 se trouve en bas à gauche et h1 en bas à droite.","ar":"من جهة الأبيض، يقع a1 أسفل اليسار وh1 أسفل اليمين."}},{"id":"c","label":{"en":"The four central squares are d4, e4, d5, and e5.","fr":"Les quatre cases centrales sont d4, e4, d5 et e5.","ar":"مربعات الوسط الأربعة هي d4 وe4 وd5 وe5."}},{"id":"d","label":{"en":"Files are the eight vertical columns named a through h from White’s left to right.","fr":"Les colonnes sont les huit lignes verticales nommées de a à h, de gauche à droite depuis le côté blanc.","ar":"الأعمدة هي الخطوط الرأسية الثمانية من a إلى h، من اليسار إلى اليمين من جهة الأبيض."}}]'::jsonb, 'a', '{"en":"Coordinates identify one exact square. “e4” means the intersection of the e-file and fourth rank, not a move or a piece.","fr":"Les coordonnées désignent une seule case précise. « e4 » est l’intersection de la colonne e et de la quatrième rangée, pas un coup ni une pièce.","ar":"تحدّد الإحداثيات مربعاً واحداً بالضبط. «e4» هو تقاطع العمود e والصف الرابع، وليس نقلة أو قطعة."}'::jsonb, '{"en":"Review the rule and compare it with the position. Naming a square","fr":"Relisez la règle et comparez-la à la position. Nommer une case","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. تسمية المربع"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-02-q11', 'l1-02', 11, 'medium', 'true_false', '{"en":"True or false: A square is written with its file letter first and its rank number second, such as e4.","fr":"Vrai ou faux : Une case s’écrit avec la lettre de sa colonne puis le numéro de sa rangée, par exemple e4.","ar":"صح أم خطأ: يُكتب اسم المربع بحرف العمود أولاً ثم رقم الصف، مثل e4."}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'true', '{"en":"Coordinates identify one exact square. “e4” means the intersection of the e-file and fourth rank, not a move or a piece.","fr":"Les coordonnées désignent une seule case précise. « e4 » est l’intersection de la colonne e et de la quatrième rangée, pas un coup ni une pièce.","ar":"تحدّد الإحداثيات مربعاً واحداً بالضبط. «e4» هو تقاطع العمود e والصف الرابع، وليس نقلة أو قطعة."}'::jsonb, '{"en":"Review the rule and compare it with the position. Naming a square","fr":"Relisez la règle et comparez-la à la position. Nommer une case","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. تسمية المربع"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-02-q12', 'l1-02', 12, 'hard', 'identify_mistake', '{"en":"A student claims: “A square name puts the rank number before the file letter, such as 4e.” Is the claim correct?","fr":"Un élève affirme : « Le nom d’une case place le numéro avant la lettre, comme 4e. » Cette affirmation est-elle correcte ?","ar":"يقول طالب: «يُكتب رقم الصف قبل حرف العمود، مثل 4e.» هل قوله صحيح؟"}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'false', '{"en":"Coordinates identify one exact square. “e4” means the intersection of the e-file and fourth rank, not a move or a piece.","fr":"Les coordonnées désignent une seule case précise. « e4 » est l’intersection de la colonne e et de la quatrième rangée, pas un coup ni une pièce.","ar":"تحدّد الإحداثيات مربعاً واحداً بالضبط. «e4» هو تقاطع العمود e والصف الرابع، وليس نقلة أو قطعة."}'::jsonb, '{"en":"Review the rule and compare it with the position. Naming a square","fr":"Relisez la règle et comparez-la à la position. Nommer une case","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. تسمية المربع"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-02-q13', 'l1-02', 13, 'easy', 'multiple_choice', '{"en":"Which statement correctly describes White’s perspective?","fr":"Quelle affirmation décrit correctement Le point de vue des Blancs ?","ar":"أي عبارة تصف منظور الأبيض بشكل صحيح؟"}'::jsonb, '[{"id":"a","label":{"en":"From White’s side, a1 is at the lower-left and h1 is at the lower-right.","fr":"Du côté des Blancs, a1 se trouve en bas à gauche et h1 en bas à droite.","ar":"من جهة الأبيض، يقع a1 أسفل اليسار وh1 أسفل اليمين."}},{"id":"b","label":{"en":"The four central squares are d4, e4, d5, and e5.","fr":"Les quatre cases centrales sont d4, e4, d5 et e5.","ar":"مربعات الوسط الأربعة هي d4 وe4 وd5 وe5."}},{"id":"c","label":{"en":"Files are the eight vertical columns named a through h from White’s left to right.","fr":"Les colonnes sont les huit lignes verticales nommées de a à h, de gauche à droite depuis le côté blanc.","ar":"الأعمدة هي الخطوط الرأسية الثمانية من a إلى h، من اليسار إلى اليمين من جهة الأبيض."}},{"id":"d","label":{"en":"Ranks are the eight horizontal rows numbered 1 through 8 from White’s side toward Black.","fr":"Les rangées sont les huit lignes horizontales numérotées de 1 à 8 depuis le côté blanc vers les Noirs.","ar":"الصفوف هي الخطوط الأفقية الثمانية المرقّمة من 1 إلى 8 من جهة الأبيض نحو الأسود."}}]'::jsonb, 'a', '{"en":"A board may be flipped for Black, but the square names do not change. Always use coordinates, not screen position, to describe a square.","fr":"On peut retourner l’échiquier pour les Noirs, mais les noms des cases ne changent pas. Utilisez toujours les coordonnées, pas leur position à l’écran.","ar":"يمكن قلب الرقعة للأسود، لكن أسماء المربعات لا تتغير. استخدم الإحداثيات لا موضع المربع على الشاشة."}'::jsonb, '{"en":"Review the rule and compare it with the position. White’s perspective","fr":"Relisez la règle et comparez-la à la position. Le point de vue des Blancs","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. منظور الأبيض"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
