INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-02-q16', 'l1-02', 16, 'hard', 'identify_mistake', '{"en":"A student claims: “Flipping the board changes the official names of the squares.” Is the claim correct?","fr":"Un élève affirme : « Retourner l’échiquier change le nom officiel des cases. » Cette affirmation est-elle correcte ?","ar":"يقول طالب: «قلب الرقعة يغيّر الأسماء الرسمية للمربعات.» هل قوله صحيح؟"}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'false', '{"en":"A board may be flipped for Black, but the square names do not change. Always use coordinates, not screen position, to describe a square.","fr":"On peut retourner l’échiquier pour les Noirs, mais les noms des cases ne changent pas. Utilisez toujours les coordonnées, pas leur position à l’écran.","ar":"يمكن قلب الرقعة للأسود، لكن أسماء المربعات لا تتغير. استخدم الإحداثيات لا موضع المربع على الشاشة."}'::jsonb, '{"en":"Review the rule and compare it with the position. White’s perspective","fr":"Relisez la règle et comparez-la à la position. Le point de vue des Blancs","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. منظور الأبيض"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-02-q17', 'l1-02', 17, 'easy', 'multiple_choice', '{"en":"Which statement correctly describes The center?","fr":"Quelle affirmation décrit correctement Le centre ?","ar":"أي عبارة تصف الوسط بشكل صحيح؟"}'::jsonb, '[{"id":"a","label":{"en":"A square is written with its file letter first and its rank number second, such as e4.","fr":"Une case s’écrit avec la lettre de sa colonne puis le numéro de sa rangée, par exemple e4.","ar":"يُكتب اسم المربع بحرف العمود أولاً ثم رقم الصف، مثل e4."}},{"id":"b","label":{"en":"The four central squares are d4, e4, d5, and e5.","fr":"Les quatre cases centrales sont d4, e4, d5 et e5.","ar":"مربعات الوسط الأربعة هي d4 وe4 وd5 وe5."}},{"id":"c","label":{"en":"Files are the eight vertical columns named a through h from White’s left to right.","fr":"Les colonnes sont les huit lignes verticales nommées de a à h, de gauche à droite depuis le côté blanc.","ar":"الأعمدة هي الخطوط الرأسية الثمانية من a إلى h، من اليسار إلى اليمين من جهة الأبيض."}},{"id":"d","label":{"en":"Ranks are the eight horizontal rows numbered 1 through 8 from White’s side toward Black.","fr":"Les rangées sont les huit lignes horizontales numérotées de 1 à 8 depuis le côté blanc vers les Noirs.","ar":"الصفوف هي الخطوط الأفقية الثمانية المرقّمة من 1 إلى 8 من جهة الأبيض نحو الأسود."}}]'::jsonb, 'b', '{"en":"Central squares matter because pieces placed near the center can influence more of the board. Control can come from occupying a square or attacking it.","fr":"Les cases centrales sont importantes : une pièce proche du centre peut influencer davantage l’échiquier. On peut contrôler une case en l’occupant ou en l’attaquant.","ar":"مربعات الوسط مهمة لأن القطع القريبة منها تؤثر في مساحة أكبر. يمكن السيطرة عليها باحتلالها أو مهاجمتها."}'::jsonb, '{"en":"Review the rule and compare it with the position. The center","fr":"Relisez la règle et comparez-la à la position. Le centre","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. الوسط"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
