ns utile que des pièces bien coordonnées.","ar":"قيم القطع إرشادية وليست قواعد. قوة الملكة في مدى حركتها، لكن الملكة المحاصرة قد تقل فائدتها عن قطع منسّقة."}'::jsonb, '{"en":"Review the rule and compare it with the position. Relative value","fr":"Relisez la règle et comparez-la à la position. La valeur relative","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. القيمة النسبية"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
