INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-04-q12', 'l1-04', 12, 'hard', 'identify_mistake', '{"en":"A student claims: “A queen is always worth exactly nine points in every position.” Is the claim correct?","fr":"Un élève affirme : « La dame vaut toujours exactement neuf points dans toutes les positions. » Cette affirmation est-elle correcte ?","ar":"يقول طالب: «تساوي الملكة دائماً تسع نقاط بالضبط في كل وضع.» هل قوله صحيح؟"}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'false', '{"en":"Piece values are guides, not rules. A queen is powerful because it moves far in several directions, but a trapped or inactive queen may be less useful than coordinated pieces.","fr":"Les valeurs sont des repères, pas des règles. La dame est puissante grâce à sa portée, mais une dame enfermée peut être moins utile que des pièces bien coordonnées.","ar":"قيم القطع إرشادية وليست قواعد. قوة الملكة في مدى حركتها، لكن الملكة المحاصرة قد تقل فائدتها عن قطع منسّقة."}'::jsonb, '{"en":"Review the rule and compare it with the position. Relative value","fr":"Relisez la règle et comparez-la à la position. La valeur relative","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. القيمة النسبية"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-04-q13', 'l1-04', 13, 'easy', 'multiple_choice', '{"en":"Which statement correctly describes Queen safety?","fr":"Quelle affirmation décrit correctement La sécurité de la dame ?","ar":"أي عبارة تصف سلامة الملكة بشكل صحيح؟"}'::jsonb, '[{"id":"a","label":{"en":"Before moving the queen, check whether the opponent can attack it and gain a tempo.","fr":"Avant de déplacer la dame, vérifiez si l’adversaire peut l’attaquer en gagnant un tempo.","ar":"قبل تحريك الملكة، افحص ما إذا كان الخصم يستطيع مهاجمتها وكسب نقلة."}},{"id":"b","label":{"en":"The queen is most effective when it works with other pieces rather than attacking alone.","fr":"La dame est plus efficace lorsqu’elle coopère avec les autres pièces au lieu d’attaquer seule.","ar":"تكون الملكة أكثر فاعلية عندما تنسق مع القطع الأخرى بدلاً من الهجوم وحدها."}},{"id":"c","label":{"en":"The queen moves any number of unobstructed squares along a rank, file, or diagonal.","fr":"La dame se déplace d’autant de cases libres qu’elle le souhaite sur une rangée, une colonne ou une diagonale.","ar":"تتحرك الملكة أي عدد من المربعات الخالية أفقياً أو عمودياً أو قطرياً."}},{"id":"d","label":{"en":"The queen cannot pass through any piece on its path.","fr":"La dame ne peut traverser aucune pièce placée sur son trajet.","ar":"لا تستطيع الملكة المرور عبر أي قطعة تعترض طريقها."}}]'::jsonb, 'a', '{"en":"A tempo is a useful unit of time in chess: forcing the queen to move repeatedly can help the opponent develop pieces. Calculate forcing replies before choosing an attractive queen move.","fr":"Un tempo est une unité de temps utile aux échecs : forcer la dame à bouger plusieurs fois peut aider l’adversaire à développer ses pièces. Calculez ses réponses forcées.","ar":"النقلة (tempo) وحدة زمنية مفيدة في الشطرنج؛ إجبار الملكة على التحرك مراراً قد يساعد الخصم على التطوير. احسب الردود الإجبارية قبل اختيار نقلة جذابة."}'::jsonb, '{"en":"Review the rule and compare it with the position. Queen safety","fr":"Relisez la règle et comparez-la à la position. La sécurité de la dame","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. سلامة الملكة"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-04-q14', 'l1-04', 14, 'medium', 'multiple_choice', '{"en":"You are teaching a beginner about Queen safety. Which rule should they apply?","fr":"Vous expliquez La sécurité de la dame à un débutant. Quelle règle doit-il appliquer ?","ar":"تشرح سلامة الملكة لمبتدئ. ما القاعدة التي ينبغي تطبيقها؟"}'::jsonb, '[{"id":"a","label":{"en":"The queen cannot pass through any piece on its path.","fr":"La dame ne peut traverser aucune pièce placée sur son trajet.","ar":"لا تستطيع الملكة المرور عبر أي قطعة تعترض طريقها."}},{"id":"b","label":{"en":"Before moving the queen, check whether the opponent can attack it and gain a tempo.","fr":"Avant de déplacer la dame, vérifiez si l’adversaire peut l’attaquer en gagnant un tempo.","ar":"قبل تحريك الملكة، افحص ما إذا كان الخصم يستطيع مهاجمتها وكسب نقلة."}},{"id":"c","label":{"en":"The queen is most effective when it works with other pieces rather than attacking alone.","fr":"La dame est plus efficace lorsqu’elle coopère avec les autres pièces au lieu d’attaquer seule.","ar":"تكون الملكة أكثر فاعلية عندما تنسق مع القطع الأخرى بدلاً من الهجوم وحدها."}},{"id":"d","label":{"en":"The queen moves any number of unobstructed squares along a rank, file, or diagonal.","fr":"La dame se déplace d’autant de cases libres qu’elle le souhaite sur une rangée, une colonne ou une diagonale.","ar":"تتحرك الملكة أي عدد من المربعات الخالية أفقياً أو عمودياً أو قطرياً."}}]'::jsonb, 'b', '{"en":"A tempo is a useful unit of time in chess: forcing the queen to move repeatedly can help the opponent develop pieces. Calculate forcing replies before choosing an attractive queen move.","fr":"Un tempo est une unité de temps utile aux échecs : forcer la dame à bouger plusieurs fois peut aider l’adversaire à développer ses pièces. Calculez ses réponses forcées.","ar":"النقلة (tempo) وحدة زمنية مفيدة في الشطرنج؛ إجبار الملكة على التحرك مراراً قد يساعد الخصم على التطوير. احسب الردود الإجبارية قبل اختيار نقلة جذابة."}'::jsonb, '{"en":"Review the rule and compare it with the position. Queen safety","fr":"Relisez la règle et comparez-la à la position. La sécurité de la dame","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. سلامة الملكة"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-04-q15', 'l1-04', 15, 'medium', 'true_false', '{"en":"True or false: Before moving the queen, check whether the opponent can attack it and gain a tempo.","fr":"Vrai ou faux : Avant de déplacer la dame, vérifiez si l’adversaire peut l’attaquer en gagnant un tempo.","ar":"صح أم خطأ: قبل تحريك الملكة، افحص ما إذا كان الخصم يستطيع مهاجمتها وكسب نقلة."}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'true', '{"en":"A tempo is a useful unit of time in chess: forcing the queen to move repeatedly can help the opponent develop pieces. Calculate forcing replies before choosing an attractive queen move.","fr":"Un tempo est une unité de temps utile aux échecs : forcer la dame à bouger plusieurs fois peut aider l’adversaire à développer ses pièces. Calculez ses réponses forcées.","ar":"النقلة (tempo) وحدة زمنية مفيدة في الشطرنج؛ إجبار الملكة على التحرك مراراً قد يساعد الخصم على التطوير. احسب الردود الإجبارية قبل اختيار نقلة جذابة."}'::jsonb, '{"en":"Review the rule and compare it with the position. Queen safety","fr":"Relisez la règle et comparez-la à la position. La sécurité de la dame","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. سلامة الملكة"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-04-q16', 'l1-04', 16, 'hard', 'identify_mistake', '{"en":"A student claims: “A queen cannot be attacked by a lower-valued piece.” Is the claim correct?","fr":"Un élève affirme : « Une pièce de moindre valeur ne peut pas attaquer la dame. » Cette affirmation est-elle correcte ?","ar":"يقول طالب: «لا تستطيع القطع الأقل قيمة مهاجمة الملكة.» هل قوله صحيح؟"}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'false', '{"en":"A tempo is a useful unit of time in chess: forcing the queen to move repeatedly can help the opponent develop pieces. Calculate forcing replies before choosing an attractive queen move.","fr":"Un tempo est une unité de temps utile aux échecs : forcer la dame à bouger plusieurs fois peut aider l’adversaire à développer ses pièces. Calculez ses réponses forcées.","ar":"النقلة (tempo) وحدة زمنية مفيدة في الشطرنج؛ إجبار الملكة على التحرك مراراً قد يساعد الخصم على التطوير. احسب الردود الإجبارية قبل اختيار نقلة جذابة."}'::jsonb, '{"en":"Review the rule and compare it with the position. Queen safety","fr":"Relisez la règle et comparez-la à la position. La sécurité de la dame","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. سلامة الملكة"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-04-q17', 'l1-04', 17, 'easy', 'multiple_choice', '{"en":"Which statement correctly describes Queen coordination?","fr":"Quelle affirmation décrit correctement La coordination de la dame ?","ar":"أي عبارة تصف تنسيق الملكة بشكل صحيح؟"}'::jsonb, '[{"id":"a","label":{"en":"A queen is commonly valued at about nine pawns, but its real value depends on the position.","fr":"La dame vaut souvent environ neuf pions, mais sa valeur réelle dépend de la position.","ar":"تُقدّر الملكة غالباً بنحو تسعة بيادق، لكن قيمتها الحقيقية تعتمد على الوضع."}},{"id":"b","label":{"en":"The queen is most effective when it works with other pieces rather than attacking alone.","fr":"La dame est plus efficace lorsqu’elle coopère avec les autres pièces au lieu d’attaquer seule.","ar":"تكون الملكة أكثر فاعلية عندما تنسق مع القطع الأخرى بدلاً من الهجوم وحدها."}},{"id":"c","label":{"en":"The queen moves any number of unobstructed squares along a rank, file, or diagonal.","fr":"La dame se déplace d’autant de cases libres qu’elle le souhaite sur une rangée, une colonne ou une diagonale.","ar":"تتحرك الملكة أي عدد من المربعات الخالية أفقياً أو عمودياً أو قطرياً."}},{"id":"d","label":{"en":"The queen cannot pass through any piece on its path.","fr":"La dame ne peut traverser aucune pièce placée sur son trajet.","ar":"لا تستطيع الملكة المرور عبر أي قطعة تعترض طريقها."}}]'::jsonb, 'b', '{"en":"A supported queen can create threats on several lines. Bring minor pieces into play first so the queen has safe squares and targets to combine against.","fr":"Une dame soutenue peut créer des menaces sur plusieurs lignes. Développez d’abord les pièces mineures pour lui offrir des cases sûres et des cibles communes.","ar":"تستطيع الملكة المدعومة صنع تهديدات على عدة خطوط. طوّر القطع الصغيرة أولاً لتجد الملكة مربعات آمنة وأهدافاً مشتركة."}'::jsonb, '{"en":"Review the rule and compare it with the position. Queen coordination","fr":"Relisez la règle et comparez-la à la position. La coordination de la dame","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. تنسيق الملكة"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-04-q18', 'l1-04', 18, 'medium', 'multiple_choice', '{"en":"You are teaching a beginner about Queen coordination. Which rule should they apply?","fr":"Vous expliquez La coordination de la dame à un débutant. Quelle règle doit-il appliquer ?","ar":"تشرح تنسيق الملكة لمبتدئ. ما القاعدة التي ينبغي تطبيقها؟"}'::jsonb, '[{"id":"a","label":{"en":"The queen cannot pass through any piece on its path.","fr":"La dame ne peut traverser aucune pièce placée sur son trajet.","ar":"لا تستطيع الملكة المرور عبر أي قطعة تعترض طريقها."}},{"id":"b","label":{"en":"A queen is commonly valued at about nine pawns, but its real value depends on the position.","fr":"La dame vaut souvent environ neuf pions, mais sa valeur réelle dépend de la position.","ar":"تُقدّر الملكة غالباً بنحو تسعة بيادق، لكن قيمتها الحقيقية تعتمد على الوضع."}},{"id":"c","label":{"en":"The queen is most effective when it works with other pieces rather than attacking alone.","fr":"La dame est plus efficace lorsqu’elle coopère avec les autres pièces au lieu d’attaquer seule.","ar":"تكون الملكة أكثر فاعلية عندما تنسق مع القطع الأخرى بدلاً من الهجوم وحدها."}},{"id":"d","label":{"en":"The queen moves any number of unobstructed squares along a rank, file, or diagonal.","fr":"La dame se déplace d’autant de cases libres qu’elle le souhaite sur une rangée, une colonne ou une diagonale.","ar":"تتحرك الملكة أي عدد من المربعات الخالية أفقياً أو عمودياً أو قطرياً."}}]'::jsonb, 'c', '{"en":"A supported queen can create threats on several lines. Bring minor pieces into play first so the queen has safe squares and targets to combine against.","fr":"Une dame soutenue peut créer des menaces sur plusieurs lignes. Développez d’abord les pièces mineures pour lui offrir des cases sûres et des cibles communes.","ar":"تستطيع الملكة المدعومة صنع تهديدات على عدة خطوط. طوّر القطع الصغيرة أولاً لتجد الملكة مربعات آمنة وأهدافاً مشتركة."}'::jsonb, '{"en":"Review the rule and compare it with the position. Queen coordination","fr":"Relisez la règle et comparez-la à la position. La coordination de la dame","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. تنسيق الملكة"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-04-q19', 'l1-04', 19, 'medium', 'true_false', '{"en":"True or false: The queen is most effective when it works with other pieces rather than attacking alone.","fr":"Vrai ou faux : La dame est plus efficace lorsqu’elle coopère avec les autres pièces au lieu d’attaquer seule.","ar":"صح أم خطأ: تكون الملكة أكثر فاعلية عندما تنسق مع القطع الأخرى بدلاً من الهجوم وحدها."}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'true', '{"en":"A supported queen can create threats on several lines. Bring minor pieces into play first so the queen has safe squares and targets to combine against.","fr":"Une dame soutenue peut créer des menaces sur plusieurs lignes. Développez d’abord les pièces mineures pour lui offrir des cases sûres et des cibles communes.","ar":"تستطيع الملكة المدعومة صنع تهديدات على عدة خطوط. طوّر القطع الصغيرة أولاً لتجد الملكة مربعات آمنة وأهدافاً مشتركة."}'::jsonb, '{"en":"Review the rule and compare it with the position. Queen coordination","fr":"Relisez la règle et comparez-la à la position. La coordination de la dame","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. تنسيق الملكة"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-04-q20', 'l1-04', 20, 'hard', 'best_move', '{"en":"On the board, make a legal move that demonstrates Queen coordination.","fr":"Sur l’échiquier, jouez un coup légal qui illustre La coordination de la dame.","ar":"نفّذ على الرقعة نقلة قانونية توضح تنسيق الملكة."}'::jsonb, '[{"id":"Qa4","label":{"en":"Qa4","fr":"Qa4","ar":"Qa4"}},{"id":"Qh5+","label":{"en":"Qh5+","fr":"Qh5+","ar":"Qh5+"}},{"id":"Qc2","label":{"en":"Qc2","fr":"Qc2","ar":"Qc2"}},{"id":"Qb3","label":{"en":"Qb3","fr":"Qb3","ar":"Qb3"}}]'::jsonb, 'Qh5+', '{"en":"Qh5+ demonstrates the queen’s diagonal movement followed by a check along the h-file.","fr":"Qh5+ montre le déplacement diagonal de la dame, qui donne ensuite échec sur la colonne h.","ar":"تُظهر Qh5+ الحركة القطرية للملكة ثم الكش على عمود h."}'::jsonb, '{"en":"Review the rule and compare it with the position. Queen coordination","fr":"Relisez la règle et comparez-la à la position. La coordination de la dame","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. تنسيق الملكة"}'::jsonb, '7k/8/8/8/8/8/8/3QK3 w - - 0 1', '["Qh5+"]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_lessons (id, level_number, lesson_number, title, summary, content, published) VALUES ('l1-05', 1, 5, '{"en":"The Rook: Movement and Strategies","fr":"La tour : déplacements et stratégies","ar":"الرخ: الحركة والاستراتيجيات"}'::jsonb, '{"en":"Understand rook lines, open files, and why rooks become powerful when connected.","fr":"Comprenez les lignes de la tour, les colonnes ouvertes et la coordination des tours.","ar":"افهم خطوط الرخ والأعمدة المفتوحة وقوة تنسيق الرخين."}'::jsonb, '{"objectives":[{"en":"Rook movement","fr":"Le déplacement de la tour","ar":"حركة الرخ"},{"en":"Open files","fr":"Les colonnes ouvertes","ar":"الأعمدة المفتوحة"},{"en":"Relative value","fr":"La valeur relative","ar":"القيمة النسبية"},{"en":"Connected rooks","fr":"Les tours reliées","ar":"الرخان المتصلان"},{"en":"Rook activity","fr":"L’activité de la tour","ar":"نشاط الرخ"}],"sections":[{"title":{"en":"Rook movement","fr":"Le déplacement de la tour","ar":"حركة الرخ"},"paragraphs":[{"en":"A rook moves any number of unobstructed squares along a rank or file.","fr":"La tour se déplace d’autant de cases libres qu’elle le souhaite sur une rangée ou une colonne.","ar":"يتحرك الرخ أي عدد من المربعات الخالية أفقياً أو عمودياً."},{"en":"The rook does not move diagonally and cannot jump. It may capture an enemy piece on its line if no piece blocks the route first.","fr":"La tour ne se déplace pas en diagonale et ne saute pas. Elle peut capturer une pièce adverse sur sa ligne si aucune pièce ne bloque le passage.","ar":"لا يتحرك الرخ قطرياً ولا يقفز. يمكنه أسر قطعة على خطه إذا لم تعترضه قطعة أخرى."},{"en":"Practice checkpoint: identify Rook movement on a board, explain the rule, and check how the opponent could respond.","fr":"Mise en pratique : repérez Le déplacement de la tour sur un échiquier, expliquez la règle et vérifiez la réponse possible de l’adversaire.","ar":"تطبيق عملي: حدّد حركة الرخ على الرقعة، واشرح القاعدة، ثم تحقّق من رد الخصم الممكن."}]},{"title":{"en":"Open files","fr":"Les colonnes ouvertes","ar":"الأعمدة المفتوحة"},"paragraphs":[{"en":"An open file has no pawns on it and can be a useful route for a rook.","fr":"Une colonne ouverte ne contient aucun pion et peut offrir une voie utile à la tour.","ar":"العمود المفتوح لا يحتوي على بيادق وقد يوفر طريقاً مفيداً للرخ."},{"en":"A rook on an open file can pressure squares and targets along that file. A half-open file has no friendly pawn but may still contain an enemy pawn.","fr":"Une tour sur une colonne ouverte peut exercer une pression le long de celle-ci. Une colonne semi-ouverte ne contient pas de pion ami, mais peut contenir un pion adverse.","ar":"يستطيع الرخ على العمود المفتوح الضغط على أهدافه. أما العمود شبه المفتوح فيخلو من بيدقك لكنه قد يحتوي بيدق الخصم."},{"en":"Practice checkpoint: identify Open files on a board, explain the rule, and check how the opponent could respond.","fr":"Mise en pratique : repérez Les colonnes ouvertes sur un échiquier, expliquez la règle et vérifiez la réponse possible de l’adversaire.","ar":"تطبيق عملي: حدّد الأعمدة المفتوحة على الرقعة، واشرح القاعدة، ثم تحقّق من رد الخصم الممكن."}]},{"title":{"en":"Relative value","fr":"La valeur relative","ar":"القيمة النسبية"},"paragraphs":[{"en":"A rook is commonly valued at about five pawns, although its activity can change its practical value.","fr":"La tour vaut souvent environ cinq pions, mais son activité modifie sa valeur pratique.","ar":"تُقدّر قيمة الرخ غالباً بنحو خمسة بيادق، لكن نشاطه يؤثر في قيمته العملية."},{"en":"A rook often becomes stronger when files open and passed pawns appear. Do not trade a rook only by counting points; compare activity, king safety, and targets.","fr":"La tour devient souvent plus forte lorsque les colonnes s’ouvrent et que des pions passés apparaissent. Évaluez aussi son activité, la sécurité des rois et les cibles.","ar":"غالباً ما يقوى الرخ عند انفتاح الأعمدة وظهور البيادق المارة. لا تقيّم التبديل بالنقاط وحدها؛ قارن النشاط وأمان الملك والأهداف."},{"en":"Practice checkpoint: identify Relative value on a board, explain the rule, and check how the opponent could respond.","fr":"Mise en pratique : repérez La valeur relative sur un échiquier, expliquez la règle et vérifiez la réponse possible de l’adversaire.","ar":"تطبيق عملي: حدّد القيمة النسبية على الرقعة، واشرح القاعدة، ثم تحقّق من رد الخصم الممكن."}]},{"title":{"en":"Connected rooks","fr":"Les tours reliées","ar":"الرخان المتصلان"},"paragraphs":[{"en":"Rooks are connected when no pieces remain between them on their shared rank or file.","fr":"Les tours sont reliées lorsqu’aucune pièce ne se trouve entre elles sur leur rangée ou colonne commune.","ar":"يكون الرخان متصلين عندما لا توجد قطع بينهما على الصف أو العمود المشترك."},{"en":"Connected rooks can defend one another and coordinate against a file or target. Castling and developing the minor pieces often help clear the back rank.","fr":"Des tours reliées se défendent et peuvent coordonner leurs attaques. Le roque et le développement des pièces mineures aident souvent à libérer la première rangée.","ar":"يدافع الرخان المتصلان أحدهما عن الآخر وينسّقان الهجوم على عمود أو هدف. يساعد التبييت وتطوير القطع الصغيرة على إخلاء الصف الخلفي."},{"en":"Practice checkpoint: identify Connected rooks on a board, explain the rule, and check how the opponent could respond.","fr":"Mise en pratique : repérez Les tours reliées sur un échiquier, expliquez la règle et vérifiez la réponse possible de l’adversaire.","ar":"تطبيق عملي: حدّد الرخان المتصلان على الرقعة، واشرح القاعدة، ثم تحقّق من رد الخصم الممكن."}]},{"title":{"en":"Rook activity","fr":"L’activité de la tour","ar":"نشاط الرخ"},"paragraphs":[{"en":"A rook is often more active behind a passed pawn, where it can support its advance or attack it.","fr":"Une tour est souvent active derrière un pion passé, qu’elle peut soutenir ou attaquer.","ar":"يكون الرخ نشطاً غالباً خلف البيدق المار، فيدعمه أو يهاجمه."},{"en":"The “behind the passed pawn” rule is a useful guideline, not an absolute law. Check whether the rook can reach the file, protect the king, and create threats before committing.","fr":"La règle « derrière le pion passé » est un bon principe, pas une loi absolue. Vérifiez l’accès à la colonne, la sécurité du roi et les menaces possibles.","ar":"قاعدة «الرخ خلف البيدق المار» إرشاد وليست قانوناً مطلقاً. افحص إمكانية الوصول إلى العمود وأمان الملك والتهديدات قبل الالتزام."},{"en":"Practice checkpoint: identify Rook activity on a board, explain the rule, and check how the opponent could respond.","fr":"Mise en pratique : repérez L’activité de la tour sur un échiquier, expliquez la règle et vérifiez la réponse possible de l’adversaire.","ar":"تطبيق عملي: حدّد نشاط الرخ على الرقعة، واشرح القاعدة، ثم تحقّق من رد الخصم الممكن."}]}],"terminology":[{"term":{"en":"Rook movement","fr":"Le déplacement de la tour","ar":"حركة الرخ"},"definition":{"en":"A rook moves any number of unobstructed squares along a rank or file.","fr":"La tour se déplace d’autant de cases libres qu’elle le souhaite sur une rangée ou une colonne.","ar":"يتحرك الرخ أي عدد من المربعات الخالية أفقياً أو عمودياً."}},{"term":{"en":"Open files","fr":"Les colonnes ouvertes","ar":"الأعمدة المفتوحة"},"definition":{"en":"An open file has no pawns on it and can be a useful route for a rook.","fr":"Une colonne ouverte ne contient aucun pion et peut offrir une voie utile à la tour.","ar":"العمود المفتوح لا يحتوي على بيادق وقد يوفر طريقاً مفيداً للرخ."}},{"term":{"en":"Relative value","fr":"La valeur relative","ar":"القيمة النسبية"},"definition":{"en":"A rook is commonly valued at about five pawns, although its activity can change its practical value.","fr":"La tour vaut souvent environ cinq pions, mais son activité modifie sa valeur pratique.","ar":"تُقدّر قيمة الرخ غالباً بنحو خمسة بيادق، لكن نشاطه يؤثر في قيمته العملية."}},{"term":{"en":"Connected rooks","fr":"Les tours reliées","ar":"الرخان المتصلان"},"definition":{"en":"Rooks are connected when no pieces remain between them on their shared rank or file.","fr":"Les tours sont reliées lorsqu’aucune pièce ne se trouve entre elles sur leur rangée ou colonne commune.","ar":"يكون الرخان متصلين عندما لا توجد قطع بينهما على الصف أو العمود المشترك."}},{"term":{"en":"Rook activity","fr":"L’activité de la tour","ar":"نشاط الرخ"},"definition":{"en":"A rook is often more active behind a passed pawn, where it can support its advance or attack it.","fr":"Une tour est souvent active derrière un pion passé, qu’elle peut soutenir ou attaquer.","ar":"يكون الرخ نشطاً غالباً خلف البيدق المار، فيدعمه أو يهاجمه."}}],"example":{"fen":"7k/8/8/8/8/8/8/R3K3 w - - 0 1","solutionMoves":["Ra8+"],"annotation":{"en":"Ra8+ travels along an open file and checks the king across the eighth rank.","fr":"Ra8+ suit une colonne ouverte et met le roi en échec sur la huitième rangée.","ar":"تتحرك Ra8+ على عمود مفتوح وتكش الملك عبر الصف الثامن."}},"commonMistakes":[{"en":"A rook moves diagonally and can jump over a piece.","fr":"La tour se déplace en diagonale et peut sauter par-dessus une pièce.","ar":"يتحرك الرخ قطرياً ويستطيع القفز فوق قطعة."},{"en":"A file is open whenever it contains no rooks.","fr":"Une colonne est ouverte dès qu’elle ne contient aucune tour.","ar":"يكون العمود مفتوحاً كلما خلا من الرخاخ."},{"en":"A rook is worth three pawns in every position.","fr":"La tour vaut trois pions dans toutes les positions.","ar":"تساوي قيمة الرخ ثلاثة بيادق في كل وضع."},{"en":"Rooks are connected whenever they are on different files.","fr":"Les tours sont reliées dès qu’elles se trouvent sur des colonnes différentes.","ar":"يكون الرخان متصلين بمجرد وجودهما على عمودين مختلفين."},{"en":"A rook should always stand in front of its own passed pawn.","fr":"Une tour doit toujours se placer devant son propre pion passé.","ar":"ينبغي للرخ دائماً الوقوف أمام بيدقه المار."}],"professionalTips":[{"en":"Before moving, pause and ask how Rook movement affects your king safety and your opponent’s best reply.","fr":"Avant de jouer, demandez-vous comment Le déplacement de la tour influence la sécurité de votre roi et la meilleure réponse adverse.","ar":"قبل أن تلعب، فكّر كيف يؤثر حركة الرخ في أمان ملكك وفي أفضل رد للخصم."},{"en":"Before moving, pause and ask how Open files affects your king safety and your opponent’s best reply.","fr":"Avant de jouer, demandez-vous comment Les colonnes ouvertes influence la sécurité de votre roi et la meilleure réponse adverse.","ar":"قبل أن تلعب، فكّر كيف يؤثر الأعمدة المفتوحة في أمان ملكك وفي أفضل رد للخصم."},{"en":"Before moving, pause and ask how Relative value affects your king safety and your opponent’s best reply.","fr":"Avant de jouer, demandez-vous comment La valeur relative influence la sécurité de votre roi et la meilleure réponse adverse.","ar":"قبل أن تلعب، فكّر كيف يؤثر القيمة النسبية في أمان ملكك وفي أفضل رد للخصم."},{"en":"Before moving, pause and ask how Connected rooks affects your king safety and your opponent’s best reply.","fr":"Avant de jouer, demandez-vous comment Les tours reliées influence la sécurité de votre roi et la meilleure réponse adverse.","ar":"قبل أن تلعب، فكّر كيف يؤثر الرخان المتصلان في أمان ملكك وفي أفضل رد للخصم."},{"en":"Before moving, pause and ask how Rook activity affects your king safety and your opponent’s best reply.","fr":"Avant de jouer, demandez-vous comment L’activité de la tour influence la sécurité de votre roi et la meilleure réponse adverse.","ar":"قبل أن تلعب، فكّر كيف يؤثر نشاط الرخ في أمان ملكك وفي أفضل رد للخصم."}],"exercises":[{"en":"Set up a position that demonstrates Rook movement. Name the legal choices and explain why one choice follows the rule.","fr":"Préparez une position illustrant Le déplacement de la tour. Indiquez les choix légaux et expliquez lequel respecte la règle.","ar":"أنشئ وضعية توضّح حركة الرخ. اذكر النقلات القانونية واشرح لماذا تتبع إحداها القاعدة."},{"en":"Set up a position that demonstrates Open files. Name the legal choices and explain why one choice follows the rule.","fr":"Préparez une position illustrant Les colonnes ouvertes. Indiquez les choix légaux et expliquez lequel respecte la règle.","ar":"أنشئ وضعية توضّح الأعمدة المفتوحة. اذكر النقلات القانونية واشرح لماذا تتبع إحداها القاعدة."},{"en":"Set up a position that demonstrates Relative value. Name the legal choices and explain why one choice follows the rule.","fr":"Préparez une position illustrant La valeur relative. Indiquez les choix légaux et expliquez lequel respecte la règle.","ar":"أنشئ وضعية توضّح القيمة النسبية. اذكر النقلات القانونية واشرح لماذا تتبع إحداها القاعدة."},{"en":"Set up a position that demonstrates Connected rooks. Name the legal choices and explain why one choice follows the rule.","fr":"Préparez une position illustrant Les tours reliées. Indiquez les choix légaux et expliquez lequel respecte la règle.","ar":"أنشئ وضعية توضّح الرخان المتصلان. اذكر النقلات القانونية واشرح لماذا تتبع إحداها القاعدة."},{"en":"Set up a position that demonstrates Rook activity. Name the legal choices and explain why one choice follows the rule.","fr":"Préparez une position illustrant L’activité de la tour. Indiquez les choix légaux et expliquez lequel respecte la règle.","ar":"أنشئ وضعية توضّح نشاط الرخ. اذكر النقلات القانونية واشرح لماذا تتبع إحداها القاعدة."}],"takeaways":[{"en":"A rook moves any number of unobstructed squares along a rank or file.","fr":"La tour se déplace d’autant de cases libres qu’elle le souhaite sur une rangée ou une colonne.","ar":"يتحرك الرخ أي عدد من المربعات الخالية أفقياً أو عمودياً."},{"en":"An open file has no pawns on it and can be a useful route for a rook.","fr":"Une colonne ouverte ne contient aucun pion et peut offrir une voie utile à la tour.","ar":"العمود المفتوح لا يحتوي على بيادق وقد يوفر طريقاً مفيداً للرخ."},{"en":"A rook is commonly valued at about five pawns, although its activity can change its practical value.","fr":"La tour vaut souvent environ cinq pions, mais son activité modifie sa valeur pratique.","ar":"تُقدّر قيمة الرخ غالباً بنحو خمسة بيادق، لكن نشاطه يؤثر في قيمته العملية."},{"en":"Rooks are connected when no pieces remain between them on their shared rank or file.","fr":"Les tours sont reliées lorsqu’aucune pièce ne se trouve entre elles sur leur rangée ou colonne commune.","ar":"يكون الرخان متصلين عندما لا توجد قطع بينهما على الصف أو العمود المشترك."},{"en":"A rook is often more active behind a passed pawn, where it can support its advance or attack it.","fr":"Une tour est souvent active derrière un pion passé, qu’elle peut soutenir ou attaquer.","ar":"يكون الرخ نشطاً غالباً خلف البيدق المار، فيدعمه أو يهاجمه."}]}'::jsonb, TRUE) ON CONFLICT (id) DO UPDATE SET level_number = EXCLUDED.level_number, lesson_number = EXCLUDED.lesson_number, title = EXCLUDED.title, summary = EXCLUDED.summary, content = EXCLUDED.content, published = TRUE, updated_at = NOW();
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-05-q01', 'l1-05', 1, 'easy', 'multiple_choice', '{"en":"Which statement correctly describes Rook movement?","fr":"Quelle affirmation décrit correctement Le déplacement de la tour ?","ar":"أي عبارة تصف حركة الرخ بشكل صحيح؟"}'::jsonb, '[{"id":"a","label":{"en":"Rooks are connected when no pieces remain between them on their shared rank or file.","fr":"Les tours sont reliées lorsqu’aucune pièce ne se trouve entre elles sur leur rangée ou colonne commune.","ar":"يكون الرخان متصلين عندما لا توجد قطع بينهما على الصف أو العمود المشترك."}},{"id":"b","label":{"en":"A rook moves any number of unobstructed squares along a rank or file.","fr":"La tour se déplace d’autant de cases libres qu’elle le souhaite sur une rangée ou une colonne.","ar":"يتحرك الرخ أي عدد من المربعات الخالية أفقياً أو عمودياً."}},{"id":"c","label":{"en":"An open file has no pawns on it and can be a useful route for a rook.","fr":"Une colonne ouverte ne contient aucun pion et peut offrir une voie utile à la tour.","ar":"العمود المفتوح لا يحتوي على بيادق وقد يوفر طريقاً مفيداً للرخ."}},{"id":"d","label":{"en":"A rook is commonly valued at about five pawns, although its activity can change its practical value.","fr":"La tour vaut souvent environ cinq pions, mais son activité modifie sa valeur pratique.","ar":"تُقدّر قيمة الرخ غالباً بنحو خمسة بيادق، لكن نشاطه يؤثر في قيمته العملية."}}]'::jsonb, 'b', '{"en":"The rook does not move diagonally and cannot jump. It may capture an enemy piece on its line if no piece blocks the route first.","fr":"La tour ne se déplace pas en diagonale et ne saute pas. Elle peut capturer une pièce adverse sur sa ligne si aucune pièce ne bloque le passage.","ar":"لا يتحرك الرخ قطرياً ولا يقفز. يمكنه أسر قطعة على خطه إذا لم تعترضه قطعة أخرى."}'::jsonb, '{"en":"Review the rule and compare it with the position. Rook movement","fr":"Relisez la règle et comparez-la à la position. Le déplacement de la tour","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. حركة الرخ"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-05-q02', 'l1-05', 2, 'medium', 'multiple_choice', '{"en":"You are teaching a beginner about Rook movement. Which rule should they apply?","fr":"Vous expliquez Le déplacement de la tour à un débutant. Quelle règle doit-il appliquer ?","ar":"تشرح حركة الرخ لمبتدئ. ما القاعدة التي ينبغي تطبيقها؟"}'::jsonb, '[{"id":"a","label":{"en":"A rook is commonly valued at about five pawns, although its activity can change its practical value.","fr":"La tour vaut souvent environ cinq pions, mais son activité modifie sa valeur pratique.","ar":"تُقدّر قيمة الرخ غالباً بنحو خمسة بيادق، لكن نشاطه يؤثر في قيمته العملية."}},{"id":"b","label":{"en":"Rooks are connected when no pieces remain between them on their shared rank or file.","fr":"Les tours sont reliées lorsqu’aucune pièce ne se trouve entre elles sur leur rangée ou colonne commune.","ar":"يكون الرخان متصلين عندما لا توجد قطع بينهما على الصف أو العمود المشترك."}},{"id":"c","label":{"en":"A rook moves any number of unobstructed squares along a rank or file.","fr":"La tour se déplace d’autant de cases libres qu’elle le souhaite sur une rangée ou une colonne.","ar":"يتحرك الرخ أي عدد من المربعات الخالية أفقياً أو عمودياً."}},{"id":"d","label":{"en":"An open file has no pawns on it and can be a useful route for a rook.","fr":"Une colonne ouverte ne contient aucun pion et peut offrir une voie utile à la tour.","ar":"العمود المفتوح لا يحتوي على بيادق وقد يوفر طريقاً مفيداً للرخ."}}]'::jsonb, 'c', '{"en":"The rook does not move diagonally and cannot jump. It may capture an enemy piece on its line if no piece blocks the route first.","fr":"La tour ne se déplace pas en diagonale et ne saute pas. Elle peut capturer une pièce adverse sur sa ligne si aucune pièce ne bloque le passage.","ar":"لا يتحرك الرخ قطرياً ولا يقفز. يمكنه أسر قطعة على خطه إذا لم تعترضه قطعة أخرى."}'::jsonb, '{"en":"Review the rule and compare it with the position. Rook movement","fr":"Relisez la règle et comparez-la à la position. Le déplacement de la tour","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. حركة الرخ"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-05-q03', 'l1-05', 3, 'medium', 'true_false', '{"en":"True or false: A rook moves any number of unobstructed squares along a rank or file.","fr":"Vrai ou faux : La tour se déplace d’autant de cases libres qu’elle le souhaite sur une rangée ou une colonne.","ar":"صح أم خطأ: يتحرك الرخ أي عدد من المربعات الخالية أفقياً أو عمودياً."}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'true', '{"en":"The rook does not move diagonally and cannot jump. It may capture an enemy piece on its line if no piece blocks the route first.","fr":"La tour ne se déplace pas en diagonale et ne saute pas. Elle peut capturer une pièce adverse sur sa ligne si aucune pièce ne bloque le passage.","ar":"لا يتحرك الرخ قطرياً ولا يقفز. يمكنه أسر قطعة على خطه إذا لم تعترضه قطعة أخرى."}'::jsonb, '{"en":"Review the rule and compare it with the position. Rook movement","fr":"Relisez la règle et comparez-la à la position. Le déplacement de la tour","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. حركة الرخ"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-05-q04', 'l1-05', 4, 'hard', 'identify_mistake', '{"en":"A student claims: “A rook moves diagonally and can jump over a piece.” Is the claim correct?","fr":"Un élève affirme : « La tour se déplace en diagonale et peut sauter par-dessus une pièce. » Cette affirmation est-elle correcte ?","ar":"يقول طالب: «يتحرك الرخ قطرياً ويستطيع القفز فوق قطعة.» هل قوله صحيح؟"}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'false', '{"en":"The rook does not move diagonally and cannot jump. It may capture an enemy piece on its line if no piece blocks the route first.","fr":"La tour ne se déplace pas en diagonale et ne saute pas. Elle peut capturer une pièce adverse sur sa ligne si aucune pièce ne bloque le passage.","ar":"لا يتحرك الرخ قطرياً ولا يقفز. يمكنه أسر قطعة على خطه إذا لم تعترضه قطعة أخرى."}'::jsonb, '{"en":"Review the rule and compare it with the position. Rook movement","fr":"Relisez la règle et comparez-la à la position. Le déplacement de la tour","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. حركة الرخ"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-05-q05', 'l1-05', 5, 'easy', 'multiple_choice', '{"en":"Which statement correctly describes Open files?","fr":"Quelle affirmation décrit correctement Les colonnes ouvertes ?","ar":"أي عبارة تصف الأعمدة المفتوحة بشكل صحيح؟"}'::jsonb, '[{"id":"a","label":{"en":"Rooks are connected when no pieces remain between them on their shared rank or file.","fr":"Les tours sont reliées lorsqu’aucune pièce ne se trouve entre elles sur leur rangée ou colonne commune.","ar":"يكون الرخان متصلين عندما لا توجد قطع بينهما على الصف أو العمود المشترك."}},{"id":"b","label":{"en":"A rook is often more active behind a passed pawn, where it can support its advance or attack it.","fr":"Une tour est souvent active derrière un pion passé, qu’elle peut soutenir ou attaquer.","ar":"يكون الرخ نشطاً غالباً خلف البيدق المار، فيدعمه أو يهاجمه."}},{"id":"c","label":{"en":"An open file has no pawns on it and can be a useful route for a rook.","fr":"Une colonne ouverte ne contient aucun pion et peut offrir une voie utile à la tour.","ar":"العمود المفتوح لا يحتوي على بيادق وقد يوفر طريقاً مفيداً للرخ."}},{"id":"d","label":{"en":"A rook is commonly valued at about five pawns, although its activity can change its practical value.","fr":"La tour vaut souvent environ cinq pions, mais son activité modifie sa valeur pratique.","ar":"تُقدّر قيمة الرخ غالباً بنحو خمسة بيادق، لكن نشاطه يؤثر في قيمته العملية."}}]'::jsonb, 'c', '{"en":"A rook on an open file can pressure squares and targets along that file. A half-open file has no friendly pawn but may still contain an enemy pawn.","fr":"Une tour sur une colonne ouverte peut exercer une pression le long de celle-ci. Une colonne semi-ouverte ne contient pas de pion ami, mais peut contenir un pion adverse.","ar":"يستطيع الرخ على العمود المفتوح الضغط على أهدافه. أما العمود شبه المفتوح فيخلو من بيدقك لكنه قد يحتوي بيدق الخصم."}'::jsonb, '{"en":"Review the rule and compare it with the position. Open files","fr":"Relisez la règle et comparez-la à la position. Les colonnes ouvertes","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. الأعمدة المفتوحة"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-05-q06', 'l1-05', 6, 'medium', 'multiple_choice', '{"en":"You are teaching a beginner about Open files. Which rule should they apply?","fr":"Vous expliquez Les colonnes ouvertes à un débutant. Quelle règle doit-il appliquer ?","ar":"تشرح الأعمدة المفتوحة لمبتدئ. ما القاعدة التي ينبغي تطبيقها؟"}'::jsonb, '[{"id":"a","label":{"en":"A rook is commonly valued at about five pawns, although its activity can change its practical value.","fr":"La tour vaut souvent environ cinq pions, mais son activité modifie sa valeur pratique.","ar":"تُقدّر قيمة الرخ غالباً بنحو خمسة بيادق، لكن نشاطه يؤثر في قيمته العملية."}},{"id":"b","label":{"en":"Rooks are connected when no pieces remain between them on their shared rank or file.","fr":"Les tours sont reliées lorsqu’aucune pièce ne se trouve entre elles sur leur rangée ou colonne commune.","ar":"يكون الرخان متصلين عندما لا توجد قطع بينهما على الصف أو العمود المشترك."}},{"id":"c","label":{"en":"A rook is often more active behind a passed pawn, where it can support its advance or attack it.","fr":"Une tour est souvent active derrière un pion passé, qu’elle peut soutenir ou attaquer.","ar":"يكون الرخ نشطاً غالباً خلف البيدق المار، فيدعمه أو يهاجمه."}},{"id":"d","label":{"en":"An open file has no pawns on it and can be a useful route for a rook.","fr":"Une colonne ouverte ne contient aucun pion et peut offrir une voie utile à la tour.","ar":"العمود المفتوح لا يحتوي على بيادق وقد يوفر طريقاً مفيداً للرخ."}}]'::jsonb, 'd', '{"en":"A rook on an open file can pressure squares and targets along that file. A half-open file has no friendly pawn but may still contain an enemy pawn.","fr":"Une tour sur une colonne ouverte peut exercer une pression le long de celle-ci. Une colonne semi-ouverte ne contient pas de pion ami, mais peut contenir un pion adverse.","ar":"يستطيع الرخ على العمود المفتوح الضغط على أهدافه. أما العمود شبه المفتوح فيخلو من بيدقك لكنه قد يحتوي بيدق الخصم."}'::jsonb, '{"en":"Review the rule and compare it with the position. Open files","fr":"Relisez la règle et comparez-la à la position. Les colonnes ouvertes","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. الأعمدة المفتوحة"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-05-q07', 'l1-05', 7, 'medium', 'true_false', '{"en":"True or false: An open file has no pawns on it and can be a useful route for a rook.","fr":"Vrai ou faux : Une colonne ouverte ne contient aucun pion et peut offrir une voie utile à la tour.","ar":"صح أم خطأ: العمود المفتوح لا يحتوي على بيادق وقد يوفر طريقاً مفيداً للرخ."}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'true', '{"en":"A rook on an open file can pressure squares and targets along that file. A half-open file has no friendly pawn but may still contain an enemy pawn.","fr":"Une tour sur une colonne ouverte peut exercer une pression le long de celle-ci. Une colonne semi-ouverte ne contient pas de pion ami, mais peut contenir un pion adverse.","ar":"يستطيع الرخ على العمود المفتوح الضغط على أهدافه. أما العمود شبه المفتوح فيخلو من بيدقك لكنه قد يحتوي بيدق الخصم."}'::jsonb, '{"en":"Review the rule and compare it with the position. Open files","fr":"Relisez la règle et comparez-la à la position. Les colonnes ouvertes","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. الأعمدة المفتوحة"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-05-q08', 'l1-05', 8, 'hard', 'identify_mistake', '{"en":"A student claims: “A file is open whenever it contains no rooks.” Is the claim correct?","fr":"Un élève affirme : « Une colonne est ouverte dès qu’elle ne contient aucune tour. » Cette affirmation est-elle correcte ?","ar":"يقول طالب: «يكون العمود مفتوحاً كلما خلا من الرخاخ.» هل قوله صحيح؟"}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'false', '{"en":"A rook on an open file can pressure squares and targets along that file. A half-open file has no friendly pawn but may still contain an enemy pawn.","fr":"Une tour sur une colonne ouverte peut exercer une pression le long de celle-ci. Une colonne semi-ouverte ne contient pas de pion ami, mais peut contenir un pion adverse.","ar":"يستطيع الرخ على العمود المفتوح الضغط على أهدافه. أما العمود شبه المفتوح فيخلو من بيدقك لكنه قد يحتوي بيدق الخصم."}'::jsonb, '{"en":"Review the rule and compare it with the position. Open files","fr":"Relisez la règle et comparez-la à la position. Les colonnes ouvertes","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. الأعمدة المفتوحة"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-05-q09', 'l1-05', 9, 'easy', 'multiple_choice', '{"en":"Which statement correctly describes Relative value?","fr":"Quelle affirmation décrit correctement La valeur relative ?","ar":"أي عبارة تصف القيمة النسبية بشكل صحيح؟"}'::jsonb, '[{"id":"a","label":{"en":"Rooks are connected when no pieces remain between them on their shared rank or file.","fr":"Les tours sont reliées lorsqu’aucune pièce ne se trouve entre elles sur leur rangée ou colonne commune.","ar":"يكون الرخان متصلين عندما لا توجد قطع بينهما على الصف أو العمود المشترك."}},{"id":"b","label":{"en":"A rook is often more active behind a passed pawn, where it can support its advance or attack it.","fr":"Une tour est souvent active derrière un pion passé, qu’elle peut soutenir ou attaquer.","ar":"يكون الرخ نشطاً غالباً خلف البيدق المار، فيدعمه أو يهاجمه."}},{"id":"c","label":{"en":"A rook moves any number of unobstructed squares along a rank or file.","fr":"La tour se déplace d’autant de cases libres qu’elle le souhaite sur une rangée ou une colonne.","ar":"يتحرك الرخ أي عدد من المربعات الخالية أفقياً أو عمودياً."}},{"id":"d","label":{"en":"A rook is commonly valued at about five pawns, although its activity can change its practical value.","fr":"La tour vaut souvent environ cinq pions, mais son activité modifie sa valeur pratique.","ar":"تُقدّر قيمة الرخ غالباً بنحو خمسة بيادق، لكن نشاطه يؤثر في قيمته العملية."}}]'::jsonb, 'd', '{"en":"A rook often becomes stronger when files open and passed pawns appear. Do not trade a rook only by counting points; compare activity, king safety, and targets.","fr":"La tour devient souvent plus forte lorsque les colonnes s’ouvrent et que des pions passés apparaissent. Évaluez aussi son activité, la sécurité des rois et les cibles.","ar":"غالباً ما يقوى الرخ عند انفتاح الأعمدة وظهور البيادق المارة. لا تقيّم التبديل بالنقاط وحدها؛ قارن النشاط وأمان الملك والأهداف."}'::jsonb, '{"en":"Review the rule and compare it with the position. Relative value","fr":"Relisez la règle et comparez-la à la position. La valeur relative","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. القيمة النسبية"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-05-q10', 'l1-05', 10, 'medium', 'multiple_choice', '{"en":"You are teaching a beginner about Relative value. Which rule should they apply?","fr":"Vous expliquez La valeur relative à un débutant. Quelle règle doit-il appliquer ?","ar":"تشرح القيمة النسبية لمبتدئ. ما القاعدة التي ينبغي تطبيقها؟"}'::jsonb, '[{"id":"a","label":{"en":"A rook is commonly valued at about five pawns, although its activity can change its practical value.","fr":"La tour vaut souvent environ cinq pions, mais son activité modifie sa valeur pratique.","ar":"تُقدّر قيمة الرخ غالباً بنحو خمسة بيادق، لكن نشاطه يؤثر في قيمته العملية."}},{"id":"b","label":{"en":"Rooks are connected when no pieces remain between them on their shared rank or file.","fr":"Les tours sont reliées lorsqu’aucune pièce ne se trouve entre elles sur leur rangée ou colonne commune.","ar":"يكون الرخان متصلين عندما لا توجد قطع بينهما على الصف أو العمود المشترك."}},{"id":"c","label":{"en":"A rook is often more active behind a passed pawn, where it can support its advance or attack it.","fr":"Une tour est souvent active derrière un pion passé, qu’elle peut soutenir ou attaquer.","ar":"يكون الرخ نشطاً غالباً خلف البيدق المار، فيدعمه أو يهاجمه."}},{"id":"d","label":{"en":"A rook moves any number of unobstructed squares along a rank or file.","fr":"La tour se déplace d’autant de cases libres qu’elle le souhaite sur une rangée ou une colonne.","ar":"يتحرك الرخ أي عدد من المربعات الخالية أفقياً أو عمودياً."}}]'::jsonb, 'a', '{"en":"A rook often becomes stronger when files open and passed pawns appear. Do not trade a rook only by counting points; compare activity, king safety, and targets.","fr":"La tour devient souvent plus forte lorsque les colonnes s’ouvrent et que des pions passés apparaissent. Évaluez aussi son activité, la sécurité des rois et les cibles.","ar":"غالباً ما يقوى الرخ عند انفتاح الأعمدة وظهور البيادق المارة. لا تقيّم التبديل بالنقاط وحدها؛ قارن النشاط وأمان الملك والأهداف."}'::jsonb, '{"en":"Review the rule and compare it with the position. Relative value","fr":"Relisez la règle et comparez-la à la position. La valeur relative","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. القيمة النسبية"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-05-q11', 'l1-05', 11, 'medium', 'true_false', '{"en":"True or false: A rook is commonly valued at about five pawns, although its activity can change its practical value.","fr":"Vrai ou faux : La tour vaut souvent environ cinq pions, mais son activité modifie sa valeur pratique.","ar":"صح أم خطأ: تُقدّر قيمة الرخ غالباً بنحو خمسة بيادق، لكن نشاطه يؤثر في قيمته العملية."}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'true', '{"en":"A rook often becomes stronger when files open and passed pawns appear. Do not trade a rook only by counting points; compare activity, king safety, and targets.","fr":"La tour devient souvent plus forte lorsque les colonnes s’ouvrent et que des pions passés apparaissent. Évaluez aussi son activité, la sécurité des rois et les cibles.","ar":"غالباً ما يقوى الرخ عند انفتاح الأعمدة وظهور البيادق المارة. لا تقيّم التبديل بالنقاط وحدها؛ قارن النشاط وأمان الملك والأهداف."}'::jsonb, '{"en":"Review the rule and compare it with the position. Relative value","fr":"Relisez la règle et comparez-la à la position. La valeur relative","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. القيمة النسبية"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-05-q12', 'l1-05', 12, 'hard', 'identify_mistake', '{"en":"A student claims: “A rook is worth three pawns in every position.” Is the claim correct?","fr":"Un élève affirme : « La tour vaut trois pions dans toutes les positions. » Cette affirmation est-elle correcte ?","ar":"يقول طالب: «تساوي قيمة الرخ ثلاثة بيادق في كل وضع.» هل قوله صحيح؟"}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'false', '{"en":"A rook often becomes stronger when files open and passed pawns appear. Do not trade a rook only by counting points; compare activity, king safety, and targets.","fr":"La tour devient souvent plus forte lorsque les colonnes s’ouvrent et que des pions passés apparaissent. Évaluez aussi son activité, la sécurité des rois et les cibles.","ar":"غالباً ما يقوى الرخ عند انفتاح الأعمدة وظهور البيادق المارة. لا تقيّم التبديل بالنقاط وحدها؛ قارن النشاط وأمان الملك والأهداف."}'::jsonb, '{"en":"Review the rule and compare it with the position. Relative value","fr":"Relisez la règle et comparez-la à la position. La valeur relative","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. القيمة النسبية"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-05-q13', 'l1-05', 13, 'easy', 'multiple_choice', '{"en":"Which statement correctly describes Connected rooks?","fr":"Quelle affirmation décrit correctement Les tours reliées ?","ar":"أي عبارة تصف الرخان المتصلان بشكل صحيح؟"}'::jsonb, '[{"id":"a","label":{"en":"Rooks are connected when no pieces remain between them on their shared rank or file.","fr":"Les tours sont reliées lorsqu’aucune pièce ne se trouve entre elles sur leur rangée ou colonne commune.","ar":"يكون الرخان متصلين عندما لا توجد قطع بينهما على الصف أو العمود المشترك."}},{"id":"b","label":{"en":"A rook is often more active behind a passed pawn, where it can support its advance or attack it.","fr":"Une tour est souvent active derrière un pion passé, qu’elle peut soutenir ou attaquer.","ar":"يكون الرخ نشطاً غالباً خلف البيدق المار، فيدعمه أو يهاجمه."}},{"id":"c","label":{"en":"A rook moves any number of unobstructed squares along a rank or file.","fr":"La tour se déplace d’autant de cases libres qu’elle le souhaite sur une rangée ou une colonne.","ar":"يتحرك الرخ أي عدد من المربعات الخالية أفقياً أو عمودياً."}},{"id":"d","label":{"en":"An open file has no pawns on it and can be a useful route for a rook.","fr":"Une colonne ouverte ne contient aucun pion et peut offrir une voie utile à la tour.","ar":"العمود المفتوح لا يحتوي على بيادق وقد يوفر طريقاً مفيداً للرخ."}}]'::jsonb, 'a', '{"en":"Connected rooks can defend one another and coordinate against a file or target. Castling and developing the minor pieces often help clear the back rank.","fr":"Des tours reliées se défendent et peuvent coordonner leurs attaques. Le roque et le développement des pièces mineures aident souvent à libérer la première rangée.","ar":"يدافع الرخان المتصلان أحدهما عن الآخر وينسّقان الهجوم على عمود أو هدف. يساعد التبييت وتطوير القطع الصغيرة على إخلاء الصف الخلفي."}'::jsonb, '{"en":"Review the rule and compare it with the position. Connected rooks","fr":"Relisez la règle et comparez-la à la position. Les tours reliées","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. الرخان المتصلان"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-05-q14', 'l1-05', 14, 'medium', 'multiple_choice', '{"en":"You are teaching a beginner about Connected rooks. Which rule should they apply?","fr":"Vous expliquez Les tours reliées à un débutant. Quelle règle doit-il appliquer ?","ar":"تشرح الرخان المتصلان لمبتدئ. ما القاعدة التي ينبغي تطبيقها؟"}'::jsonb, '[{"id":"a","label":{"en":"An open file has no pawns on it and can be a useful route for a rook.","fr":"Une colonne ouverte ne contient aucun pion et peut offrir une voie utile à la tour.","ar":"العمود المفتوح لا يحتوي على بيادق وقد يوفر طريقاً مفيداً للرخ."}},{"id":"b","label":{"en":"Rooks are connected when no pieces remain between them on their shared rank or file.","fr":"Les tours sont reliées lorsqu’aucune pièce ne se trouve entre elles sur leur rangée ou colonne commune.","ar":"يكون الرخان متصلين عندما لا توجد قطع بينهما على الصف أو العمود المشترك."}},{"id":"c","label":{"en":"A rook is often more active behind a passed pawn, where it can support its advance or attack it.","fr":"Une tour est souvent active derrière un pion passé, qu’elle peut soutenir ou attaquer.","ar":"يكون الرخ نشطاً غالباً خلف البيدق المار، فيدعمه أو يهاجمه."}},{"id":"d","label":{"en":"A rook moves any number of unobstructed squares along a rank or file.","fr":"La tour se déplace d’autant de cases libres qu’elle le souhaite sur une rangée ou une colonne.","ar":"يتحرك الرخ أي عدد من المربعات الخالية أفقياً أو عمودياً."}}]'::jsonb, 'b', '{"en":"Connected rooks can defend one another and coordinate against a file or target. Castling and developing the minor pieces often help clear the back rank.","fr":"Des tours reliées se défendent et peuvent coordonner leurs attaques. Le roque et le développement des pièces mineures aident souvent à libérer la première rangée.","ar":"يدافع الرخان المتصلان أحدهما عن الآخر وينسّقان الهجوم على عمود أو هدف. يساعد التبييت وتطوير القطع الصغيرة على إخلاء الصف الخلفي."}'::jsonb, '{"en":"Review the rule and compare it with the position. Connected rooks","fr":"Relisez la règle et comparez-la à la position. Les tours reliées","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. الرخان المتصلان"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-05-q15', 'l1-05', 15, 'medium', 'true_false', '{"en":"True or false: Rooks are connected when no pieces remain between them on their shared rank or file.","fr":"Vrai ou faux : Les tours sont reliées lorsqu’aucune pièce ne se trouve entre elles sur leur rangée ou colonne commune.","ar":"صح أم خطأ: يكون الرخان متصلين عندما لا توجد قطع بينهما على الصف أو العمود المشترك."}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'true', '{"en":"Connected rooks can defend one another and coordinate against a file or target. Castling and developing the minor pieces often help clear the back rank.","fr":"Des tours reliées se défendent et peuvent coordonner leurs attaques. Le roque et le développement des pièces mineures aident souvent à libérer la première rangée.","ar":"يدافع الرخان المتصلان أحدهما عن الآخر وينسّقان الهجوم على عمود أو هدف. يساعد التبييت وتطوير القطع الصغيرة على إخلاء الصف الخلفي."}'::jsonb, '{"en":"Review the rule and compare it with the position. Connected rooks","fr":"Relisez la règle et comparez-la à la position. Les tours reliées","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. الرخان المتصلان"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-05-q16', 'l1-05', 16, 'hard', 'identify_mistake', '{"en":"A student claims: “Rooks are connected whenever they are on different files.” Is the claim correct?","fr":"Un élève affirme : « Les tours sont reliées dès qu’elles se trouvent sur des colonnes différentes. » Cette affirmation est-elle correcte ?","ar":"يقول طالب: «يكون الرخان متصلين بمجرد وجودهما على عمودين مختلفين.» هل قوله صحيح؟"}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'false', '{"en":"Connected rooks can defend one another and coordinate against a file or target. Castling and developing the minor pieces often help clear the back rank.","fr":"Des tours reliées se défendent et peuvent coordonner leurs attaques. Le roque et le développement des pièces mineures aident souvent à libérer la première rangée.","ar":"يدافع الرخان المتصلان أحدهما عن الآخر وينسّقان الهجوم على عمود أو هدف. يساعد التبييت وتطوير القطع الصغيرة على إخلاء الصف الخلفي."}'::jsonb, '{"en":"Review the rule and compare it with the position. Connected rooks","fr":"Relisez la règle et comparez-la à la position. Les tours reliées","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. الرخان المتصلان"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-05-q17', 'l1-05', 17, 'easy', 'multiple_choice', '{"en":"Which statement correctly describes Rook activity?","fr":"Quelle affirmation décrit correctement L’activité de la tour ?","ar":"أي عبارة تصف نشاط الرخ بشكل صحيح؟"}'::jsonb, '[{"id":"a","label":{"en":"A rook is commonly valued at about five pawns, although its activity can change its practical value.","fr":"La tour vaut souvent environ cinq pions, mais son activité modifie sa valeur pratique.","ar":"تُقدّر قيمة الرخ غالباً بنحو خمسة بيادق، لكن نشاطه يؤثر في قيمته العملية."}},{"id":"b","label":{"en":"A rook is often more active behind a passed pawn, where it can support its advance or attack it.","fr":"Une tour est souvent active derrière un pion passé, qu’elle peut soutenir ou attaquer.","ar":"يكون الرخ نشطاً غالباً خلف البيدق المار، فيدعمه أو يهاجمه."}},{"id":"c","label":{"en":"A rook moves any number of unobstructed squares along a rank or file.","fr":"La tour se déplace d’autant de cases libres qu’elle le souhaite sur une rangée ou une colonne.","ar":"يتحرك الرخ أي عدد من المربعات الخالية أفقياً أو عمودياً."}},{"id":"d","label":{"en":"An open file has no pawns on it and can be a useful route for a rook.","fr":"Une colonne ouverte ne contient aucun pion et peut offrir une voie utile à la tour.","ar":"العمود المفتوح لا يحتوي على بيادق وقد يوفر طريقاً مفيداً للرخ."}}]'::jsonb, 'b', '{"en":"The “behind the passed pawn” rule is a useful guideline, not an absolute law. Check whether the rook can reach the file, protect the king, and create threats before committing.","fr":"La règle « derrière le pion passé » est un bon principe, pas une loi absolue. Vérifiez l’accès à la colonne, la sécurité du roi et les menaces possibles.","ar":"قاعدة «الرخ خلف البيدق المار» إرشاد وليست قانوناً مطلقاً. افحص إمكانية الوصول إلى العمود وأمان الملك والتهديدات قبل الالتزام."}'::jsonb, '{"en":"Review the rule and compare it with the position. Rook activity","fr":"Relisez la règle et comparez-la à la position. L’activité de la tour","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. نشاط الرخ"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-05-q18', 'l1-05', 18, 'medium', 'multiple_choice', '{"en":"You are teaching a beginner about Rook activity. Which rule should they apply?","fr":"Vous expliquez L’activité de la tour à un débutant. Quelle règle doit-il appliquer ?","ar":"تشرح نشاط الرخ لمبتدئ. ما القاعدة التي ينبغي تطبيقها؟"}'::jsonb, '[{"id":"a","label":{"en":"An open file has no pawns on it and can be a useful route for a rook.","fr":"Une colonne ouverte ne contient aucun pion et peut offrir une voie utile à la tour.","ar":"العمود المفتوح لا يحتوي على بيادق وقد يوفر طريقاً مفيداً للرخ."}},{"id":"b","label":{"en":"A rook is commonly valued at about five pawns, although its activity can change its practical value.","fr":"La tour vaut souvent environ cinq pions, mais son activité modifie sa valeur pratique.","ar":"تُقدّر قيمة الرخ غالباً بنحو خمسة بيادق، لكن نشاطه يؤثر في قيمته العملية."}},{"id":"c","label":{"en":"A rook is often more active behind a passed pawn, where it can support its advance or attack it.","fr":"Une tour est souvent active derrière un pion passé, qu’elle peut soutenir ou attaquer.","ar":"يكون الرخ نشطاً غالباً خلف البيدق المار، فيدعمه أو يهاجمه."}},{"id":"d","label":{"en":"A rook moves any number of unobstructed squares along a rank or file.","fr":"La tour se déplace d’autant de cases libres qu’elle le souhaite sur une rangée ou une colonne.","ar":"يتحرك الرخ أي عدد من المربعات الخالية أفقياً أو عمودياً."}}]'::jsonb, 'c', '{"en":"The “behind the passed pawn” rule is a useful guideline, not an absolute law. Check whether the rook can reach the file, protect the king, and create threats before committing.","fr":"La règle « derrière le pion passé » est un bon principe, pas une loi absolue. Vérifiez l’accès à la colonne, la sécurité du roi et les menaces possibles.","ar":"قاعدة «الرخ خلف البيدق المار» إرشاد وليست قانوناً مطلقاً. افحص إمكانية الوصول إلى العمود وأمان الملك والتهديدات قبل الالتزام."}'::jsonb, '{"en":"Review the rule and compare it with the position. Rook activity","fr":"Relisez la règle et comparez-la à la position. L’activité de la tour","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. نشاط الرخ"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-05-q19', 'l1-05', 19, 'medium', 'true_false', '{"en":"True or false: A rook is often more active behind a passed pawn, where it can support its advance or attack it.","fr":"Vrai ou faux : Une tour est souvent active derrière un pion passé, qu’elle peut soutenir ou attaquer.","ar":"صح أم خطأ: يكون الرخ نشطاً غالباً خلف البيدق المار، فيدعمه أو يهاجمه."}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'true', '{"en":"The “behind the passed pawn” rule is a useful guideline, not an absolute law. Check whether the rook can reach the file, protect the king, and create threats before committing.","fr":"La règle « derrière le pion passé » est un bon principe, pas une loi absolue. Vérifiez l’accès à la colonne, la sécurité du roi et les menaces possibles.","ar":"قاعدة «الرخ خلف البيدق المار» إرشاد وليست قانوناً مطلقاً. افحص إمكانية الوصول إلى العمود وأمان الملك والتهديدات قبل الالتزام."}'::jsonb, '{"en":"Review the rule and compare it with the position. Rook activity","fr":"Relisez la règle et comparez-la à la position. L’activité de la tour","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. نشاط الرخ"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-05-q20', 'l1-05', 20, 'hard', 'best_move', '{"en":"On the board, make a legal move that demonstrates Rook activity.","fr":"Sur l’échiquier, jouez un coup légal qui illustre L’activité de la tour.","ar":"نفّذ على الرقعة نقلة قانونية توضح نشاط الرخ."}'::jsonb, '[{"id":"Ra4","label":{"en":"Ra4","fr":"Ra4","ar":"Ra4"}},{"id":"Ra8+","label":{"en":"Ra8+","fr":"Ra8+","ar":"Ra8+"}},{"id":"Ra2","label":{"en":"Ra2","fr":"Ra2","ar":"Ra2"}},{"id":"Ra3","label":{"en":"Ra3","fr":"Ra3","ar":"Ra3"}}]'::jsonb, 'Ra8+', '{"en":"Ra8+ travels along an open file and checks the king across the eighth rank.","fr":"Ra8+ suit une colonne ouverte et met le roi en échec sur la huitième rangée.","ar":"تتحرك Ra8+ على عمود مفتوح وتكش الملك عبر الصف الثامن."}'::jsonb, '{"en":"Review the rule and compare it with the position. Rook activity","fr":"Relisez la règle et comparez-la à la position. L’activité de la tour","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. نشاط الرخ"}'::jsonb, '7k/8/8/8/8/8/8/R3K3 w - - 0 1', '["Ra8+"]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_lessons (id, level_number, lesson_number, title, summary, content, published) VALUES ('l1-06', 1, 6, '{"en":"The Bishop: Movement and Diagonals","fr":"Le fou : déplacements et diagonales","ar":"الفيل: الحركة والأقطار"}'::jsonb, '{"en":"Use diagonals, understand bishop color, and recognize the impact of pawn structure.","fr":"Utilisez les diagonales, comprenez la couleur du fou et observez la structure de pions.","ar":"استخدم الأقطار وافهم لون الفيل وتأثير بنية البيادق."}'::jsonb, '{"objectives":[{"en":"Bishop movement","fr":"Le déplacement du fou","ar":"حركة الفيل"},{"en":"Square color","fr":"La couleur des cases","ar":"لون المربعات"},{"en":"The bishop pair","fr":"La paire de fous","ar":"زوج الفيلين"},{"en":"Pawn structure and bishops","fr":"La structure de pions et les fous","ar":"بنية البيادق والفيلان"},{"en":"Bishop lines","fr":"Les lignes du fou","ar":"خطوط الفيل"}],"sections":[{"title":{"en":"Bishop movement","fr":"Le déplacement du fou","ar":"حركة الفيل"},"paragraphs":[{"en":"A bishop moves any number of unobstructed squares diagonally.","fr":"Le fou se déplace d’autant de cases libres qu’il le souhaite en diagonale.","ar":"يتحرك الفيل أي عدد من المربعات الخالية قطرياً."},{"en":"A bishop cannot move horizontally or vertically, and it cannot jump over another piece. A capture is made by landing on an enemy piece at the end of a clear diagonal.","fr":"Le fou ne se déplace ni horizontalement ni verticalement et ne saute pas. Il capture en terminant sa diagonale libre sur une pièce adverse.","ar":"لا يتحرك الفيل أفقياً أو عمودياً ولا يقفز فوق القطع. يأسر بإنهاء قطر خالٍ على قطعة للخصم."},{"en":"Practice checkpoint: identify Bishop movement on a board, explain the rule, and check how the opponent could respond.","fr":"Mise en pratique : repérez Le déplacement du fou sur un échiquier, expliquez la règle et vérifiez la réponse possible de l’adversaire.","ar":"تطبيق عملي: حدّد حركة الفيل على الرقعة، واشرح القاعدة، ثم تحقّق من رد الخصم الممكن."}]},{"title":{"en":"Square color","fr":"La couleur des cases","ar":"لون المربعات"},"paragraphs":[{"en":"A bishop remains on the same color squares throughout the game.","fr":"Un fou reste sur des cases de la même couleur pendant toute la partie.","ar":"يبقى الفيل على مربعات اللون نفسه طوال المباراة."},{"en":"A bishop that starts on a light square can never control a dark square directly. This makes the other bishop valuable for covering the opposite color complex.","fr":"Un fou qui commence sur une case claire ne contrôle jamais directement les cases foncées. L’autre fou peut couvrir l’autre couleur.","ar":"الفيل الذي يبدأ على مربع فاتح لا يسيطر مباشرة على المربعات الداكنة. لذلك يفيد الفيل الآخر في تغطية اللون المقابل."},{"en":"Practice checkpoint: identify Square color on a board, explain the rule, and check how the opponent could respond.","fr":"Mise en pratique : repérez La couleur des cases sur un échiquier, expliquez la règle et vérifiez la réponse possible de l’adversaire.","ar":"تطبيق عملي: حدّد لون المربعات على الرقعة، واشرح القاعدة، ثم تحقّق من رد الخصم الممكن."}]},{"title":{"en":"The bishop pair","fr":"La paire de fous","ar":"زوج الفيلين"},"paragraphs":[{"en":"Having both bishops gives a player a bishop pair that can influence both square colors.","fr":"Posséder les deux fous permet d’influencer les cases des deux couleurs.","ar":"امتلاك الفيلين يتيح التأثير في مربعات اللونين."},{"en":"The bishop pair can be especially useful in open positions, where long diagonals are clear. It is an advantage to evaluate, not an automatic win or a reason to ignore king safety.","fr":"La paire de fous est souvent utile dans les positions ouvertes où les grandes diagonales sont libres. C’est un avantage à évaluer, pas une victoire automatique.","ar":"قد يكون زوج الفيلين مفيداً في المراكز المفتوحة ذات الأقطار الطويلة. إنها ميزة تُقيّم وليست فوزاً تلقائياً أو سبباً لإهمال أمان الملك."},{"en":"Practice checkpoint: identify The bishop pair on a board, explain the rule, and check how the opponent could respond.","fr":"Mise en pratique : repérez La paire de fous sur un échiquier, expliquez la règle et vérifiez la réponse possible de l’adversaire.","ar":"تطبيق عملي: حدّد زوج الفيلين على الرقعة، واشرح القاعدة، ثم تحقّق من رد الخصم الممكن."}]},{"title":{"en":"Pawn structure and bishops","fr":"La structure de pions et les fous","ar":"بنية البيادق والفيلان"},"paragraphs":[{"en":"A bishop’s activity depends on whether its own pawns block its diagonals.","fr":"L’activité d’un fou dépend du blocage ou non de ses diagonales par ses propres pions.","ar":"يعتمد نشاط الفيل على ما إذا كانت بيادق صاحبه تعيق أقطاره."},{"en":"A bishop behind a fixed chain of same-color pawns may have limited routes. Open a diagonal with a thoughtful pawn move, or improve another piece before changing the structure.","fr":"Un fou enfermé derrière une chaîne de pions fixes peut manquer de routes. Ouvrez une diagonale avec un coup de pion réfléchi ou améliorez une autre pièce.","ar":"قد تقل مسارات الفيل خلف سلسلة بيادق ثابتة. افتح قطراً بنقلة بيدق مدروسة أو حسّن قطعة أخرى قبل تغيير البنية."},{"en":"Practice checkpoint: identify Pawn structure and bishops on a board, explain the rule, and check how the opponent could respond.","fr":"Mise en pratique : repérez La structure de pions et les fous sur un échiquier, expliquez la règle et vérifiez la réponse possible de l’adversaire.","ar":"تطبيق عملي: حدّد بنية البيادق والفيلان على الرقعة، واشرح القاعدة، ثم تحقّق من رد الخصم الممكن."}]},{"title":{"en":"Bishop lines","fr":"Les lignes du fou","ar":"خطوط الفيل"},"paragraphs":[{"en":"A bishop’s long diagonal can pressure a target from a distance when the path is clear.","fr":"Une longue diagonale permet au fou de mettre une cible sous pression à distance si la ligne est libre.","ar":"يمكن لقطر طويل أن يمكّن الفيل من الضغط على هدف بعيد إذا كان الطريق خالياً."},{"en":"A bishop may attack a square without moving closer to it. Before opening a diagonal, verify that your own king and valuable pieces will not become exposed.","fr":"Le fou peut attaquer une case sans s’en approcher. Avant d’ouvrir une diagonale, vérifiez que votre roi et vos pièces importantes restent protégés.","ar":"قد يهاجم الفيل مربعاً من بعيد. قبل فتح القطر، تأكد من عدم كشف ملكك أو قطعك المهمة."},{"en":"Practice checkpoint: identify Bishop lines on a board, explain the rule, and check how the opponent could respond.","fr":"Mise en pratique : repérez Les lignes du fou sur un échiquier, expliquez la règle et vérifiez la réponse possible de l’adversaire.","ar":"تطبيق عملي: حدّد خطوط الفيل على الرقعة، واشرح القاعدة، ثم تحقّق من رد الخصم الممكن."}]}],"terminology":[{"term":{"en":"Bishop movement","fr":"Le déplacement du fou","ar":"حركة الفيل"},"definition":{"en":"A bishop moves any number of unobstructed squares diagonally.","fr":"Le fou se déplace d’autant de cases libres qu’il le souhaite en diagonale.","ar":"يتحرك الفيل أي عدد من المربعات الخالية قطرياً."}},{"term":{"en":"Square color","fr":"La couleur des cases","ar":"لون المربعات"},"definition":{"en":"A bishop remains on the same color squares throughout the game.","fr":"Un fou reste sur des cases de la même couleur pendant toute la partie.","ar":"يبقى الفيل على مربعات اللون نفسه طوال المباراة."}},{"term":{"en":"The bishop pair","fr":"La paire de fous","ar":"زوج الفيلين"},"definition":{"en":"Having both bishops gives a player a bishop pair that can influence both square colors.","fr":"Posséder les deux fous permet d’influencer les cases des deux couleurs.","ar":"امتلاك الفيلين يتيح التأثير في مربعات اللونين."}},{"term":{"en":"Pawn structure and bishops","fr":"La structure de pions et les fous","ar":"بنية البيادق والفيلان"},"definition":{"en":"A bishop’s activity depends on whether its own pawns block its diagonals.","fr":"L’activité d’un fou dépend du blocage ou non de ses diagonales par ses propres pions.","ar":"يعتمد نشاط الفيل على ما إذا كانت بيادق صاحبه تعيق أقطاره."}},{"term":{"en":"Bishop lines","fr":"Les lignes du fou","ar":"خطوط الفيل"},"definition":{"en":"A bishop’s long diagonal can pressure a target from a distance when the path is clear.","fr":"Une longue diagonale permet au fou de mettre une cible sous pression à distance si la ligne est libre.","ar":"يمكن لقطر طويل أن يمكّن الفيل من الضغط على هدف بعيد إذا كان الطريق خالياً."}}],"example":{"fen":"7k/8/8/8/8/8/8/2B1K3 w - - 0 1","solutionMoves":["Bf4"],"annotation":{"en":"Bf4 follows a clear diagonal from c1 to f4, illustrating the bishop’s movement.","fr":"Bf4 suit une diagonale libre de c1 à f4 et illustre le déplacement du fou.","ar":"تتبع Bf4 قطراً خالياً من c1 إلى f4، موضحةً حركة الفيل."}},"commonMistakes":[{"en":"A bishop moves in straight lines along ranks and files.","fr":"Le fou se déplace en ligne droite sur les rangées et colonnes.","ar":"يتحرك الفيل بخطوط مستقيمة أفقية وعمودية."},{"en":"A bishop can switch square colors after moving two squares.","fr":"Le fou peut changer de couleur de cases après un déplacement de deux cases.","ar":"يستطيع الفيل تبديل لون المربعات بعد التحرك مربعين."},{"en":"A bishop pair guarantees checkmate regardless of the position.","fr":"La paire de fous garantit le mat quelle que soit la position.","ar":"يضمن زوج الفيلين كش مات مهما كان الوضع."},{"en":"A bishop is always active even when its own pawns block every diagonal.","fr":"Un fou est toujours actif même si ses propres pions bloquent toutes ses diagonales.","ar":"يكون الفيل نشطاً دائماً حتى لو سدت بيادق صاحبه أقطاره كلها."},{"en":"A bishop attacks only the next square on its diagonal.","fr":"Le fou n’attaque que la case suivante sur sa diagonale.","ar":"يهاجم الفيل المربع التالي فقط على قطره."}],"professionalTips":[{"en":"Before moving, pause and ask how Bishop movement affects your king safety and your opponent’s best reply.","fr":"Avant de jouer, demandez-vous comment Le déplacement du fou influence la sécurité de votre roi et la meilleure réponse adverse.","ar":"قبل أن تلعب، فكّر كيف يؤثر حركة الفيل في أمان ملكك وفي أفضل رد للخصم."},{"en":"Before moving, pause and ask how Square color affects your king safety and your opponent’s best reply.","fr":"Avant de jouer, demandez-vous comment La couleur des cases influence la sécurité de votre roi et la meilleure réponse adverse.","ar":"قبل أن تلعب، فكّر كيف يؤثر لون المربعات في أمان ملكك وفي أفضل رد للخصم."},{"en":"Before moving, pause and ask how The bishop pair affects your king safety and your opponent’s best reply.","fr":"Avant de jouer, demandez-vous comment La paire de fous influence la sécurité de votre roi et la meilleure réponse adverse.","ar":"قبل أن تلعب، فكّر كيف يؤثر زوج الفيلين في أمان ملكك وفي أفضل رد للخصم."},{"en":"Before moving, pause and ask how Pawn structure and bishops affects your king safety and your opponent’s best reply.","fr":"Avant de jouer, demandez-vous comment La structure de pions et les fous influence la sécurité de votre roi et la meilleure réponse adverse.","ar":"قبل أن تلعب، فكّر كيف يؤثر بنية البيادق والفيلان في أمان ملكك وفي أفضل رد للخصم."},{"en":"Before moving, pause and ask how Bishop lines affects your king safety and your opponent’s best reply.","fr":"Avant de jouer, demandez-vous comment Les lignes du fou influence la sécurité de votre roi et la meilleure réponse adverse.","ar":"قبل أن تلعب، فكّر كيف يؤثر خطوط الفيل في أمان ملكك وفي أفضل رد للخصم."}],"exercises":[{"en":"Set up a position that demonstrates Bishop movement. Name the legal choices and explain why one choice follows the rule.","fr":"Préparez une position illustrant Le déplacement du fou. Indiquez les choix légaux et expliquez lequel respecte la règle.","ar":"أنشئ وضعية توضّح حركة الفيل. اذكر النقلات القانونية واشرح لماذا تتبع إحداها القاعدة."},{"en":"Set up a position that demonstrates Square color. Name the legal choices and explain why one choice follows the rule.","fr":"Préparez une position illustrant La couleur des cases. Indiquez les choix légaux et expliquez lequel respecte la règle.","ar":"أنشئ وضعية توضّح لون المربعات. اذكر النقلات القانونية واشرح لماذا تتبع إحداها القاعدة."},{"en":"Set up a position that demonstrates The bishop pair. Name the legal choices and explain why one choice follows the rule.","fr":"Préparez une position illustrant La paire de fous. Indiquez les choix légaux et expliquez lequel respecte la règle.","ar":"أنشئ وضعية توضّح زوج الفيلين. اذكر النقلات القانونية واشرح لماذا تتبع إحداها القاعدة."},{"en":"Set up a position that demonstrates Pawn structure and bishops. Name the legal choices and explain why one choice follows the rule.","fr":"Préparez une position illustrant La structure de pions et les fous. Indiquez les choix légaux et expliquez lequel respecte la règle.","ar":"أنشئ وضعية توضّح بنية البيادق والفيلان. اذكر النقلات القانونية واشرح لماذا تتبع إحداها القاعدة."},{"en":"Set up a position that demonstrates Bishop lines. Name the legal choices and explain why one choice follows the rule.","fr":"Préparez une position illustrant Les lignes du fou. Indiquez les choix légaux et expliquez lequel respecte la règle.","ar":"أنشئ وضعية توضّح خطوط الفيل. اذكر النقلات القانونية واشرح لماذا تتبع إحداها القاعدة."}],"takeaways":[{"en":"A bishop moves any number of unobstructed squares diagonally.","fr":"Le fou se déplace d’autant de cases libres qu’il le souhaite en diagonale.","ar":"يتحرك الفيل أي عدد من المربعات الخالية قطرياً."},{"en":"A bishop remains on the same color squares throughout the game.","fr":"Un fou reste sur des cases de la même couleur pendant toute la partie.","ar":"يبقى الفيل على مربعات اللون نفسه طوال المباراة."},{"en":"Having both bishops gives a player a bishop pair that can influence both square colors.","fr":"Posséder les deux fous permet d’influencer les cases des deux couleurs.","ar":"امتلاك الفيلين يتيح التأثير في مربعات اللونين."},{"en":"A bishop’s activity depends on whether its own pawns block its diagonals.","fr":"L’activité d’un fou dépend du blocage ou non de ses diagonales par ses propres pions.","ar":"يعتمد نشاط الفيل على ما إذا كانت بيادق صاحبه تعيق أقطاره."},{"en":"A bishop’s long diagonal can pressure a target from a distance when the path is clear.","fr":"Une longue diagonale permet au fou de mettre une cible sous pression à distance si la ligne est libre.","ar":"يمكن لقطر طويل أن يمكّن الفيل من الضغط على هدف بعيد إذا كان الطريق خالياً."}]}'::jsonb, TRUE) ON CONFLICT (id) DO UPDATE SET level_number = EXCLUDED.level_number, lesson_number = EXCLUDED.lesson_number, title = EXCLUDED.title, summary = EXCLUDED.summary, content = EXCLUDED.content, published = TRUE, updated_at = NOW();
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-06-q01', 'l1-06', 1, 'easy', 'multiple_choice', '{"en":"Which statement correctly describes Bishop movement?","fr":"Quelle affirmation décrit correctement Le déplacement du fou ?","ar":"أي عبارة تصف حركة الفيل بشكل صحيح؟"}'::jsonb, '[{"id":"a","label":{"en":"A bishop’s activity depends on whether its own pawns block its diagonals.","fr":"L’activité d’un fou dépend du blocage ou non de ses diagonales par ses propres pions.","ar":"يعتمد نشاط الفيل على ما إذا كانت بيادق صاحبه تعيق أقطاره."}},{"id":"b","label":{"en":"A bishop moves any number of unobstructed squares diagonally.","fr":"Le fou se déplace d’autant de cases libres qu’il le souhaite en diagonale.","ar":"يتحرك الفيل أي عدد من المربعات الخالية قطرياً."}},{"id":"c","label":{"en":"A bishop remains on the same color squares throughout the game.","fr":"Un fou reste sur des cases de la même couleur pendant toute la partie.","ar":"يبقى الفيل على مربعات اللون نفسه طوال المباراة."}},{"id":"d","label":{"en":"Having both bishops gives a player a bishop pair that can influence both square colors.","fr":"Posséder les deux fous permet d’influencer les cases des deux couleurs.","ar":"امتلاك الفيلين يتيح التأثير في مربعات اللونين."}}]'::jsonb, 'b', '{"en":"A bishop cannot move horizontally or vertically, and it cannot jump over another piece. A capture is made by landing on an enemy piece at the end of a clear diagonal.","fr":"Le fou ne se déplace ni horizontalement ni verticalement et ne saute pas. Il capture en terminant sa diagonale libre sur une pièce adverse.","ar":"لا يتحرك الفيل أفقياً أو عمودياً ولا يقفز فوق القطع. يأسر بإنهاء قطر خالٍ على قطعة للخصم."}'::jsonb, '{"en":"Review the rule and compare it with the position. Bishop movement","fr":"Relisez la règle et comparez-la à la position. Le déplacement du fou","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. حركة الفيل"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-06-q02', 'l1-06', 2, 'medium', 'multiple_choice', '{"en":"You are teaching a beginner about Bishop movement. Which rule should they apply?","fr":"Vous expliquez Le déplacement du fou à un débutant. Quelle règle doit-il appliquer ?","ar":"تشرح حركة الفيل لمبتدئ. ما القاعدة التي ينبغي تطبيقها؟"}'::jsonb, '[{"id":"a","label":{"en":"Having both bishops gives a player a bishop pair that can influence both square colors.","fr":"Posséder les deux fous permet d’influencer les cases des deux couleurs.","ar":"امتلاك الفيلين يتيح التأثير في مربعات اللونين."}},{"id":"b","label":{"en":"A bishop’s activity depends on whether its own pawns block its diagonals.","fr":"L’activité d’un fou dépend du blocage ou non de ses diagonales par ses propres pions.","ar":"يعتمد نشاط الفيل على ما إذا كانت بيادق صاحبه تعيق أقطاره."}},{"id":"c","label":{"en":"A bishop moves any number of unobstructed squares diagonally.","fr":"Le fou se déplace d’autant de cases libres qu’il le souhaite en diagonale.","ar":"يتحرك الفيل أي عدد من المربعات الخالية قطرياً."}},{"id":"d","label":{"en":"A bishop remains on the same color squares throughout the game.","fr":"Un fou reste sur des cases de la même couleur pendant toute la partie.","ar":"يبقى الفيل على مربعات اللون نفسه طوال المباراة."}}]'::jsonb, 'c', '{"en":"A bishop cannot move horizontally or vertically, and it cannot jump over another piece. A capture is made by landing on an enemy piece at the end of a clear diagonal.","fr":"Le fou ne se déplace ni horizontalement ni verticalement et ne saute pas. Il capture en terminant sa diagonale libre sur une pièce adverse.","ar":"لا يتحرك الفيل أفقياً أو عمودياً ولا يقفز فوق القطع. يأسر بإنهاء قطر خالٍ على قطعة للخصم."}'::jsonb, '{"en":"Review the rule and compare it with the position. Bishop movement","fr":"Relisez la règle et comparez-la à la position. Le déplacement du fou","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. حركة الفيل"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-06-q03', 'l1-06', 3, 'medium', 'true_false', '{"en":"True or false: A bishop moves any number of unobstructed squares diagonally.","fr":"Vrai ou faux : Le fou se déplace d’autant de cases libres qu’il le souhaite en diagonale.","ar":"صح أم خطأ: يتحرك الفيل أي عدد من المربعات الخالية قطرياً."}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'true', '{"en":"A bishop cannot move horizontally or vertically, and it cannot jump over another piece. A capture is made by landing on an enemy piece at the end of a clear diagonal.","fr":"Le fou ne se déplace ni horizontalement ni verticalement et ne saute pas. Il capture en terminant sa diagonale libre sur une pièce adverse.","ar":"لا يتحرك الفيل أفقياً أو عمودياً ولا يقفز فوق القطع. يأسر بإنهاء قطر خالٍ على قطعة للخصم."}'::jsonb, '{"en":"Review the rule and compare it with the position. Bishop movement","fr":"Relisez la règle et comparez-la à la position. Le déplacement du fou","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. حركة الفيل"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-06-q04', 'l1-06', 4, 'hard', 'identify_mistake', '{"en":"A student claims: “A bishop moves in straight lines along ranks and files.” Is the claim correct?","fr":"Un élève affirme : « Le fou se déplace en ligne droite sur les rangées et colonnes. » Cette affirmation est-elle correcte ?","ar":"يقول طالب: «يتحرك الفيل بخطوط مستقيمة أفقية وعمودية.» هل قوله صحيح؟"}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'false', '{"en":"A bishop cannot move horizontally or vertically, and it cannot jump over another piece. A capture is made by landing on an enemy piece at the end of a clear diagonal.","fr":"Le fou ne se déplace ni horizontalement ni verticalement et ne saute pas. Il capture en terminant sa diagonale libre sur une pièce adverse.","ar":"لا يتحرك الفيل أفقياً أو عمودياً ولا يقفز فوق القطع. يأسر بإنهاء قطر خالٍ على قطعة للخصم."}'::jsonb, '{"en":"Review the rule and compare it with the position. Bishop movement","fr":"Relisez la règle et comparez-la à la position. Le déplacement du fou","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. حركة الفيل"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-06-q05', 'l1-06', 5, 'easy', 'multiple_choice', '{"en":"Which statement correctly describes Square color?","fr":"Quelle affirmation décrit correctement La couleur des cases ?","ar":"أي عبارة تصف لون المربعات بشكل صحيح؟"}'::jsonb, '[{"id":"a","label":{"en":"A bishop’s activity depends on whether its own pawns block its diagonals.","fr":"L’activité d’un fou dépend du blocage ou non de ses diagonales par ses propres pions.","ar":"يعتمد نشاط الفيل على ما إذا كانت بيادق صاحبه تعيق أقطاره."}},{"id":"b","label":{"en":"A bishop’s long diagonal can pressure a target from a distance when the path is clear.","fr":"Une longue diagonale permet au fou de mettre une cible sous pression à distance si la ligne est libre.","ar":"يمكن لقطر طويل أن يمكّن الفيل من الضغط على هدف بعيد إذا كان الطريق خالياً."}},{"id":"c","label":{"en":"A bishop remains on the same color squares throughout the game.","fr":"Un fou reste sur des cases de la même couleur pendant toute la partie.","ar":"يبقى الفيل على مربعات اللون نفسه طوال المباراة."}},{"id":"d","label":{"en":"Having both bishops gives a player a bishop pair that can influence both square colors.","fr":"Posséder les deux fous permet d’influencer les cases des deux couleurs.","ar":"امتلاك الفيلين يتيح التأثير في مربعات اللونين."}}]'::jsonb, 'c', '{"en":"A bishop that starts on a light square can never control a dark square directly. This makes the other bishop valuable for covering the opposite color complex.","fr":"Un fou qui commence sur une case claire ne contrôle jamais directement les cases foncées. L’autre fou peut couvrir l’autre couleur.","ar":"الفيل الذي يبدأ على مربع فاتح لا يسيطر مباشرة على المربعات الداكنة. لذلك يفيد الفيل الآخر في تغطية اللون المقابل."}'::jsonb, '{"en":"Review the rule and compare it with the position. Square color","fr":"Relisez la règle et comparez-la à la position. La couleur des cases","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. لون المربعات"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
