INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-07-q17', 'l1-07', 17, 'easy', 'multiple_choice', '{"en":"Which statement correctly describes Knight forks?","fr":"Quelle affirmation décrit correctement Les fourchettes de cavalier ?","ar":"أي عبارة تصف شوكة الحصان بشكل صحيح؟"}'::jsonb, '[{"id":"a","label":{"en":"Every knight move changes the color of the square the knight occupies.","fr":"Chaque coup de cavalier change la couleur de la case qu’il occupe.","ar":"تغيّر كل نقلة للحصان لون المربع الذي يقف عليه."}},{"id":"b","label":{"en":"A knight can attack several targets at once, creating a fork or double attack.","fr":"Le cavalier peut attaquer plusieurs cibles à la fois et créer une fourchette.","ar":"يستطيع الحصان مهاجمة عدة أهداف معاً وصنع شوكة أو هجوم مزدوج."}},{"id":"c","label":{"en":"A knight moves two squares in one direction and then one square perpendicular to that direction.","fr":"Le cavalier avance de deux cases dans une direction, puis d’une case perpendiculairement.","ar":"يتحرك الحصان مربعين في اتجاه ثم مربعاً واحداً عمودياً على ذلك الاتجاه."}},{"id":"d","label":{"en":"A knight is the only standard chess piece that can jump over intervening pieces.","fr":"Le cavalier est la seule pièce habituelle qui peut sauter par-dessus les pièces intermédiaires.","ar":"الحصان هو القطعة الوحيدة في الشطرنج التي تستطيع القفز فوق القطع."}}]'::jsonb, 'b', '{"en":"Because a knight’s attack cannot be blocked, a fork may threaten a king and another piece simultaneously. Look for checks first, then identify the second target.","fr":"Comme son attaque ne peut pas être bloquée, une fourchette peut menacer simultanément le roi et une autre pièce. Cherchez d’abord les échecs, puis une seconde cible.","ar":"لأن هجوم الحصان لا يُصد بقطعة، قد تهدد الشوكة الملك وقطعة أخرى معاً. ابحث عن الكش أولاً ثم عن الهدف الثاني."}'::jsonb, '{"en":"Review the rule and compare it with the position. Knight forks","fr":"Relisez la règle et comparez-la à la position. Les fourchettes de cavalier","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. شوكة الحصان"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-07-q18', 'l1-07', 18, 'medium', 'multiple_choice', '{"en":"You are teaching a beginner about Knight forks. Which rule should they apply?","fr":"Vous expliquez Les fourchettes de cavalier à un débutant. Quelle règle doit-il appliquer ?","ar":"تشرح شوكة الحصان لمبتدئ. ما القاعدة التي ينبغي تطبيقها؟"}'::jsonb, '[{"id":"a","label":{"en":"A knight is the only standard chess piece that can jump over intervening pieces.","fr":"Le cavalier est la seule pièce habituelle qui peut sauter par-dessus les pièces intermédiaires.","ar":"الحصان هو القطعة الوحيدة في الشطرنج التي تستطيع القفز فوق القطع."}},{"id":"b","label":{"en":"Every knight move changes the color of the square the knight occupies.","fr":"Chaque coup de cavalier change la couleur de la case qu’il occupe.","ar":"تغيّر كل نقلة للحصان لون المربع الذي يقف عليه."}},{"id":"c","label":{"en":"A knight can attack several targets at once, creating a fork or double attack.","fr":"Le cavalier peut attaquer plusieurs cibles à la fois et créer une fourchette.","ar":"يستطيع الحصان مهاجمة عدة أهداف معاً وصنع شوكة أو هجوم مزدوج."}},{"id":"d","label":{"en":"A knight moves two squares in one direction and then one square perpendicular to that direction.","fr":"Le cavalier avance de deux cases dans une direction, puis d’une case perpendiculairement.","ar":"يتحرك الحصان مربعين في اتجاه ثم مربعاً واحداً عمودياً على ذلك الاتجاه."}}]'::jsonb, 'c', '{"en":"Because a knight’s attack cannot be blocked, a fork may threaten a king and another piece simultaneously. Look for checks first, then identify the second target.","fr":"Comme son attaque ne peut pas être bloquée, une fourchette peut menacer simultanément le roi et une autre pièce. Cherchez d’abord les échecs, puis une seconde cible.","ar":"لأن هجوم الحصان لا يُصد بقطعة، قد تهدد الشوكة الملك وقطعة أخرى معاً. ابحث عن الكش أولاً ثم عن الهدف الثاني."}'::jsonb, '{"en":"Review the rule and compare it with the position. Knight forks","fr":"Relisez la règle et comparez-la à la position. Les fourchettes de cavalier","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. شوكة الحصان"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-07-q19', 'l1-07', 19, 'medium', 'true_false', '{"en":"True or false: A knight can attack several targets at once, creating a fork or double attack.","fr":"Vrai ou faux : Le cavalier peut attaquer plusieurs cibles à la fois et créer une fourchette.","ar":"صح أم خطأ: يستطيع الحصان مهاجمة عدة أهداف معاً وصنع شوكة أو هجوم مزدوج."}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'true', '{"en":"Because a knight’s attack cannot be blocked, a fork may threaten a king and another piece simultaneously. Look for checks first, then identify the second target.","fr":"Comme son attaque ne peut pas être bloquée, une fourchette peut menacer simultanément le roi et une autre pièce. Cherchez d’abord les échecs, puis une seconde cible.","ar":"لأن هجوم الحصان لا يُصد بقطعة، قد تهدد الشوكة الملك وقطعة أخرى معاً. ابحث عن الكش أولاً ثم عن الهدف الثاني."}'::jsonb, '{"en":"Review the rule and compare it with the position. Knight forks","fr":"Relisez la règle et comparez-la à la position. Les fourchettes de cavalier","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. شوكة الحصان"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-07-q20', 'l1-07', 20, 'hard', 'best_move', '{"en":"On the board, make a legal move that demonstrates Knight forks.","fr":"Sur l’échiquier, jouez un coup légal qui illustre Les fourchettes de cavalier.","ar":"نفّذ على الرقعة نقلة قانونية توضح شوكة الحصان."}'::jsonb, '[{"id":"b3","label":{"en":"b3","fr":"b3","ar":"b3"}},{"id":"Nf3","label":{"en":"Nf3","fr":"Nf3","ar":"Nf3"}},{"id":"a3","label":{"en":"a3","fr":"a3","ar":"a3"}},{"id":"a4","label":{"en":"a4","fr":"a4","ar":"a4"}}]'::jsonb, 'Nf3', '{"en":"Nf3 is the knight’s L-shaped move from g1 to f3; the e2 pawn does not block the jump.","fr":"Nf3 est le déplacement en L du cavalier de g1 à f3 ; le pion e2 ne bloque pas son saut.","ar":"Nf3 نقلة L للحصان من g1 إلى f3؛ لا يعيق بيدق e2 قفزته."}'::jsonb, '{"en":"Review the rule and compare it with the position. Knight forks","fr":"Relisez la règle et comparez-la à la position. Les fourchettes de cavalier","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. شوكة الحصان"}'::jsonb, 'rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1', '["Nf3"]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_lessons (id, level_number, lesson_number, title, summary, content, published) VALUES ('l1-08', 1, 8, '{"en":"The Pawn: Movement, Captures and Promotion","fr":"Le pion : déplacement, prise et promotion","ar":"البيدق: الحركة والأسر والترقية"}'::jsonb, '{"en":"Learn the pawn’s forward movement, diagonal captures, promotion, and en passant.","fr":"Apprenez l’avance du pion, ses prises en diagonale, la promotion et la prise en passant.","ar":"تعلّم تقدم البيدق وأسره قطرياً وترقيته والأخذ بالتجاوز."}'::jsonb, '{"objectives":[{"en":"Forward movement","fr":"L’avance","ar":"التقدم"},{"en":"First double step","fr":"La double avance initiale","ar":"التقدم المزدوج الأول"},{"en":"Captures","fr":"Les prises","ar":"الأسر"},{"en":"Promotion","fr":"La promotion","ar":"الترقية"},{"en":"En passant","fr":"La prise en passant","ar":"الأخذ بالتجاوز"}],"sections":[{"title":{"en":"Forward movement","fr":"L’avance","ar":"التقدم"},"paragraphs":[{"en":"A pawn normally moves one square forward into an empty square.","fr":"Un pion avance normalement d’une case vers l’avant sur une case vide.","ar":"يتقدم البيدق عادةً مربعاً واحداً إلى الأمام نحو مربع فارغ."},{"en":"Pawns do not move backward. White advances toward rank 8 and Black toward rank 1. A pawn cannot move forward into an occupied square.","fr":"Les pions ne reculent pas. Les Blancs avancent vers la rangée 8 et les Noirs vers la rangée 1. Un pion ne peut pas avancer sur une case occupée.","ar":"لا تتراجع البيادق. يتقدم الأبيض نحو الصف 8 والأسود نحو الصف 1، ولا يستطيع البيدق التقدم إلى مربع مشغول."},{"en":"Practice checkpoint: identify Forward movement on a board, explain the rule, and check how the opponent could respond.","fr":"Mise en pratique : repérez L’avance sur un échiquier, expliquez la règle et vérifiez la réponse possible de l’adversaire.","ar":"تطبيق عملي: حدّد التقدم على الرقعة، واشرح القاعدة، ثم تحقّق من رد الخصم الممكن."}]},{"title":{"en":"First double step","fr":"La double avance initiale","ar":"التقدم المزدوج الأول"},"paragraphs":[{"en":"From its starting rank, a pawn may advance two squares if both squares are clear.","fr":"Depuis sa rangée de départ, un pion peut avancer de deux cases si les deux sont libres.","ar":"من صف البداية، يمكن للبيدق التقدم مربعين إذا كان كلاهما خالياً."},{"en":"The two-square move is optional, not mandatory. A pawn can make it only from its starting square and cannot jump over a piece on the intermediate square.","fr":"La double avance est facultative. Elle n’est possible que depuis la case de départ et le pion ne peut pas sauter une pièce intermédiaire.","ar":"التقدم مربعين اختياري وليس إلزامياً. لا يحدث إلا من مربع البداية ولا يقفز البيدق فوق قطعة في المربع الوسيط."},{"en":"Practice checkpoint: identify First double step on a board, explain the rule, and check how the opponent could respond.","fr":"Mise en pratique : repérez La double avance initiale sur un échiquier, expliquez la règle et vérifiez la réponse possible de l’adversaire.","ar":"تطبيق عملي: حدّد التقدم المزدوج الأول على الرقعة، واشرح القاعدة، ثم تحقّق من رد الخصم الممكن."}]},{"title":{"en":"Captures","fr":"Les prises","ar":"الأسر"},"paragraphs":[{"en":"A pawn captures one square diagonally forward, not straight ahead.","fr":"Un pion capture une case en diagonale vers l’avant, jamais tout droit.","ar":"يأسر البيدق مربعاً واحداً قطرياً إلى الأمام وليس مباشرة."},{"en":"A pawn moves and captures differently: forward for a quiet move, diagonal for a capture. It cannot capture a piece behind it or on an adjacent file without moving forward.","fr":"Le pion se déplace et capture différemment : tout droit pour avancer, en diagonale pour prendre. Il ne capture ni derrière lui ni horizontalement.","ar":"تختلف حركة البيدق عن أسره: يتقدم مباشرة ويأسر قطرياً. لا يأسر خلفه أو أفقياً إلى مربع مجاور."},{"en":"Practice checkpoint: identify Captures on a board, explain the rule, and check how the opponent could respond.","fr":"Mise en pratique : repérez Les prises sur un échiquier, expliquez la règle et vérifiez la réponse possible de l’adversaire.","ar":"تطبيق عملي: حدّد الأسر على الرقعة، واشرح القاعدة، ثم تحقّق من رد الخصم الممكن."}]},{"title":{"en":"Promotion","fr":"La promotion","ar":"الترقية"},"paragraphs":[{"en":"When a pawn reaches the last rank, it must promote to a queen, rook, bishop, or knight.","fr":"Lorsqu’un pion atteint la dernière rangée, il doit être promu en dame, tour, fou ou cavalier.","ar":"عندما يصل البيدق إلى الصف الأخير، يجب ترقيته إلى ملكة أو رخ أو فيل أو حصان."},{"en":"Promotion happens immediately on reaching the last rank. A pawn cannot become a king, and choosing a piece other than a queen is called underpromotion.","fr":"La promotion a lieu dès l’arrivée sur la dernière rangée. Le pion ne peut pas devenir roi ; choisir une pièce autre que la dame est une sous-promotion.","ar":"تحدث الترقية فور الوصول إلى الصف الأخير. لا يتحول البيدق إلى ملك، واختيار قطعة غير الملكة يسمى ترقية ناقصة."},{"en":"Practice checkpoint: identify Promotion on a board, explain the rule, and check how the opponent could respond.","fr":"Mise en pratique : repérez La promotion sur un échiquier, expliquez la règle et vérifiez la réponse possible de l’adversaire.","ar":"تطبيق عملي: حدّد الترقية على الرقعة، واشرح القاعدة، ثم تحقّق من رد الخصم الممكن."}]},{"title":{"en":"En passant","fr":"La prise en passant","ar":"الأخذ بالتجاوز"},"paragraphs":[{"en":"En passant is an immediate pawn capture after an opponent advances a pawn two squares past your pawn.","fr":"La prise en passant est une prise immédiate après qu’un pion adverse a avancé de deux cases au-delà du vôtre.","ar":"الأخذ بالتجاوز أسر فوري بعد أن يتقدم بيدق الخصم مربعين متجاوزاً بيدقك."},{"en":"The capturing pawn moves diagonally to the square the opposing pawn passed over, and the opposing pawn is removed. If you do not take en passant on the very next move, the right expires.","fr":"Le pion preneur avance en diagonale sur la case traversée et le pion adverse est retiré. Si la prise n’est pas jouée immédiatement, le droit disparaît.","ar":"يتحرك البيدق الآسر قطرياً إلى المربع الذي تجاوزه بيدق الخصم، ثم يُزال البيدق. إذا لم تنفذها فوراً، يسقط الحق بها."},{"en":"Practice checkpoint: identify En passant on a board, explain the rule, and check how the opponent could respond.","fr":"Mise en pratique : repérez La prise en passant sur un échiquier, expliquez la règle et vérifiez la réponse possible de l’adversaire.","ar":"تطبيق عملي: حدّد الأخذ بالتجاوز على الرقعة، واشرح القاعدة، ثم تحقّق من رد الخصم الممكن."}]}],"terminology":[{"term":{"en":"Forward movement","fr":"L’avance","ar":"التقدم"},"definition":{"en":"A pawn normally moves one square forward into an empty square.","fr":"Un pion avance normalement d’une case vers l’avant sur une case vide.","ar":"يتقدم البيدق عادةً مربعاً واحداً إلى الأمام نحو مربع فارغ."}},{"term":{"en":"First double step","fr":"La double avance initiale","ar":"التقدم المزدوج الأول"},"definition":{"en":"From its starting rank, a pawn may advance two squares if both squares are clear.","fr":"Depuis sa rangée de départ, un pion peut avancer de deux cases si les deux sont libres.","ar":"من صف البداية، يمكن للبيدق التقدم مربعين إذا كان كلاهما خالياً."}},{"term":{"en":"Captures","fr":"Les prises","ar":"الأسر"},"definition":{"en":"A pawn captures one square diagonally forward, not straight ahead.","fr":"Un pion capture une case en diagonale vers l’avant, jamais tout droit.","ar":"يأسر البيدق مربعاً واحداً قطرياً إلى الأمام وليس مباشرة."}},{"term":{"en":"Promotion","fr":"La promotion","ar":"الترقية"},"definition":{"en":"When a pawn reaches the last rank, it must promote to a queen, rook, bishop, or knight.","fr":"Lorsqu’un pion atteint la dernière rangée, il doit être promu en dame, tour, fou ou cavalier.","ar":"عندما يصل البيدق إلى الصف الأخير، يجب ترقيته إلى ملكة أو رخ أو فيل أو حصان."}},{"term":{"en":"En passant","fr":"La prise en passant","ar":"الأخذ بالتجاوز"},"definition":{"en":"En passant is an immediate pawn capture after an opponent advances a pawn two squares past your pawn.","fr":"La prise en passant est une prise immédiate après qu’un pion adverse a avancé de deux cases au-delà du vôtre.","ar":"الأخذ بالتجاوز أسر فوري بعد أن يتقدم بيدق الخصم مربعين متجاوزاً بيدقك."}}],"example":{"fen":"7k/P7/8/8/8/8/8/7K w - - 0 1","solutionMoves":["a8=Q+"],"annotation":{"en":"a8=Q+ shows a pawn reaching the last rank and promoting; the resulting queen gives check.","fr":"a8=Q+ montre un pion qui atteint la dernière rangée et est promu ; la dame obtenue donne échec.","ar":"تُظهر a8=Q+ وصول البيدق إلى الصف الأخير وترقيته؛ ثم تكش الملكة الناتجة."}},"commonMistakes":[{"en":"A pawn captures by moving straight forward one square.","fr":"Un pion capture en avançant tout droit d’une case.","ar":"يأسر البيدق بتحركه مربعاً إلى الأمام مباشرة."},{"en":"A pawn may move two squares from any square whenever the path is clear.","fr":"Un pion peut avancer de deux cases depuis n’importe quelle case si le chemin est libre.","ar":"يستطيع البيدق التقدم مربعين من أي مربع متى كان الطريق خالياً."},{"en":"A pawn captures a piece directly in front of it.","fr":"Un pion capture une pièce située directement devant lui.","ar":"يأسر البيدق القطعة الموجودة أمامه مباشرة."},{"en":"A pawn may promote only to a queen and only if a queen has already been captured.","fr":"Un pion ne peut devenir qu’une dame, et seulement si une dame a déjà été capturée.","ar":"لا يترقى البيدق إلا إلى ملكة وبعد أسر ملكة الخصم فقط."},{"en":"En passant can be played at any later time as long as the pawns remain adjacent.","fr":"La prise en passant peut être jouée plus tard tant que les pions restent voisins.","ar":"يمكن تنفيذ الأخذ بالتجاوز في أي وقت لاحق ما دام البيدقان متجاورين."}],"professionalTips":[{"en":"Before moving, pause and ask how Forward movement affects your king safety and your opponent’s best reply.","fr":"Avant de jouer, demandez-vous comment L’avance influence la sécurité de votre roi et la meilleure réponse adverse.","ar":"قبل أن تلعب، فكّر كيف يؤثر التقدم في أمان ملكك وفي أفضل رد للخصم."},{"en":"Before moving, pause and ask how First double step affects your king safety and your opponent’s best reply.","fr":"Avant de jouer, demandez-vous comment La double avance initiale influence la sécurité de votre roi et la meilleure réponse adverse.","ar":"قبل أن تلعب، فكّر كيف يؤثر التقدم المزدوج الأول في أمان ملكك وفي أفضل رد للخصم."},{"en":"Before moving, pause and ask how Captures affects your king safety and your opponent’s best reply.","fr":"Avant de jouer, demandez-vous comment Les prises influence la sécurité de votre roi et la meilleure réponse adverse.","ar":"قبل أن تلعب، فكّر كيف يؤثر الأسر في أمان ملكك وفي أفضل رد للخصم."},{"en":"Before moving, pause and ask how Promotion affects your king safety and your opponent’s best reply.","fr":"Avant de jouer, demandez-vous comment La promotion influence la sécurité de votre roi et la meilleure réponse adverse.","ar":"قبل أن تلعب، فكّر كيف يؤثر الترقية في أمان ملكك وفي أفضل رد للخصم."},{"en":"Before moving, pause and ask how En passant affects your king safety and your opponent’s best reply.","fr":"Avant de jouer, demandez-vous comment La prise en passant influence la sécurité de votre roi et la meilleure réponse adverse.","ar":"قبل أن تلعب، فكّر كيف يؤثر الأخذ بالتجاوز في أمان ملكك وفي أفضل رد للخصم."}],"exercises":[{"en":"Set up a position that demonstrates Forward movement. Name the legal choices and explain why one choice follows the rule.","fr":"Préparez une position illustrant L’avance. Indiquez les choix légaux et expliquez lequel respecte la règle.","ar":"أنشئ وضعية توضّح التقدم. اذكر النقلات القانونية واشرح لماذا تتبع إحداها القاعدة."},{"en":"Set up a position that demonstrates First double step. Name the legal choices and explain why one choice follows the rule.","fr":"Préparez une position illustrant La double avance initiale. Indiquez les choix légaux et expliquez lequel respecte la règle.","ar":"أنشئ وضعية توضّح التقدم المزدوج الأول. اذكر النقلات القانونية واشرح لماذا تتبع إحداها القاعدة."},{"en":"Set up a position that demonstrates Captures. Name the legal choices and explain why one choice follows the rule.","fr":"Préparez une position illustrant Les prises. Indiquez les choix légaux et expliquez lequel respecte la règle.","ar":"أنشئ وضعية توضّح الأسر. اذكر النقلات القانونية واشرح لماذا تتبع إحداها القاعدة."},{"en":"Set up a position that demonstrates Promotion. Name the legal choices and explain why one choice follows the rule.","fr":"Préparez une position illustrant La promotion. Indiquez les choix légaux et expliquez lequel respecte la règle.","ar":"أنشئ وضعية توضّح الترقية. اذكر النقلات القانونية واشرح لماذا تتبع إحداها القاعدة."},{"en":"Set up a position that demonstrates En passant. Name the legal choices and explain why one choice follows the rule.","fr":"Préparez une position illustrant La prise en passant. Indiquez les choix légaux et expliquez lequel respecte la règle.","ar":"أنشئ وضعية توضّح الأخذ بالتجاوز. اذكر النقلات القانونية واشرح لماذا تتبع إحداها القاعدة."}],"takeaways":[{"en":"A pawn normally moves one square forward into an empty square.","fr":"Un pion avance normalement d’une case vers l’avant sur une case vide.","ar":"يتقدم البيدق عادةً مربعاً واحداً إلى الأمام نحو مربع فارغ."},{"en":"From its starting rank, a pawn may advance two squares if both squares are clear.","fr":"Depuis sa rangée de départ, un pion peut avancer de deux cases si les deux sont libres.","ar":"من صف البداية، يمكن للبيدق التقدم مربعين إذا كان كلاهما خالياً."},{"en":"A pawn captures one square diagonally forward, not straight ahead.","fr":"Un pion capture une case en diagonale vers l’avant, jamais tout droit.","ar":"يأسر البيدق مربعاً واحداً قطرياً إلى الأمام وليس مباشرة."},{"en":"When a pawn reaches the last rank, it must promote to a queen, rook, bishop, or knight.","fr":"Lorsqu’un pion atteint la dernière rangée, il doit être promu en dame, tour, fou ou cavalier.","ar":"عندما يصل البيدق إلى الصف الأخير، يجب ترقيته إلى ملكة أو رخ أو فيل أو حصان."},{"en":"En passant is an immediate pawn capture after an opponent advances a pawn two squares past your pawn.","fr":"La prise en passant est une prise immédiate après qu’un pion adverse a avancé de deux cases au-delà du vôtre.","ar":"الأخذ بالتجاوز أسر فوري بعد أن يتقدم بيدق الخصم مربعين متجاوزاً بيدقك."}]}'::jsonb, TRUE) ON CONFLICT (id) DO UPDATE SET level_number = EXCLUDED.level_number, lesson_number = EXCLUDED.lesson_number, title = EXCLUDED.title, summary = EXCLUDED.summary, content = EXCLUDED.content, published = TRUE, updated_at = NOW();
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-08-q01', 'l1-08', 1, 'easy', 'multiple_choice', '{"en":"Which statement correctly describes Forward movement?","fr":"Quelle affirmation décrit correctement L’avance ?","ar":"أي عبارة تصف التقدم بشكل صحيح؟"}'::jsonb, '[{"id":"a","label":{"en":"When a pawn reaches the last rank, it must promote to a queen, rook, bishop, or knight.","fr":"Lorsqu’un pion atteint la dernière rangée, il doit être promu en dame, tour, fou ou cavalier.","ar":"عندما يصل البيدق إلى الصف الأخير، يجب ترقيته إلى ملكة أو رخ أو فيل أو حصان."}},{"id":"b","label":{"en":"A pawn normally moves one square forward into an empty square.","fr":"Un pion avance normalement d’une case vers l’avant sur une case vide.","ar":"يتقدم البيدق عادةً مربعاً واحداً إلى الأمام نحو مربع فارغ."}},{"id":"c","label":{"en":"From its starting rank, a pawn may advance two squares if both squares are clear.","fr":"Depuis sa rangée de départ, un pion peut avancer de deux cases si les deux sont libres.","ar":"من صف البداية، يمكن للبيدق التقدم مربعين إذا كان كلاهما خالياً."}},{"id":"d","label":{"en":"A pawn captures one square diagonally forward, not straight ahead.","fr":"Un pion capture une case en diagonale vers l’avant, jamais tout droit.","ar":"يأسر البيدق مربعاً واحداً قطرياً إلى الأمام وليس مباشرة."}}]'::jsonb, 'b', '{"en":"Pawns do not move backward. White advances toward rank 8 and Black toward rank 1. A pawn cannot move forward into an occupied square.","fr":"Les pions ne reculent pas. Les Blancs avancent vers la rangée 8 et les Noirs vers la rangée 1. Un pion ne peut pas avancer sur une case occupée.","ar":"لا تتراجع البيادق. يتقدم الأبيض نحو الصف 8 والأسود نحو الصف 1، ولا يستطيع البيدق التقدم إلى مربع مشغول."}'::jsonb, '{"en":"Review the rule and compare it with the position. Forward movement","fr":"Relisez la règle et comparez-la à la position. L’avance","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. التقدم"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-08-q02', 'l1-08', 2, 'medium', 'multiple_choice', '{"en":"You are teaching a beginner about Forward movement. Which rule should they apply?","fr":"Vous expliquez L’avance à un débutant. Quelle règle doit-il appliquer ?","ar":"تشرح التقدم لمبتدئ. ما القاعدة التي ينبغي تطبيقها؟"}'::jsonb, '[{"id":"a","label":{"en":"A pawn captures one square diagonally forward, not straight ahead.","fr":"Un pion capture une case en diagonale vers l’avant, jamais tout droit.","ar":"يأسر البيدق مربعاً واحداً قطرياً إلى الأمام وليس مباشرة."}},{"id":"b","label":{"en":"When a pawn reaches the last rank, it must promote to a queen, rook, bishop, or knight.","fr":"Lorsqu’un pion atteint la dernière rangée, il doit être promu en dame, tour, fou ou cavalier.","ar":"عندما يصل البيدق إلى الصف الأخير، يجب ترقيته إلى ملكة أو رخ أو فيل أو حصان."}},{"id":"c","label":{"en":"A pawn normally moves one square forward into an empty square.","fr":"Un pion avance normalement d’une case vers l’avant sur une case vide.","ar":"يتقدم البيدق عادةً مربعاً واحداً إلى الأمام نحو مربع فارغ."}},{"id":"d","label":{"en":"From its starting rank, a pawn may advance two squares if both squares are clear.","fr":"Depuis sa rangée de départ, un pion peut avancer de deux cases si les deux sont libres.","ar":"من صف البداية، يمكن للبيدق التقدم مربعين إذا كان كلاهما خالياً."}}]'::jsonb, 'c', '{"en":"Pawns do not move backward. White advances toward rank 8 and Black toward rank 1. A pawn cannot move forward into an occupied square.","fr":"Les pions ne reculent pas. Les Blancs avancent vers la rangée 8 et les Noirs vers la rangée 1. Un pion ne peut pas avancer sur une case occupée.","ar":"لا تتراجع البيادق. يتقدم الأبيض نحو الصف 8 والأسود نحو الصف 1، ولا يستطيع البيدق التقدم إلى مربع مشغول."}'::jsonb, '{"en":"Review the rule and compare it with the position. Forward movement","fr":"Relisez la règle et comparez-la à la position. L’avance","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. التقدم"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-08-q03', 'l1-08', 3, 'medium', 'true_false', '{"en":"True or false: A pawn normally moves one square forward into an empty square.","fr":"Vrai ou faux : Un pion avance normalement d’une case vers l’avant sur une case vide.","ar":"صح أم خطأ: يتقدم البيدق عادةً مربعاً واحداً إلى الأمام نحو مربع فارغ."}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'true', '{"en":"Pawns do not move backward. White advances toward rank 8 and Black toward rank 1. A pawn cannot move forward into an occupied square.","fr":"Les pions ne reculent pas. Les Blancs avancent vers la rangée 8 et les Noirs vers la rangée 1. Un pion ne peut pas avancer sur une case occupée.","ar":"لا تتراجع البيادق. يتقدم الأبيض نحو الصف 8 والأسود نحو الصف 1، ولا يستطيع البيدق التقدم إلى مربع مشغول."}'::jsonb, '{"en":"Review the rule and compare it with the position. Forward movement","fr":"Relisez la règle et comparez-la à la position. L’avance","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. التقدم"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-08-q04', 'l1-08', 4, 'hard', 'identify_mistake', '{"en":"A student claims: “A pawn captures by moving straight forward one square.” Is the claim correct?","fr":"Un élève affirme : « Un pion capture en avançant tout droit d’une case. » Cette affirmation est-elle correcte ?","ar":"يقول طالب: «يأسر البيدق بتحركه مربعاً إلى الأمام مباشرة.» هل قوله صحيح؟"}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'false', '{"en":"Pawns do not move backward. White advances toward rank 8 and Black toward rank 1. A pawn cannot move forward into an occupied square.","fr":"Les pions ne reculent pas. Les Blancs avancent vers la rangée 8 et les Noirs vers la rangée 1. Un pion ne peut pas avancer sur une case occupée.","ar":"لا تتراجع البيادق. يتقدم الأبيض نحو الصف 8 والأسود نحو الصف 1، ولا يستطيع البيدق التقدم إلى مربع مشغول."}'::jsonb, '{"en":"Review the rule and compare it with the position. Forward movement","fr":"Relisez la règle et comparez-la à la position. L’avance","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. التقدم"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-08-q05', 'l1-08', 5, 'easy', 'multiple_choice', '{"en":"Which statement correctly describes First double step?","fr":"Quelle affirmation décrit correctement La double avance initiale ?","ar":"أي عبارة تصف التقدم المزدوج الأول بشكل صحيح؟"}'::jsonb, '[{"id":"a","label":{"en":"When a pawn reaches the last rank, it must promote to a queen, rook, bishop, or knight.","fr":"Lorsqu’un pion atteint la dernière rangée, il doit être promu en dame, tour, fou ou cavalier.","ar":"عندما يصل البيدق إلى الصف الأخير، يجب ترقيته إلى ملكة أو رخ أو فيل أو حصان."}},{"id":"b","label":{"en":"En passant is an immediate pawn capture after an opponent advances a pawn two squares past your pawn.","fr":"La prise en passant est une prise immédiate après qu’un pion adverse a avancé de deux cases au-delà du vôtre.","ar":"الأخذ بالتجاوز أسر فوري بعد أن يتقدم بيدق الخصم مربعين متجاوزاً بيدقك."}},{"id":"c","label":{"en":"From its starting rank, a pawn may advance two squares if both squares are clear.","fr":"Depuis sa rangée de départ, un pion peut avancer de deux cases si les deux sont libres.","ar":"من صف البداية، يمكن للبيدق التقدم مربعين إذا كان كلاهما خالياً."}},{"id":"d","label":{"en":"A pawn captures one square diagonally forward, not straight ahead.","fr":"Un pion capture une case en diagonale vers l’avant, jamais tout droit.","ar":"يأسر البيدق مربعاً واحداً قطرياً إلى الأمام وليس مباشرة."}}]'::jsonb, 'c', '{"en":"The two-square move is optional, not mandatory. A pawn can make it only from its starting square and cannot jump over a piece on the intermediate square.","fr":"La double avance est facultative. Elle n’est possible que depuis la case de départ et le pion ne peut pas sauter une pièce intermédiaire.","ar":"التقدم مربعين اختياري وليس إلزامياً. لا يحدث إلا من مربع البداية ولا يقفز البيدق فوق قطعة في المربع الوسيط."}'::jsonb, '{"en":"Review the rule and compare it with the position. First double step","fr":"Relisez la règle et comparez-la à la position. La double avance initiale","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. التقدم المزدوج الأول"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-08-q06', 'l1-08', 6, 'medium', 'multiple_choice', '{"en":"You are teaching a beginner about First double step. Which rule should they apply?","fr":"Vous expliquez La double avance initiale à un débutant. Quelle règle doit-il appliquer ?","ar":"تشرح التقدم المزدوج الأول لمبتدئ. ما القاعدة التي ينبغي تطبيقها؟"}'::jsonb, '[{"id":"a","label":{"en":"A pawn captures one square diagonally forward, not straight ahead.","fr":"Un pion capture une case en diagonale vers l’avant, jamais tout droit.","ar":"يأسر البيدق مربعاً واحداً قطرياً إلى الأمام وليس مباشرة."}},{"id":"b","label":{"en":"When a pawn reaches the last rank, it must promote to a queen, rook, bishop, or knight.","fr":"Lorsqu’un pion atteint la dernière rangée, il doit être promu en dame, tour, fou ou cavalier.","ar":"عندما يصل البيدق إلى الصف الأخير، يجب ترقيته إلى ملكة أو رخ أو فيل أو حصان."}},{"id":"c","label":{"en":"En passant is an immediate pawn capture after an opponent advances a pawn two squares past your pawn.","fr":"La prise en passant est une prise immédiate après qu’un pion adverse a avancé de deux cases au-delà du vôtre.","ar":"الأخذ بالتجاوز أسر فوري بعد أن يتقدم بيدق الخصم مربعين متجاوزاً بيدقك."}},{"id":"d","label":{"en":"From its starting rank, a pawn may advance two squares if both squares are clear.","fr":"Depuis sa rangée de départ, un pion peut avancer de deux cases si les deux sont libres.","ar":"من صف البداية، يمكن للبيدق التقدم مربعين إذا كان كلاهما خالياً."}}]'::jsonb, 'd', '{"en":"The two-square move is optional, not mandatory. A pawn can make it only from its starting square and cannot jump over a piece on the intermediate square.","fr":"La double avance est facultative. Elle n’est possible que depuis la case de départ et le pion ne peut pas sauter une pièce intermédiaire.","ar":"التقدم مربعين اختياري وليس إلزامياً. لا يحدث إلا من مربع البداية ولا يقفز البيدق فوق قطعة في المربع الوسيط."}'::jsonb, '{"en":"Review the rule and compare it with the position. First double step","fr":"Relisez la règle et comparez-la à la position. La double avance initiale","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. التقدم المزدوج الأول"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-08-q07', 'l1-08', 7, 'medium', 'true_false', '{"en":"True or false: From its starting rank, a pawn may advance two squares if both squares are clear.","fr":"Vrai ou faux : Depuis sa rangée de départ, un pion peut avancer de deux cases si les deux sont libres.","ar":"صح أم خطأ: من صف البداية، يمكن للبيدق التقدم مربعين إذا كان كلاهما خالياً."}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'true', '{"en":"The two-square move is optional, not mandatory. A pawn can make it only from its starting square and cannot jump over a piece on the intermediate square.","fr":"La double avance est facultative. Elle n’est possible que depuis la case de départ et le pion ne peut pas sauter une pièce intermédiaire.","ar":"التقدم مربعين اختياري وليس إلزامياً. لا يحدث إلا من مربع البداية ولا يقفز البيدق فوق قطعة في المربع الوسيط."}'::jsonb, '{"en":"Review the rule and compare it with the position. First double step","fr":"Relisez la règle et comparez-la à la position. La double avance initiale","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. التقدم المزدوج الأول"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-08-q08', 'l1-08', 8, 'hard', 'identify_mistake', '{"en":"A student claims: “A pawn may move two squares from any square whenever the path is clear.” Is the claim correct?","fr":"Un élève affirme : « Un pion peut avancer de deux cases depuis n’importe quelle case si le chemin est libre. » Cette affirmation est-elle correcte ?","ar":"يقول طالب: «يستطيع البيدق التقدم مربعين من أي مربع متى كان الطريق خالياً.» هل قوله صحيح؟"}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'false', '{"en":"The two-square move is optional, not mandatory. A pawn can make it only from its starting square and cannot jump over a piece on the intermediate square.","fr":"La double avance est facultative. Elle n’est possible que depuis la case de départ et le pion ne peut pas sauter une pièce intermédiaire.","ar":"التقدم مربعين اختياري وليس إلزامياً. لا يحدث إلا من مربع البداية ولا يقفز البيدق فوق قطعة في المربع الوسيط."}'::jsonb, '{"en":"Review the rule and compare it with the position. First double step","fr":"Relisez la règle et comparez-la à la position. La double avance initiale","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. التقدم المزدوج الأول"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-08-q09', 'l1-08', 9, 'easy', 'multiple_choice', '{"en":"Which statement correctly describes Captures?","fr":"Quelle affirmation décrit correctement Les prises ?","ar":"أي عبارة تصف الأسر بشكل صحيح؟"}'::jsonb, '[{"id":"a","label":{"en":"When a pawn reaches the last rank, it must promote to a queen, rook, bishop, or knight.","fr":"Lorsqu’un pion atteint la dernière rangée, il doit être promu en dame, tour, fou ou cavalier.","ar":"عندما يصل البيدق إلى الصف الأخير، يجب ترقيته إلى ملكة أو رخ أو فيل أو حصان."}},{"id":"b","label":{"en":"En passant is an immediate pawn capture after an opponent advances a pawn two squares past your pawn.","fr":"La prise en passant est une prise immédiate après qu’un pion adverse a avancé de deux cases au-delà du vôtre.","ar":"الأخذ بالتجاوز أسر فوري بعد أن يتقدم بيدق الخصم مربعين متجاوزاً بيدقك."}},{"id":"c","label":{"en":"A pawn normally moves one square forward into an empty square.","fr":"Un pion avance normalement d’une case vers l’avant sur une case vide.","ar":"يتقدم البيدق عادةً مربعاً واحداً إلى الأمام نحو مربع فارغ."}},{"id":"d","label":{"en":"A pawn captures one square diagonally forward, not straight ahead.","fr":"Un pion capture une case en diagonale vers l’avant, jamais tout droit.","ar":"يأسر البيدق مربعاً واحداً قطرياً إلى الأمام وليس مباشرة."}}]'::jsonb, 'd', '{"en":"A pawn moves and captures differently: forward for a quiet move, diagonal for a capture. It cannot capture a piece behind it or on an adjacent file without moving forward.","fr":"Le pion se déplace et capture différemment : tout droit pour avancer, en diagonale pour prendre. Il ne capture ni derrière lui ni horizontalement.","ar":"تختلف حركة البيدق عن أسره: يتقدم مباشرة ويأسر قطرياً. لا يأسر خلفه أو أفقياً إلى مربع مجاور."}'::jsonb, '{"en":"Review the rule and compare it with the position. Captures","fr":"Relisez la règle et comparez-la à la position. Les prises","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. الأسر"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-08-q10', 'l1-08', 10, 'medium', 'multiple_choice', '{"en":"You are teaching a beginner about Captures. Which rule should they apply?","fr":"Vous expliquez Les prises à un débutant. Quelle règle doit-il appliquer ?","ar":"تشرح الأسر لمبتدئ. ما القاعدة التي ينبغي تطبيقها؟"}'::jsonb, '[{"id":"a","label":{"en":"A pawn captures one square diagonally forward, not straight ahead.","fr":"Un pion capture une case en diagonale vers l’avant, jamais tout droit.","ar":"يأسر البيدق مربعاً واحداً قطرياً إلى الأمام وليس مباشرة."}},{"id":"b","label":{"en":"When a pawn reaches the last rank, it must promote to a queen, rook, bishop, or knight.","fr":"Lorsqu’un pion atteint la dernière rangée, il doit être promu en dame, tour, fou ou cavalier.","ar":"عندما يصل البيدق إلى الصف الأخير، يجب ترقيته إلى ملكة أو رخ أو فيل أو حصان."}},{"id":"c","label":{"en":"En passant is an immediate pawn capture after an opponent advances a pawn two squares past your pawn.","fr":"La prise en passant est une prise immédiate après qu’un pion adverse a avancé de deux cases au-delà du vôtre.","ar":"الأخذ بالتجاوز أسر فوري بعد أن يتقدم بيدق الخصم مربعين متجاوزاً بيدقك."}},{"id":"d","label":{"en":"A pawn normally moves one square forward into an empty square.","fr":"Un pion avance normalement d’une case vers l’avant sur une case vide.","ar":"يتقدم البيدق عادةً مربعاً واحداً إلى الأمام نحو مربع فارغ."}}]'::jsonb, 'a', '{"en":"A pawn moves and captures differently: forward for a quiet move, diagonal for a capture. It cannot capture a piece behind it or on an adjacent file without moving forward.","fr":"Le pion se déplace et capture différemment : tout droit pour avancer, en diagonale pour prendre. Il ne capture ni derrière lui ni horizontalement.","ar":"تختلف حركة البيدق عن أسره: يتقدم مباشرة ويأسر قطرياً. لا يأسر خلفه أو أفقياً إلى مربع مجاور."}'::jsonb, '{"en":"Review the rule and compare it with the position. Captures","fr":"Relisez la règle et comparez-la à la position. Les prises","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. الأسر"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-08-q11', 'l1-08', 11, 'medium', 'true_false', '{"en":"True or false: A pawn captures one square diagonally forward, not straight ahead.","fr":"Vrai ou faux : Un pion capture une case en diagonale vers l’avant, jamais tout droit.","ar":"صح أم خطأ: يأسر البيدق مربعاً واحداً قطرياً إلى الأمام وليس مباشرة."}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'true', '{"en":"A pawn moves and captures differently: forward for a quiet move, diagonal for a capture. It cannot capture a piece behind it or on an adjacent file without moving forward.","fr":"Le pion se déplace et capture différemment : tout droit pour avancer, en diagonale pour prendre. Il ne capture ni derrière lui ni horizontalement.","ar":"تختلف حركة البيدق عن أسره: يتقدم مباشرة ويأسر قطرياً. لا يأسر خلفه أو أفقياً إلى مربع مجاور."}'::jsonb, '{"en":"Review the rule and compare it with the position. Captures","fr":"Relisez la règle et comparez-la à la position. Les prises","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. الأسر"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-08-q12', 'l1-08', 12, 'hard', 'identify_mistake', '{"en":"A student claims: “A pawn captures a piece directly in front of it.” Is the claim correct?","fr":"Un élève affirme : « Un pion capture une pièce située directement devant lui. » Cette affirmation est-elle correcte ?","ar":"يقول طالب: «يأسر البيدق القطعة الموجودة أمامه مباشرة.» هل قوله صحيح؟"}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'false', '{"en":"A pawn moves and captures differently: forward for a quiet move, diagonal for a capture. It cannot capture a piece behind it or on an adjacent file without moving forward.","fr":"Le pion se déplace et capture différemment : tout droit pour avancer, en diagonale pour prendre. Il ne capture ni derrière lui ni horizontalement.","ar":"تختلف حركة البيدق عن أسره: يتقدم مباشرة ويأسر قطرياً. لا يأسر خلفه أو أفقياً إلى مربع مجاور."}'::jsonb, '{"en":"Review the rule and compare it with the position. Captures","fr":"Relisez la règle et comparez-la à la position. Les prises","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. الأسر"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-08-q13', 'l1-08', 13, 'easy', 'multiple_choice', '{"en":"Which statement correctly describes Promotion?","fr":"Quelle affirmation décrit correctement La promotion ?","ar":"أي عبارة تصف الترقية بشكل صحيح؟"}'::jsonb, '[{"id":"a","label":{"en":"When a pawn reaches the last rank, it must promote to a queen, rook, bishop, or knight.","fr":"Lorsqu’un pion atteint la dernière rangée, il doit être promu en dame, tour, fou ou cavalier.","ar":"عندما يصل البيدق إلى الصف الأخير، يجب ترقيته إلى ملكة أو رخ أو فيل أو حصان."}},{"id":"b","label":{"en":"En passant is an immediate pawn capture after an opponent advances a pawn two squares past your pawn.","fr":"La prise en passant est une prise immédiate après qu’un pion adverse a avancé de deux cases au-delà du vôtre.","ar":"الأخذ بالتجاوز أسر فوري بعد أن يتقدم بيدق الخصم مربعين متجاوزاً بيدقك."}},{"id":"c","label":{"en":"A pawn normally moves one square forward into an empty square.","fr":"Un pion avance normalement d’une case vers l’avant sur une case vide.","ar":"يتقدم البيدق عادةً مربعاً واحداً إلى الأمام نحو مربع فارغ."}},{"id":"d","label":{"en":"From its starting rank, a pawn may advance two squares if both squares are clear.","fr":"Depuis sa rangée de départ, un pion peut avancer de deux cases si les deux sont libres.","ar":"من صف البداية، يمكن للبيدق التقدم مربعين إذا كان كلاهما خالياً."}}]'::jsonb, 'a', '{"en":"Promotion happens immediately on reaching the last rank. A pawn cannot become a king, and choosing a piece other than a queen is called underpromotion.","fr":"La promotion a lieu dès l’arrivée sur la dernière rangée. Le pion ne peut pas devenir roi ; choisir une pièce autre que la dame est une sous-promotion.","ar":"تحدث الترقية فور الوصول إلى الصف الأخير. لا يتحول البيدق إلى ملك، واختيار قطعة غير الملكة يسمى ترقية ناقصة."}'::jsonb, '{"en":"Review the rule and compare it with the position. Promotion","fr":"Relisez la règle et comparez-la à la position. La promotion","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. الترقية"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-08-q14', 'l1-08', 14, 'medium', 'multiple_choice', '{"en":"You are teaching a beginner about Promotion. Which rule should they apply?","fr":"Vous expliquez La promotion à un débutant. Quelle règle doit-il appliquer ?","ar":"تشرح الترقية لمبتدئ. ما القاعدة التي ينبغي تطبيقها؟"}'::jsonb, '[{"id":"a","label":{"en":"From its starting rank, a pawn may advance two squares if both squares are clear.","fr":"Depuis sa rangée de départ, un pion peut avancer de deux cases si les deux sont libres.","ar":"من صف البداية، يمكن للبيدق التقدم مربعين إذا كان كلاهما خالياً."}},{"id":"b","label":{"en":"When a pawn reaches the last rank, it must promote to a queen, rook, bishop, or knight.","fr":"Lorsqu’un pion atteint la dernière rangée, il doit être promu en dame, tour, fou ou cavalier.","ar":"عندما يصل البيدق إلى الصف الأخير، يجب ترقيته إلى ملكة أو رخ أو فيل أو حصان."}},{"id":"c","label":{"en":"En passant is an immediate pawn capture after an opponent advances a pawn two squares past your pawn.","fr":"La prise en passant est une prise immédiate après qu’un pion adverse a avancé de deux cases au-delà du vôtre.","ar":"الأخذ بالتجاوز أسر فوري بعد أن يتقدم بيدق الخصم مربعين متجاوزاً بيدقك."}},{"id":"d","label":{"en":"A pawn normally moves one square forward into an empty square.","fr":"Un pion avance normalement d’une case vers l’avant sur une case vide.","ar":"يتقدم البيدق عادةً مربعاً واحداً إلى الأمام نحو مربع فارغ."}}]'::jsonb, 'b', '{"en":"Promotion happens immediately on reaching the last rank. A pawn cannot become a king, and choosing a piece other than a queen is called underpromotion.","fr":"La promotion a lieu dès l’arrivée sur la dernière rangée. Le pion ne peut pas devenir roi ; choisir une pièce autre que la dame est une sous-promotion.","ar":"تحدث الترقية فور الوصول إلى الصف الأخير. لا يتحول البيدق إلى ملك، واختيار قطعة غير الملكة يسمى ترقية ناقصة."}'::jsonb, '{"en":"Review the rule and compare it with the position. Promotion","fr":"Relisez la règle et comparez-la à la position. La promotion","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. الترقية"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-08-q15', 'l1-08', 15, 'medium', 'true_false', '{"en":"True or false: When a pawn reaches the last rank, it must promote to a queen, rook, bishop, or knight.","fr":"Vrai ou faux : Lorsqu’un pion atteint la dernière rangée, il doit être promu en dame, tour, fou ou cavalier.","ar":"صح أم خطأ: عندما يصل البيدق إلى الصف الأخير، يجب ترقيته إلى ملكة أو رخ أو فيل أو حصان."}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'true', '{"en":"Promotion happens immediately on reaching the last rank. A pawn cannot become a king, and choosing a piece other than a queen is called underpromotion.","fr":"La promotion a lieu dès l’arrivée sur la dernière rangée. Le pion ne peut pas devenir roi ; choisir une pièce autre que la dame est une sous-promotion.","ar":"تحدث الترقية فور الوصول إلى الصف الأخير. لا يتحول البيدق إلى ملك، واختيار قطعة غير الملكة يسمى ترقية ناقصة."}'::jsonb, '{"en":"Review the rule and compare it with the position. Promotion","fr":"Relisez la règle et comparez-la à la position. La promotion","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. الترقية"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-08-q16', 'l1-08', 16, 'hard', 'identify_mistake', '{"en":"A student claims: “A pawn may promote only to a queen and only if a queen has already been captured.” Is the claim correct?","fr":"Un élève affirme : « Un pion ne peut devenir qu’une dame, et seulement si une dame a déjà été capturée. » Cette affirmation est-elle correcte ?","ar":"يقول طالب: «لا يترقى البيدق إلا إلى ملكة وبعد أسر ملكة الخصم فقط.» هل قوله صحيح؟"}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'false', '{"en":"Promotion happens immediately on reaching the last rank. A pawn cannot become a king, and choosing a piece other than a queen is called underpromotion.","fr":"La promotion a lieu dès l’arrivée sur la dernière rangée. Le pion ne peut pas devenir roi ; choisir une pièce autre que la dame est une sous-promotion.","ar":"تحدث الترقية فور الوصول إلى الصف الأخير. لا يتحول البيدق إلى ملك، واختيار قطعة غير الملكة يسمى ترقية ناقصة."}'::jsonb, '{"en":"Review the rule and compare it with the position. Promotion","fr":"Relisez la règle et comparez-la à la position. La promotion","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. الترقية"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-08-q17', 'l1-08', 17, 'easy', 'multiple_choice', '{"en":"Which statement correctly describes En passant?","fr":"Quelle affirmation décrit correctement La prise en passant ?","ar":"أي عبارة تصف الأخذ بالتجاوز بشكل صحيح؟"}'::jsonb, '[{"id":"a","label":{"en":"A pawn captures one square diagonally forward, not straight ahead.","fr":"Un pion capture une case en diagonale vers l’avant, jamais tout droit.","ar":"يأسر البيدق مربعاً واحداً قطرياً إلى الأمام وليس مباشرة."}},{"id":"b","label":{"en":"En passant is an immediate pawn capture after an opponent advances a pawn two squares past your pawn.","fr":"La prise en passant est une prise immédiate après qu’un pion adverse a avancé de deux cases au-delà du vôtre.","ar":"الأخذ بالتجاوز أسر فوري بعد أن يتقدم بيدق الخصم مربعين متجاوزاً بيدقك."}},{"id":"c","label":{"en":"A pawn normally moves one square forward into an empty square.","fr":"Un pion avance normalement d’une case vers l’avant sur une case vide.","ar":"يتقدم البيدق عادةً مربعاً واحداً إلى الأمام نحو مربع فارغ."}},{"id":"d","label":{"en":"From its starting rank, a pawn may advance two squares if both squares are clear.","fr":"Depuis sa rangée de départ, un pion peut avancer de deux cases si les deux sont libres.","ar":"من صف البداية، يمكن للبيدق التقدم مربعين إذا كان كلاهما خالياً."}}]'::jsonb, 'b', '{"en":"The capturing pawn moves diagonally to the square the opposing pawn passed over, and the opposing pawn is removed. If you do not take en passant on the very next move, the right expires.","fr":"Le pion preneur avance en diagonale sur la case traversée et le pion adverse est retiré. Si la prise n’est pas jouée immédiatement, le droit disparaît.","ar":"يتحرك البيدق الآسر قطرياً إلى المربع الذي تجاوزه بيدق الخصم، ثم يُزال البيدق. إذا لم تنفذها فوراً، يسقط الحق بها."}'::jsonb, '{"en":"Review the rule and compare it with the position. En passant","fr":"Relisez la règle et comparez-la à la position. La prise en passant","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. الأخذ بالتجاوز"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-08-q18', 'l1-08', 18, 'medium', 'multiple_choice', '{"en":"You are teaching a beginner about En passant. Which rule should they apply?","fr":"Vous expliquez La prise en passant à un débutant. Quelle règle doit-il appliquer ?","ar":"تشرح الأخذ بالتجاوز لمبتدئ. ما القاعدة التي ينبغي تطبيقها؟"}'::jsonb, '[{"id":"a","label":{"en":"From its starting rank, a pawn may advance two squares if both squares are clear.","fr":"Depuis sa rangée de départ, un pion peut avancer de deux cases si les deux sont libres.","ar":"من صف البداية، يمكن للبيدق التقدم مربعين إذا كان كلاهما خالياً."}},{"id":"b","label":{"en":"A pawn captures one square diagonally forward, not straight ahead.","fr":"Un pion capture une case en diagonale vers l’avant, jamais tout droit.","ar":"يأسر البيدق مربعاً واحداً قطرياً إلى الأمام وليس مباشرة."}},{"id":"c","label":{"en":"En passant is an immediate pawn capture after an opponent advances a pawn two squares past your pawn.","fr":"La prise en passant est une prise immédiate après qu’un pion adverse a avancé de deux cases au-delà du vôtre.","ar":"الأخذ بالتجاوز أسر فوري بعد أن يتقدم بيدق الخصم مربعين متجاوزاً بيدقك."}},{"id":"d","label":{"en":"A pawn normally moves one square forward into an empty square.","fr":"Un pion avance normalement d’une case vers l’avant sur une case vide.","ar":"يتقدم البيدق عادةً مربعاً واحداً إلى الأمام نحو مربع فارغ."}}]'::jsonb, 'c', '{"en":"The capturing pawn moves diagonally to the square the opposing pawn passed over, and the opposing pawn is removed. If you do not take en passant on the very next move, the right expires.","fr":"Le pion preneur avance en diagonale sur la case traversée et le pion adverse est retiré. Si la prise n’est pas jouée immédiatement, le droit disparaît.","ar":"يتحرك البيدق الآسر قطرياً إلى المربع الذي تجاوزه بيدق الخصم، ثم يُزال البيدق. إذا لم تنفذها فوراً، يسقط الحق بها."}'::jsonb, '{"en":"Review the rule and compare it with the position. En passant","fr":"Relisez la règle et comparez-la à la position. La prise en passant","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. الأخذ بالتجاوز"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-08-q19', 'l1-08', 19, 'medium', 'true_false', '{"en":"True or false: En passant is an immediate pawn capture after an opponent advances a pawn two squares past your pawn.","fr":"Vrai ou faux : La prise en passant est une prise immédiate après qu’un pion adverse a avancé de deux cases au-delà du vôtre.","ar":"صح أم خطأ: الأخذ بالتجاوز أسر فوري بعد أن يتقدم بيدق الخصم مربعين متجاوزاً بيدقك."}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'true', '{"en":"The capturing pawn moves diagonally to the square the opposing pawn passed over, and the opposing pawn is removed. If you do not take en passant on the very next move, the right expires.","fr":"Le pion preneur avance en diagonale sur la case traversée et le pion adverse est retiré. Si la prise n’est pas jouée immédiatement, le droit disparaît.","ar":"يتحرك البيدق الآسر قطرياً إلى المربع الذي تجاوزه بيدق الخصم، ثم يُزال البيدق. إذا لم تنفذها فوراً، يسقط الحق بها."}'::jsonb, '{"en":"Review the rule and compare it with the position. En passant","fr":"Relisez la règle et comparez-la à la position. La prise en passant","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. الأخذ بالتجاوز"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-08-q20', 'l1-08', 20, 'hard', 'best_move', '{"en":"On the board, make a legal move that demonstrates En passant.","fr":"Sur l’échiquier, jouez un coup légal qui illustre La prise en passant.","ar":"نفّذ على الرقعة نقلة قانونية توضح الأخذ بالتجاوز."}'::jsonb, '[{"id":"a8=R+","label":{"en":"a8=R+","fr":"a8=R+","ar":"a8=R+"}},{"id":"a8=Q+","label":{"en":"a8=Q+","fr":"a8=Q+","ar":"a8=Q+"}},{"id":"a8=N","label":{"en":"a8=N","fr":"a8=N","ar":"a8=N"}},{"id":"a8=B","label":{"en":"a8=B","fr":"a8=B","ar":"a8=B"}}]'::jsonb, 'a8=Q+', '{"en":"a8=Q+ shows a pawn reaching the last rank and promoting; the resulting queen gives check.","fr":"a8=Q+ montre un pion qui atteint la dernière rangée et est promu ; la dame obtenue donne échec.","ar":"تُظهر a8=Q+ وصول البيدق إلى الصف الأخير وترقيته؛ ثم تكش الملكة الناتجة."}'::jsonb, '{"en":"Review the rule and compare it with the position. En passant","fr":"Relisez la règle et comparez-la à la position. La prise en passant","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. الأخذ بالتجاوز"}'::jsonb, '7k/P7/8/8/8/8/8/7K w - - 0 1', '["a8=Q+"]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_lessons (id, level_number, lesson_number, title, summary, content, published) VALUES ('l1-09', 1, 9, '{"en":"Understanding Check, Checkmate and Stalemate","fr":"Comprendre l’échec, le mat et le pat","ar":"فهم الكش وكش مات والجمود"}'::jsonb, '{"en":"Distinguish check, checkmate, and stalemate, and learn how to respond to threats against the king.","fr":"Distinguez l’échec, le mat et le pat, et apprenez à répondre aux menaces contre le roi.","ar":"ميّز بين الكش وكش مات والجمود وتعلّم الرد على تهديدات الملك."}'::jsonb, '{"objectives":[{"en":"Check","fr":"L’échec","ar":"الكش"},{"en":"Checkmate","fr":"L’échec et mat","ar":"كش مات"},{"en":"Stalemate","fr":"Le pat","ar":"الجمود"},{"en":"Three ways to answer check","fr":"Trois façons de parer l’échec","ar":"ثلاث وسائل للرد على الكش"},{"en":"Delivering mate","fr":"Donner échec et mat","ar":"تنفيذ كش مات"}],"sections":[{"title":{"en":"Check","fr":"L’échec","ar":"الكش"},"paragraphs":[{"en":"A king is in check when an opposing piece attacks its square.","fr":"Un roi est en échec lorsqu’une pièce adverse attaque sa case.","ar":"يكون الملك في كش عندما تهاجم قطعة للخصم مربعه."},{"en":"Check must be answered on the very next move. A player may not leave their king in check or make a move that exposes it to check.","fr":"Il faut parer l’échec au coup suivant. On ne peut pas laisser son roi en échec ni jouer un coup qui l’y expose.","ar":"يجب الرد على الكش في النقلة التالية. لا يجوز ترك الملك في كش أو تنفيذ نقلة تكشفه له."},{"en":"Practice checkpoint: identify Check on a board, explain the rule, and check how the opponent could respond.","fr":"Mise en pratique : repérez L’échec sur un échiquier, expliquez la règle et vérifiez la réponse possible de l’adversaire.","ar":"تطبيق عملي: حدّد الكش على الرقعة، واشرح القاعدة، ثم تحقّق من رد الخصم الممكن."}]},{"title":{"en":"Checkmate","fr":"L’échec et mat","ar":"كش مات"},"paragraphs":[{"en":"Checkmate occurs when the king is in check and no legal move can remove the threat.","fr":"Il y a échec et mat lorsque le roi est en échec et qu’aucun coup légal ne peut parer la menace.","ar":"يحدث كش مات عندما يكون الملك في كش ولا توجد نقلة قانونية تزيل التهديد."},{"en":"Test every possible defense: king moves, captures of the checking piece, and blocks against sliding attacks. If none work, the game ends immediately with a win for the attacker.","fr":"Vérifiez les déplacements du roi, la capture de l’attaquant et la parade d’une attaque à distance. Si aucune défense ne fonctionne, la partie se termine par une victoire.","ar":"افحص تحركات الملك وأسر القطعة المهاجمة وصد الهجوم الخطي. إن لم تنجح أي وسيلة، تنتهي المباراة بفوز المهاجم."},{"en":"Practice checkpoint: identify Checkmate on a board, explain the rule, and check how the opponent could respond.","fr":"Mise en pratique : repérez L’échec et mat sur un échiquier, expliquez la règle et vérifiez la réponse possible de l’adversaire.","ar":"تطبيق عملي: حدّد كش مات على الرقعة، واشرح القاعدة، ثم تحقّق من رد الخصم الممكن."}]},{"title":{"en":"Stalemate","fr":"Le pat","ar":"الجمود"},"paragraphs":[{"en":"Stalemate is a draw when the player to move is not in check but has no legal move.","fr":"Le pat est une partie nulle lorsque le joueur au trait n’est pas en échec mais n’a aucun coup légal.","ar":"الجمود تعادل عندما لا يكون اللاعب الذي عليه الدور في كش ولا يملك أي نقلة قانونية."},{"en":"Stalemate is not checkmate. A player who is ahead in material must avoid removing every legal move unless the king is actually checkmated.","fr":"Le pat n’est pas un échec et mat. Un joueur en avantage matériel doit éviter de supprimer tous les coups légaux si le roi n’est pas réellement mat.","ar":"الجمود ليس كش مات. على المتقدم مادياً تجنب سلب الخصم كل النقلات القانونية ما لم يكن ملكه في كش مات فعلياً."},{"en":"Practice checkpoint: identify Stalemate on a board, explain the rule, and check how the opponent could respond.","fr":"Mise en pratique : repérez Le pat sur un échiquier, expliquez la règle et vérifiez la réponse possible de l’adversaire.","ar":"تطبيق عملي: حدّد الجمود على الرقعة، واشرح القاعدة، ثم تحقّق من رد الخصم الممكن."}]},{"title":{"en":"Three ways to answer check","fr":"Trois façons de parer l’échec","ar":"ثلاث وسائل للرد على الكش"},"paragraphs":[{"en":"A check may be answered by moving the king, capturing the attacker, or blocking a sliding attack when possible.","fr":"On peut parer l’échec en déplaçant le roi, en capturant l’attaquant ou en bloquant une attaque à distance si possible.","ar":"يمكن الرد على الكش بتحريك الملك أو أسر المهاجم أو صد الهجوم الخطي إن أمكن."},{"en":"Not every check permits all three defenses. A knight check cannot be blocked, and a double check normally requires moving the king. Analyze the actual geometry of the attack.","fr":"Toutes les défenses ne sont pas possibles contre chaque échec. On ne bloque pas un échec de cavalier et un double échec impose généralement de bouger le roi.","ar":"لا تتاح الوسائل الثلاث لكل كش. لا يمكن صد كش الحصان، والكش المزدوج يتطلب عادةً تحريك الملك. افحص شكل الهجوم."},{"en":"Practice checkpoint: identify Three ways to answer check on a board, explain the rule, and check how the opponent could respond.","fr":"Mise en pratique : repérez Trois façons de parer l’échec sur un échiquier, expliquez la règle et vérifiez la réponse possible de l’adversaire.","ar":"تطبيق عملي: حدّد ثلاث وسائل للرد على الكش على الرقعة، واشرح القاعدة، ثم تحقّق من رد الخصم الممكن."}]},{"title":{"en":"Delivering mate","fr":"Donner échec et mat","ar":"تنفيذ كش مات"},"paragraphs":[{"en":"A mating move must attack the king and leave the opponent with no legal escape or defense.","fr":"Un coup de mat doit attaquer le roi et ne laisser aucune fuite ni défense légale.","ar":"يجب أن تهاجم نقلة المات الملك وألا تترك للخصم مهرباً أو دفاعاً قانونياً."},{"en":"Before announcing mate, check captures, king escapes, and blocks. A move that merely attacks the king is check, not mate, if even one legal defense remains.","fr":"Avant d’annoncer le mat, vérifiez les captures, les fuites du roi et les parades. S’il reste une seule défense légale, il s’agit seulement d’un échec.","ar":"قبل إعلان المات، افحص الأسر وهروب الملك والصد. إذا بقي دفاع قانوني واحد، فهذه نقلة كش وليست مات."},{"en":"Practice checkpoint: identify Delivering mate on a board, explain the rule, and check how the opponent could respond.","fr":"Mise en pratique : repérez Donner échec et mat sur un échiquier, expliquez la règle et vérifiez la réponse possible de l’adversaire.","ar":"تطبيق عملي: حدّد تنفيذ كش مات على الرقعة، واشرح القاعدة، ثم تحقّق من رد الخصم الممكن."}]}],"terminology":[{"term":{"en":"Check","fr":"L’échec","ar":"الكش"},"definition":{"en":"A king is in check when an opposing piece attacks its square.","fr":"Un roi est en échec lorsqu’une pièce adverse attaque sa case.","ar":"يكون الملك في كش عندما تهاجم قطعة للخصم مربعه."}},{"term":{"en":"Checkmate","fr":"L’échec et mat","ar":"كش مات"},"definition":{"en":"Checkmate occurs when the king is in check and no legal move can remove the threat.","fr":"Il y a échec et mat lorsque le roi est en échec et qu’aucun coup légal ne peut parer la menace.","ar":"يحدث كش مات عندما يكون الملك في كش ولا توجد نقلة قانونية تزيل التهديد."}},{"term":{"en":"Stalemate","fr":"Le pat","ar":"الجمود"},"definition":{"en":"Stalemate is a draw when the player to move is not in check but has no legal move.","fr":"Le pat est une partie nulle lorsque le joueur au trait n’est pas en échec mais n’a aucun coup légal.","ar":"الجمود تعادل عندما لا يكون اللاعب الذي عليه الدور في كش ولا يملك أي نقلة قانونية."}},{"term":{"en":"Three ways to answer check","fr":"Trois façons de parer l’échec","ar":"ثلاث وسائل للرد على الكش"},"definition":{"en":"A check may be answered by moving the king, capturing the attacker, or blocking a sliding attack when possible.","fr":"On peut parer l’échec en déplaçant le roi, en capturant l’attaquant ou en bloquant une attaque à distance si possible.","ar":"يمكن الرد على الكش بتحريك الملك أو أسر المهاجم أو صد الهجوم الخطي إن أمكن."}},{"term":{"en":"Delivering mate","fr":"Donner échec et mat","ar":"تنفيذ كش مات"},"definition":{"en":"A mating move must attack the king and leave the opponent with no legal escape or defense.","fr":"Un coup de mat doit attaquer le roi et ne laisser aucune fuite ni défense légale.","ar":"يجب أن تهاجم نقلة المات الملك وألا تترك للخصم مهرباً أو دفاعاً قانونياً."}}],"example":{"fen":"7k/8/5KQ1/8/8/8/8/8 w - - 0 1","solutionMoves":["Qg7#"],"annotation":{"en":"Qg7# is checkmate: the queen checks the king and the white king protects the queen’s mating square.","fr":"Qg7# est mat : la dame attaque le roi et le roi blanc protège la case de mat.","ar":"Qg7# كش مات: تهاجم الملكة الملك ويحمي الملك الأبيض مربع المات."}},"commonMistakes":[{"en":"Check is optional to answer if the player can capture another piece.","fr":"Il est facultatif de parer l’échec si l’on peut capturer une autre pièce.","ar":"الرد على الكش اختياري إذا استطاع اللاعب أسر قطعة أخرى."},{"en":"Checkmate means the king is attacked but may still escape on the next turn.","fr":"Le mat signifie que le roi est attaqué mais pourra fuir au prochain tour.","ar":"يعني كش مات أن الملك مهدد لكنه يستطيع الهرب في الدور التالي."},{"en":"Stalemate is a win for the player who has more pieces.","fr":"Le pat est une victoire du joueur qui possède le plus de pièces.","ar":"الجمود فوز للاعب الذي يملك قطعاً أكثر."},{"en":"Every check can be blocked by placing any piece between attacker and king.","fr":"On peut parer tout échec en plaçant n’importe quelle pièce entre l’attaquant et le roi.","ar":"يمكن صد كل كش بوضع أي قطعة بين المهاجم والملك."},{"en":"Any attack that gives check is automatically checkmate.","fr":"Toute attaque qui donne échec est automatiquement un mat.","ar":"كل هجوم يسبب كش هو كش مات تلقائياً."}],"professionalTips":[{"en":"Before moving, pause and ask how Check affects your king safety and your opponent’s best reply.","fr":"Avant de jouer, demandez-vous comment L’échec influence la sécurité de votre roi et la meilleure réponse adverse.","ar":"قبل أن تلعب، فكّر كيف يؤثر الكش في أمان ملكك وفي أفضل رد للخصم."},{"en":"Before moving, pause and ask how Checkmate affects your king safety and your opponent’s best reply.","fr":"Avant de jouer, demandez-vous comment L’échec et mat influence la sécurité de votre roi et la meilleure réponse adverse.","ar":"قبل أن تلعب، فكّر كيف يؤثر كش مات في أمان ملكك وفي أفضل رد للخصم."},{"en":"Before moving, pause and ask how Stalemate affects your king safety and your opponent’s best reply.","fr":"Avant de jouer, demandez-vous comment Le pat influence la sécurité de votre roi et la meilleure réponse adverse.","ar":"قبل أن تلعب، فكّر كيف يؤثر الجمود في أمان ملكك وفي أفضل رد للخصم."},{"en":"Before moving, pause and ask how Three ways to answer check affects your king safety and your opponent’s best reply.","fr":"Avant de jouer, demandez-vous comment Trois façons de parer l’échec influence la sécurité de votre roi et la meilleure réponse adverse.","ar":"قبل أن تلعب، فكّر كيف يؤثر ثلاث وسائل للرد على الكش في أمان ملكك وفي أفضل رد للخصم."},{"en":"Before moving, pause and ask how Delivering mate affects your king safety and your opponent’s best reply.","fr":"Avant de jouer, demandez-vous comment Donner échec et mat influence la sécurité de votre roi et la meilleure réponse adverse.","ar":"قبل أن تلعب، فكّر كيف يؤثر تنفيذ كش مات في أمان ملكك وفي أفضل رد للخصم."}],"exercises":[{"en":"Set up a position that demonstrates Check. Name the legal choices and explain why one choice follows the rule.","fr":"Préparez une position illustrant L’échec. Indiquez les choix légaux et expliquez lequel respecte la règle.","ar":"أنشئ وضعية توضّح الكش. اذكر النقلات القانونية واشرح لماذا تتبع إحداها القاعدة."},{"en":"Set up a position that demonstrates Checkmate. Name the legal choices and explain why one choice follows the rule.","fr":"Préparez une position illustrant L’échec et mat. Indiquez les choix légaux et expliquez lequel respecte la règle.","ar":"أنشئ وضعية توضّح كش مات. اذكر النقلات القانونية واشرح لماذا تتبع إحداها القاعدة."},{"en":"Set up a position that demonstrates Stalemate. Name the legal choices and explain why one choice follows the rule.","fr":"Préparez une position illustrant Le pat. Indiquez les choix légaux et expliquez lequel respecte la règle.","ar":"أنشئ وضعية توضّح الجمود. اذكر النقلات القانونية واشرح لماذا تتبع إحداها القاعدة."},{"en":"Set up a position that demonstrates Three ways to answer check. Name the legal choices and explain why one choice follows the rule.","fr":"Préparez une position illustrant Trois façons de parer l’échec. Indiquez les choix légaux et expliquez lequel respecte la règle.","ar":"أنشئ وضعية توضّح ثلاث وسائل للرد على الكش. اذكر النقلات القانونية واشرح لماذا تتبع إحداها القاعدة."},{"en":"Set up a position that demonstrates Delivering mate. Name the legal choices and explain why one choice follows the rule.","fr":"Préparez une position illustrant Donner échec et mat. Indiquez les choix légaux et expliquez lequel respecte la règle.","ar":"أنشئ وضعية توضّح تنفيذ كش مات. اذكر النقلات القانونية واشرح لماذا تتبع إحداها القاعدة."}],"takeaways":[{"en":"A king is in check when an opposing piece attacks its square.","fr":"Un roi est en échec lorsqu’une pièce adverse attaque sa case.","ar":"يكون الملك في كش عندما تهاجم قطعة للخصم مربعه."},{"en":"Checkmate occurs when the king is in check and no legal move can remove the threat.","fr":"Il y a échec et mat lorsque le roi est en échec et qu’aucun coup légal ne peut parer la menace.","ar":"يحدث كش مات عندما يكون الملك في كش ولا توجد نقلة قانونية تزيل التهديد."},{"en":"Stalemate is a draw when the player to move is not in check but has no legal move.","fr":"Le pat est une partie nulle lorsque le joueur au trait n’est pas en échec mais n’a aucun coup légal.","ar":"الجمود تعادل عندما لا يكون اللاعب الذي عليه الدور في كش ولا يملك أي نقلة قانونية."},{"en":"A check may be answered by moving the king, capturing the attacker, or blocking a sliding attack when possible.","fr":"On peut parer l’échec en déplaçant le roi, en capturant l’attaquant ou en bloquant une attaque à distance si possible.","ar":"يمكن الرد على الكش بتحريك الملك أو أسر المهاجم أو صد الهجوم الخطي إن أمكن."},{"en":"A mating move must attack the king and leave the opponent with no legal escape or defense.","fr":"Un coup de mat doit attaquer le roi et ne laisser aucune fuite ni défense légale.","ar":"يجب أن تهاجم نقلة المات الملك وألا تترك للخصم مهرباً أو دفاعاً قانونياً."}]}'::jsonb, TRUE) ON CONFLICT (id) DO UPDATE SET level_number = EXCLUDED.level_number, lesson_number = EXCLUDED.lesson_number, title = EXCLUDED.title, summary = EXCLUDED.summary, content = EXCLUDED.content, published = TRUE, updated_at = NOW();
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-09-q01', 'l1-09', 1, 'easy', 'multiple_choice', '{"en":"Which statement correctly describes Check?","fr":"Quelle affirmation décrit correctement L’échec ?","ar":"أي عبارة تصف الكش بشكل صحيح؟"}'::jsonb, '[{"id":"a","label":{"en":"A check may be answered by moving the king, capturing the attacker, or blocking a sliding attack when possible.","fr":"On peut parer l’échec en déplaçant le roi, en capturant l’attaquant ou en bloquant une attaque à distance si possible.","ar":"يمكن الرد على الكش بتحريك الملك أو أسر المهاجم أو صد الهجوم الخطي إن أمكن."}},{"id":"b","label":{"en":"A king is in check when an opposing piece attacks its square.","fr":"Un roi est en échec lorsqu’une pièce adverse attaque sa case.","ar":"يكون الملك في كش عندما تهاجم قطعة للخصم مربعه."}},{"id":"c","label":{"en":"Checkmate occurs when the king is in check and no legal move can remove the threat.","fr":"Il y a échec et mat lorsque le roi est en échec et qu’aucun coup légal ne peut parer la menace.","ar":"يحدث كش مات عندما يكون الملك في كش ولا توجد نقلة قانونية تزيل التهديد."}},{"id":"d","label":{"en":"Stalemate is a draw when the player to move is not in check but has no legal move.","fr":"Le pat est une partie nulle lorsque le joueur au trait n’est pas en échec mais n’a aucun coup légal.","ar":"الجمود تعادل عندما لا يكون اللاعب الذي عليه الدور في كش ولا يملك أي نقلة قانونية."}}]'::jsonb, 'b', '{"en":"Check must be answered on the very next move. A player may not leave their king in check or make a move that exposes it to check.","fr":"Il faut parer l’échec au coup suivant. On ne peut pas laisser son roi en échec ni jouer un coup qui l’y expose.","ar":"يجب الرد على الكش في النقلة التالية. لا يجوز ترك الملك في كش أو تنفيذ نقلة تكشفه له."}'::jsonb, '{"en":"Review the rule and compare it with the position. Check","fr":"Relisez la règle et comparez-la à la position. L’échec","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. الكش"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-09-q02', 'l1-09', 2, 'medium', 'multiple_choice', '{"en":"You are teaching a beginner about Check. Which rule should they apply?","fr":"Vous expliquez L’échec à un débutant. Quelle règle doit-il appliquer ?","ar":"تشرح الكش لمبتدئ. ما القاعدة التي ينبغي تطبيقها؟"}'::jsonb, '[{"id":"a","label":{"en":"Stalemate is a draw when the player to move is not in check but has no legal move.","fr":"Le pat est une partie nulle lorsque le joueur au trait n’est pas en échec mais n’a aucun coup légal.","ar":"الجمود تعادل عندما لا يكون اللاعب الذي عليه الدور في كش ولا يملك أي نقلة قانونية."}},{"id":"b","label":{"en":"A check may be answered by moving the king, capturing the attacker, or blocking a sliding attack when possible.","fr":"On peut parer l’échec en déplaçant le roi, en capturant l’attaquant ou en bloquant une attaque à distance si possible.","ar":"يمكن الرد على الكش بتحريك الملك أو أسر المهاجم أو صد الهجوم الخطي إن أمكن."}},{"id":"c","label":{"en":"A king is in check when an opposing piece attacks its square.","fr":"Un roi est en échec lorsqu’une pièce adverse attaque sa case.","ar":"يكون الملك في كش عندما تهاجم قطعة للخصم مربعه."}},{"id":"d","label":{"en":"Checkmate occurs when the king is in check and no legal move can remove the threat.","fr":"Il y a échec et mat lorsque le roi est en échec et qu’aucun coup légal ne peut parer la menace.","ar":"يحدث كش مات عندما يكون الملك في كش ولا توجد نقلة قانونية تزيل التهديد."}}]'::jsonb, 'c', '{"en":"Check must be answered on the very next move. A player may not leave their king in check or make a move that exposes it to check.","fr":"Il faut parer l’échec au coup suivant. On ne peut pas laisser son roi en échec ni jouer un coup qui l’y expose.","ar":"يجب الرد على الكش في النقلة التالية. لا يجوز ترك الملك في كش أو تنفيذ نقلة تكشفه له."}'::jsonb, '{"en":"Review the rule and compare it with the position. Check","fr":"Relisez la règle et comparez-la à la position. L’échec","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. الكش"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-09-q03', 'l1-09', 3, 'medium', 'true_false', '{"en":"True or false: A king is in check when an opposing piece attacks its square.","fr":"Vrai ou faux : Un roi est en échec lorsqu’une pièce adverse attaque sa case.","ar":"صح أم خطأ: يكون الملك في كش عندما تهاجم قطعة للخصم مربعه."}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'true', '{"en":"Check must be answered on the very next move. A player may not leave their king in check or make a move that exposes it to check.","fr":"Il faut parer l’échec au coup suivant. On ne peut pas laisser son roi en échec ni jouer un coup qui l’y expose.","ar":"يجب الرد على الكش في النقلة التالية. لا يجوز ترك الملك في كش أو تنفيذ نقلة تكشفه له."}'::jsonb, '{"en":"Review the rule and compare it with the position. Check","fr":"Relisez la règle et comparez-la à la position. L’échec","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. الكش"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-09-q04', 'l1-09', 4, 'hard', 'identify_mistake', '{"en":"A student claims: “Check is optional to answer if the player can capture another piece.” Is the claim correct?","fr":"Un élève affirme : « Il est facultatif de parer l’échec si l’on peut capturer une autre pièce. » Cette affirmation est-elle correcte ?","ar":"يقول طالب: «الرد على الكش اختياري إذا استطاع اللاعب أسر قطعة أخرى.» هل قوله صحيح؟"}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'false', '{"en":"Check must be answered on the very next move. A player may not leave their king in check or make a move that exposes it to check.","fr":"Il faut parer l’échec au coup suivant. On ne peut pas laisser son roi en échec ni jouer un coup qui l’y expose.","ar":"يجب الرد على الكش في النقلة التالية. لا يجوز ترك الملك في كش أو تنفيذ نقلة تكشفه له."}'::jsonb, '{"en":"Review the rule and compare it with the position. Check","fr":"Relisez la règle et comparez-la à la position. L’échec","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. الكش"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-09-q05', 'l1-09', 5, 'easy', 'multiple_choice', '{"en":"Which statement correctly describes Checkmate?","fr":"Quelle affirmation décrit correctement L’échec et mat ?","ar":"أي عبارة تصف كش مات بشكل صحيح؟"}'::jsonb, '[{"id":"a","label":{"en":"A check may be answered by moving the king, capturing the attacker, or blocking a sliding attack when possible.","fr":"On peut parer l’échec en déplaçant le roi, en capturant l’attaquant ou en bloquant une attaque à distance si possible.","ar":"يمكن الرد على الكش بتحريك الملك أو أسر المهاجم أو صد الهجوم الخطي إن أمكن."}},{"id":"b","label":{"en":"A mating move must attack the king and leave the opponent with no legal escape or defense.","fr":"Un coup de mat doit attaquer le roi et ne laisser aucune fuite ni défense légale.","ar":"يجب أن تهاجم نقلة المات الملك وألا تترك للخصم مهرباً أو دفاعاً قانونياً."}},{"id":"c","label":{"en":"Checkmate occurs when the king is in check and no legal move can remove the threat.","fr":"Il y a échec et mat lorsque le roi est en échec et qu’aucun coup légal ne peut parer la menace.","ar":"يحدث كش مات عندما يكون الملك في كش ولا توجد نقلة قانونية تزيل التهديد."}},{"id":"d","label":{"en":"Stalemate is a draw when the player to move is not in check but has no legal move.","fr":"Le pat est une partie nulle lorsque le joueur au trait n’est pas en échec mais n’a aucun coup légal.","ar":"الجمود تعادل عندما لا يكون اللاعب الذي عليه الدور في كش ولا يملك أي نقلة قانونية."}}]'::jsonb, 'c', '{"en":"Test every possible defense: king moves, captures of the checking piece, and blocks against sliding attacks. If none work, the game ends immediately with a win for the attacker.","fr":"Vérifiez les déplacements du roi, la capture de l’attaquant et la parade d’une attaque à distance. Si aucune défense ne fonctionne, la partie se termine par une victoire.","ar":"افحص تحركات الملك وأسر القطعة المهاجمة وصد الهجوم الخطي. إن لم تنجح أي وسيلة، تنتهي المباراة بفوز المهاجم."}'::jsonb, '{"en":"Review the rule and compare it with the position. Checkmate","fr":"Relisez la règle et comparez-la à la position. L’échec et mat","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. كش مات"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-09-q06', 'l1-09', 6, 'medium', 'multiple_choice', '{"en":"You are teaching a beginner about Checkmate. Which rule should they apply?","fr":"Vous expliquez L’échec et mat à un débutant. Quelle règle doit-il appliquer ?","ar":"تشرح كش مات لمبتدئ. ما القاعدة التي ينبغي تطبيقها؟"}'::jsonb, '[{"id":"a","label":{"en":"Stalemate is a draw when the player to move is not in check but has no legal move.","fr":"Le pat est une partie nulle lorsque le joueur au trait n’est pas en échec mais n’a aucun coup légal.","ar":"الجمود تعادل عندما لا يكون اللاعب الذي عليه الدور في كش ولا يملك أي نقلة قانونية."}},{"id":"b","label":{"en":"A check may be answered by moving the king, capturing the attacker, or blocking a sliding attack when possible.","fr":"On peut parer l’échec en déplaçant le roi, en capturant l’attaquant ou en bloquant une attaque à distance si possible.","ar":"يمكن الرد على الكش بتحريك الملك أو أسر المهاجم أو صد الهجوم الخطي إن أمكن."}},{"id":"c","label":{"en":"A mating move must attack the king and leave the opponent with no legal escape or defense.","fr":"Un coup de mat doit attaquer le roi et ne laisser aucune fuite ni défense légale.","ar":"يجب أن تهاجم نقلة المات الملك وألا تترك للخصم مهرباً أو دفاعاً قانونياً."}},{"id":"d","label":{"en":"Checkmate occurs when the king is in check and no legal move can remove the threat.","fr":"Il y a échec et mat lorsque le roi est en échec et qu’aucun coup légal ne peut parer la menace.","ar":"يحدث كش مات عندما يكون الملك في كش ولا توجد نقلة قانونية تزيل التهديد."}}]'::jsonb, 'd', '{"en":"Test every possible defense: king moves, captures of the checking piece, and blocks against sliding attacks. If none work, the game ends immediately with a win for the attacker.","fr":"Vérifiez les déplacements du roi, la capture de l’attaquant et la parade d’une attaque à distance. Si aucune défense ne fonctionne, la partie se termine par une victoire.","ar":"افحص تحركات الملك وأسر القطعة المهاجمة وصد الهجوم الخطي. إن لم تنجح أي وسيلة، تنتهي المباراة بفوز المهاجم."}'::jsonb, '{"en":"Review the rule and compare it with the position. Checkmate","fr":"Relisez la règle et comparez-la à la position. L’échec et mat","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. كش مات"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-09-q07', 'l1-09', 7, 'medium', 'true_false', '{"en":"True or false: Checkmate occurs when the king is in check and no legal move can remove the threat.","fr":"Vrai ou faux : Il y a échec et mat lorsque le roi est en échec et qu’aucun coup légal ne peut parer la menace.","ar":"صح أم خطأ: يحدث كش مات عندما يكون الملك في كش ولا توجد نقلة قانونية تزيل التهديد."}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'true', '{"en":"Test every possible defense: king moves, captures of the checking piece, and blocks against sliding attacks. If none work, the game ends immediately with a win for the attacker.","fr":"Vérifiez les déplacements du roi, la capture de l’attaquant et la parade d’une attaque à distance. Si aucune défense ne fonctionne, la partie se termine par une victoire.","ar":"افحص تحركات الملك وأسر القطعة المهاجمة وصد الهجوم الخطي. إن لم تنجح أي وسيلة، تنتهي المباراة بفوز المهاجم."}'::jsonb, '{"en":"Review the rule and compare it with the position. Checkmate","fr":"Relisez la règle et comparez-la à la position. L’échec et mat","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. كش مات"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-09-q08', 'l1-09', 8, 'hard', 'identify_mistake', '{"en":"A student claims: “Checkmate means the king is attacked but may still escape on the next turn.” Is the claim correct?","fr":"Un élève affirme : « Le mat signifie que le roi est attaqué mais pourra fuir au prochain tour. » Cette affirmation est-elle correcte ?","ar":"يقول طالب: «يعني كش مات أن الملك مهدد لكنه يستطيع الهرب في الدور التالي.» هل قوله صحيح؟"}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'false', '{"en":"Test every possible defense: king moves, captures of the checking piece, and blocks against sliding attacks. If none work, the game ends immediately with a win for the attacker.","fr":"Vérifiez les déplacements du roi, la capture de l’attaquant et la parade d’une attaque à distance. Si aucune défense ne fonctionne, la partie se termine par une victoire.","ar":"افحص تحركات الملك وأسر القطعة المهاجمة وصد الهجوم الخطي. إن لم تنجح أي وسيلة، تنتهي المباراة بفوز المهاجم."}'::jsonb, '{"en":"Review the rule and compare it with the position. Checkmate","fr":"Relisez la règle et comparez-la à la position. L’échec et mat","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. كش مات"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-09-q09', 'l1-09', 9, 'easy', 'multiple_choice', '{"en":"Which statement correctly describes Stalemate?","fr":"Quelle affirmation décrit correctement Le pat ?","ar":"أي عبارة تصف الجمود بشكل صحيح؟"}'::jsonb, '[{"id":"a","label":{"en":"A check may be answered by moving the king, capturing the attacker, or blocking a sliding attack when possible.","fr":"On peut parer l’échec en déplaçant le roi, en capturant l’attaquant ou en bloquant une attaque à distance si possible.","ar":"يمكن الرد على الكش بتحريك الملك أو أسر المهاجم أو صد الهجوم الخطي إن أمكن."}},{"id":"b","label":{"en":"A mating move must attack the king and leave the opponent with no legal escape or defense.","fr":"Un coup de mat doit attaquer le roi et ne laisser aucune fuite ni défense légale.","ar":"يجب أن تهاجم نقلة المات الملك وألا تترك للخصم مهرباً أو دفاعاً قانونياً."}},{"id":"c","label":{"en":"A king is in check when an opposing piece attacks its square.","fr":"Un roi est en échec lorsqu’une pièce adverse attaque sa case.","ar":"يكون الملك في كش عندما تهاجم قطعة للخصم مربعه."}},{"id":"d","label":{"en":"Stalemate is a draw when the player to move is not in check but has no legal move.","fr":"Le pat est une partie nulle lorsque le joueur au trait n’est pas en échec mais n’a aucun coup légal.","ar":"الجمود تعادل عندما لا يكون اللاعب الذي عليه الدور في كش ولا يملك أي نقلة قانونية."}}]'::jsonb, 'd', '{"en":"Stalemate is not checkmate. A player who is ahead in material must avoid removing every legal move unless the king is actually checkmated.","fr":"Le pat n’est pas un échec et mat. Un joueur en avantage matériel doit éviter de supprimer tous les coups légaux si le roi n’est pas réellement mat.","ar":"الجمود ليس كش مات. على المتقدم مادياً تجنب سلب الخصم كل النقلات القانونية ما لم يكن ملكه في كش مات فعلياً."}'::jsonb, '{"en":"Review the rule and compare it with the position. Stalemate","fr":"Relisez la règle et comparez-la à la position. Le pat","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. الجمود"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-09-q10', 'l1-09', 10, 'medium', 'multiple_choice', '{"en":"You are teaching a beginner about Stalemate. Which rule should they apply?","fr":"Vous expliquez Le pat à un débutant. Quelle règle doit-il appliquer ?","ar":"تشرح الجمود لمبتدئ. ما القاعدة التي ينبغي تطبيقها؟"}'::jsonb, '[{"id":"a","label":{"en":"Stalemate is a draw when the player to move is not in check but has no legal move.","fr":"Le pat est une partie nulle lorsque le joueur au trait n’est pas en échec mais n’a aucun coup légal.","ar":"الجمود تعادل عندما لا يكون اللاعب الذي عليه الدور في كش ولا يملك أي نقلة قانونية."}},{"id":"b","label":{"en":"A check may be answered by moving the king, capturing the attacker, or blocking a sliding attack when possible.","fr":"On peut parer l’échec en déplaçant le roi, en capturant l’attaquant ou en bloquant une attaque à distance si possible.","ar":"يمكن الرد على الكش بتحريك الملك أو أسر المهاجم أو صد الهجوم الخطي إن أمكن."}},{"id":"c","label":{"en":"A mating move must attack the king and leave the opponent with no legal escape or defense.","fr":"Un coup de mat doit attaquer le roi et ne laisser aucune fuite ni défense légale.","ar":"يجب أن تهاجم نقلة المات الملك وألا تترك للخصم مهرباً أو دفاعاً قانونياً."}},{"id":"d","label":{"en":"A king is in check when an opposing piece attacks its square.","fr":"Un roi est en échec lorsqu’une pièce adverse attaque sa case.","ar":"يكون الملك في كش عندما تهاجم قطعة للخصم مربعه."}}]'::jsonb, 'a', '{"en":"Stalemate is not checkmate. A player who is ahead in material must avoid removing every legal move unless the king is actually checkmated.","fr":"Le pat n’est pas un échec et mat. Un joueur en avantage matériel doit éviter de supprimer tous les coups légaux si le roi n’est pas réellement mat.","ar":"الجمود ليس كش مات. على المتقدم مادياً تجنب سلب الخصم كل النقلات القانونية ما لم يكن ملكه في كش مات فعلياً."}'::jsonb, '{"en":"Review the rule and compare it with the position. Stalemate","fr":"Relisez la règle et comparez-la à la position. Le pat","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. الجمود"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-09-q11', 'l1-09', 11, 'medium', 'true_false', '{"en":"True or false: Stalemate is a draw when the player to move is not in check but has no legal move.","fr":"Vrai ou faux : Le pat est une partie nulle lorsque le joueur au trait n’est pas en échec mais n’a aucun coup légal.","ar":"صح أم خطأ: الجمود تعادل عندما لا يكون اللاعب الذي عليه الدور في كش ولا يملك أي نقلة قانونية."}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'true', '{"en":"Stalemate is not checkmate. A player who is ahead in material must avoid removing every legal move unless the king is actually checkmated.","fr":"Le pat n’est pas un échec et mat. Un joueur en avantage matériel doit éviter de supprimer tous les coups légaux si le roi n’est pas réellement mat.","ar":"الجمود ليس كش مات. على المتقدم مادياً تجنب سلب الخصم كل النقلات القانونية ما لم يكن ملكه في كش مات فعلياً."}'::jsonb, '{"en":"Review the rule and compare it with the position. Stalemate","fr":"Relisez la règle et comparez-la à la position. Le pat","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. الجمود"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-09-q12', 'l1-09', 12, 'hard', 'identify_mistake', '{"en":"A student claims: “Stalemate is a win for the player who has more pieces.” Is the claim correct?","fr":"Un élève affirme : « Le pat est une victoire du joueur qui possède le plus de pièces. » Cette affirmation est-elle correcte ?","ar":"يقول طالب: «الجمود فوز للاعب الذي يملك قطعاً أكثر.» هل قوله صحيح؟"}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'false', '{"en":"Stalemate is not checkmate. A player who is ahead in material must avoid removing every legal move unless the king is actually checkmated.","fr":"Le pat n’est pas un échec et mat. Un joueur en avantage matériel doit éviter de supprimer tous les coups légaux si le roi n’est pas réellement mat.","ar":"الجمود ليس كش مات. على المتقدم مادياً تجنب سلب الخصم كل النقلات القانونية ما لم يكن ملكه في كش مات فعلياً."}'::jsonb, '{"en":"Review the rule and compare it with the position. Stalemate","fr":"Relisez la règle et comparez-la à la position. Le pat","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. الجمود"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-09-q13', 'l1-09', 13, 'easy', 'multiple_choice', '{"en":"Which statement correctly describes Three ways to answer check?","fr":"Quelle affirmation décrit correctement Trois façons de parer l’échec ?","ar":"أي عبارة تصف ثلاث وسائل للرد على الكش بشكل صحيح؟"}'::jsonb, '[{"id":"a","label":{"en":"A check may be answered by moving the king, capturing the attacker, or blocking a sliding attack when possible.","fr":"On peut parer l’échec en déplaçant le roi, en capturant l’attaquant ou en bloquant une attaque à distance si possible.","ar":"يمكن الرد على الكش بتحريك الملك أو أسر المهاجم أو صد الهجوم الخطي إن أمكن."}},{"id":"b","label":{"en":"A mating move must attack the king and leave the opponent with no legal escape or defense.","fr":"Un coup de mat doit attaquer le roi et ne laisser aucune fuite ni défense légale.","ar":"يجب أن تهاجم نقلة المات الملك وألا تترك للخصم مهرباً أو دفاعاً قانونياً."}},{"id":"c","label":{"en":"A king is in check when an opposing piece attacks its square.","fr":"Un roi est en échec lorsqu’une pièce adverse attaque sa case.","ar":"يكون الملك في كش عندما تهاجم قطعة للخصم مربعه."}},{"id":"d","label":{"en":"Checkmate occurs when the king is in check and no legal move can remove the threat.","fr":"Il y a échec et mat lorsque le roi est en échec et qu’aucun coup légal ne peut parer la menace.","ar":"يحدث كش مات عندما يكون الملك في كش ولا توجد نقلة قانونية تزيل التهديد."}}]'::jsonb, 'a', '{"en":"Not every check permits all three defenses. A knight check cannot be blocked, and a double check normally requires moving the king. Analyze the actual geometry of the attack.","fr":"Toutes les défenses ne sont pas possibles contre chaque échec. On ne bloque pas un échec de cavalier et un double échec impose généralement de bouger le roi.","ar":"لا تتاح الوسائل الثلاث لكل كش. لا يمكن صد كش الحصان، والكش المزدوج يتطلب عادةً تحريك الملك. افحص شكل الهجوم."}'::jsonb, '{"en":"Review the rule and compare it with the position. Three ways to answer check","fr":"Relisez la règle et comparez-la à la position. Trois façons de parer l’échec","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. ثلاث وسائل للرد على الكش"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-09-q14', 'l1-09', 14, 'medium', 'multiple_choice', '{"en":"You are teaching a beginner about Three ways to answer check. Which rule should they apply?","fr":"Vous expliquez Trois façons de parer l’échec à un débutant. Quelle règle doit-il appliquer ?","ar":"تشرح ثلاث وسائل للرد على الكش لمبتدئ. ما القاعدة التي ينبغي تطبيقها؟"}'::jsonb, '[{"id":"a","label":{"en":"Checkmate occurs when the king is in check and no legal move can remove the threat.","fr":"Il y a échec et mat lorsque le roi est en échec et qu’aucun coup légal ne peut parer la menace.","ar":"يحدث كش مات عندما يكون الملك في كش ولا توجد نقلة قانونية تزيل التهديد."}},{"id":"b","label":{"en":"A check may be answered by moving the king, capturing the attacker, or blocking a sliding attack when possible.","fr":"On peut parer l’échec en déplaçant le roi, en capturant l’attaquant ou en bloquant une attaque à distance si possible.","ar":"يمكن الرد على الكش بتحريك الملك أو أسر المهاجم أو صد الهجوم الخطي إن أمكن."}},{"id":"c","label":{"en":"A mating move must attack the king and leave the opponent with no legal escape or defense.","fr":"Un coup de mat doit attaquer le roi et ne laisser aucune fuite ni défense légale.","ar":"يجب أن تهاجم نقلة المات الملك وألا تترك للخصم مهرباً أو دفاعاً قانونياً."}},{"id":"d","label":{"en":"A king is in check when an opposing piece attacks its square.","fr":"Un roi est en échec lorsqu’une pièce adverse attaque sa case.","ar":"يكون الملك في كش عندما تهاجم قطعة للخصم مربعه."}}]'::jsonb, 'b', '{"en":"Not every check permits all three defenses. A knight check cannot be blocked, and a double check normally requires moving the king. Analyze the actual geometry of the attack.","fr":"Toutes les défenses ne sont pas possibles contre chaque échec. On ne bloque pas un échec de cavalier et un double échec impose généralement de bouger le roi.","ar":"لا تتاح الوسائل الثلاث لكل كش. لا يمكن صد كش الحصان، والكش المزدوج يتطلب عادةً تحريك الملك. افحص شكل الهجوم."}'::jsonb, '{"en":"Review the rule and compare it with the position. Three ways to answer check","fr":"Relisez la règle et comparez-la à la position. Trois façons de parer l’échec","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. ثلاث وسائل للرد على الكش"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-09-q15', 'l1-09', 15, 'medium', 'true_false', '{"en":"True or false: A check may be answered by moving the king, capturing the attacker, or blocking a sliding attack when possible.","fr":"Vrai ou faux : On peut parer l’échec en déplaçant le roi, en capturant l’attaquant ou en bloquant une attaque à distance si possible.","ar":"صح أم خطأ: يمكن الرد على الكش بتحريك الملك أو أسر المهاجم أو صد الهجوم الخطي إن أمكن."}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'true', '{"en":"Not every check permits all three defenses. A knight check cannot be blocked, and a double check normally requires moving the king. Analyze the actual geometry of the attack.","fr":"Toutes les défenses ne sont pas possibles contre chaque échec. On ne bloque pas un échec de cavalier et un double échec impose généralement de bouger le roi.","ar":"لا تتاح الوسائل الثلاث لكل كش. لا يمكن صد كش الحصان، والكش المزدوج يتطلب عادةً تحريك الملك. افحص شكل الهجوم."}'::jsonb, '{"en":"Review the rule and compare it with the position. Three ways to answer check","fr":"Relisez la règle et comparez-la à la position. Trois façons de parer l’échec","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. ثلاث وسائل للرد على الكش"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-09-q16', 'l1-09', 16, 'hard', 'identify_mistake', '{"en":"A student claims: “Every check can be blocked by placing any piece between attacker and king.” Is the claim correct?","fr":"Un élève affirme : « On peut parer tout échec en plaçant n’importe quelle pièce entre l’attaquant et le roi. » Cette affirmation est-elle correcte ?","ar":"يقول طالب: «يمكن صد كل كش بوضع أي قطعة بين المهاجم والملك.» هل قوله صحيح؟"}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'false', '{"en":"Not every check permits all three defenses. A knight check cannot be blocked, and a double check normally requires moving the king. Analyze the actual geometry of the attack.","fr":"Toutes les défenses ne sont pas possibles contre chaque échec. On ne bloque pas un échec de cavalier et un double échec impose généralement de bouger le roi.","ar":"لا تتاح الوسائل الثلاث لكل كش. لا يمكن صد كش الحصان، والكش المزدوج يتطلب عادةً تحريك الملك. افحص شكل الهجوم."}'::jsonb, '{"en":"Review the rule and compare it with the position. Three ways to answer check","fr":"Relisez la règle et comparez-la à la position. Trois façons de parer l’échec","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. ثلاث وسائل للرد على الكش"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-09-q17', 'l1-09', 17, 'easy', 'multiple_choice', '{"en":"Which statement correctly describes Delivering mate?","fr":"Quelle affirmation décrit correctement Donner échec et mat ?","ar":"أي عبارة تصف تنفيذ كش مات بشكل صحيح؟"}'::jsonb, '[{"id":"a","label":{"en":"Stalemate is a draw when the player to move is not in check but has no legal move.","fr":"Le pat est une partie nulle lorsque le joueur au trait n’est pas en échec mais n’a aucun coup légal.","ar":"الجمود تعادل عندما لا يكون اللاعب الذي عليه الدور في كش ولا يملك أي نقلة قانونية."}},{"id":"b","label":{"en":"A mating move must attack the king and leave the opponent with no legal escape or defense.","fr":"Un coup de mat doit attaquer le roi et ne laisser aucune fuite ni défense légale.","ar":"يجب أن تهاجم نقلة المات الملك وألا تترك للخصم مهرباً أو دفاعاً قانونياً."}},{"id":"c","label":{"en":"A king is in check when an opposing piece attacks its square.","fr":"Un roi est en échec lorsqu’une pièce adverse attaque sa case.","ar":"يكون الملك في كش عندما تهاجم قطعة للخصم مربعه."}},{"id":"d","label":{"en":"Checkmate occurs when the king is in check and no legal move can remove the threat.","fr":"Il y a échec et mat lorsque le roi est en échec et qu’aucun coup légal ne peut parer la menace.","ar":"يحدث كش مات عندما يكون الملك في كش ولا توجد نقلة قانونية تزيل التهديد."}}]'::jsonb, 'b', '{"en":"Before announcing mate, check captures, king escapes, and blocks. A move that merely attacks the king is check, not mate, if even one legal defense remains.","fr":"Avant d’annoncer le mat, vérifiez les captures, les fuites du roi et les parades. S’il reste une seule défense légale, il s’agit seulement d’un échec.","ar":"قبل إعلان المات، افحص الأسر وهروب الملك والصد. إذا بقي دفاع قانوني واحد، فهذه نقلة كش وليست مات."}'::jsonb, '{"en":"Review the rule and compare it with the position. Delivering mate","fr":"Relisez la règle et comparez-la à la position. Donner échec et mat","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. تنفيذ كش مات"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-09-q18', 'l1-09', 18, 'medium', 'multiple_choice', '{"en":"You are teaching a beginner about Delivering mate. Which rule should they apply?","fr":"Vous expliquez Donner échec et mat à un débutant. Quelle règle doit-il appliquer ?","ar":"تشرح تنفيذ كش مات لمبتدئ. ما القاعدة التي ينبغي تطبيقها؟"}'::jsonb, '[{"id":"a","label":{"en":"Checkmate occurs when the king is in check and no legal move can remove the threat.","fr":"Il y a échec et mat lorsque le roi est en échec et qu’aucun coup légal ne peut parer la menace.","ar":"يحدث كش مات عندما يكون الملك في كش ولا توجد نقلة قانونية تزيل التهديد."}},{"id":"b","label":{"en":"Stalemate is a draw when the player to move is not in check but has no legal move.","fr":"Le pat est une partie nulle lorsque le joueur au trait n’est pas en échec mais n’a aucun coup légal.","ar":"الجمود تعادل عندما لا يكون اللاعب الذي عليه الدور في كش ولا يملك أي نقلة قانونية."}},{"id":"c","label":{"en":"A mating move must attack the king and leave the opponent with no legal escape or defense.","fr":"Un coup de mat doit attaquer le roi et ne laisser aucune fuite ni défense légale.","ar":"يجب أن تهاجم نقلة المات الملك وألا تترك للخصم مهرباً أو دفاعاً قانونياً."}},{"id":"d","label":{"en":"A king is in check when an opposing piece attacks its square.","fr":"Un roi est en échec lorsqu’une pièce adverse attaque sa case.","ar":"يكون الملك في كش عندما تهاجم قطعة للخصم مربعه."}}]'::jsonb, 'c', '{"en":"Before announcing mate, check captures, king escapes, and blocks. A move that merely attacks the king is check, not mate, if even one legal defense remains.","fr":"Avant d’annoncer le mat, vérifiez les captures, les fuites du roi et les parades. S’il reste une seule défense légale, il s’agit seulement d’un échec.","ar":"قبل إعلان المات، افحص الأسر وهروب الملك والصد. إذا بقي دفاع قانوني واحد، فهذه نقلة كش وليست مات."}'::jsonb, '{"en":"Review the rule and compare it with the position. Delivering mate","fr":"Relisez la règle et comparez-la à la position. Donner échec et mat","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. تنفيذ كش مات"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-09-q19', 'l1-09', 19, 'medium', 'true_false', '{"en":"True or false: A mating move must attack the king and leave the opponent with no legal escape or defense.","fr":"Vrai ou faux : Un coup de mat doit attaquer le roi et ne laisser aucune fuite ni défense légale.","ar":"صح أم خطأ: يجب أن تهاجم نقلة المات الملك وألا تترك للخصم مهرباً أو دفاعاً قانونياً."}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'true', '{"en":"Before announcing mate, check captures, king escapes, and blocks. A move that merely attacks the king is check, not mate, if even one legal defense remains.","fr":"Avant d’annoncer le mat, vérifiez les captures, les fuites du roi et les parades. S’il reste une seule défense légale, il s’agit seulement d’un échec.","ar":"قبل إعلان المات، افحص الأسر وهروب الملك والصد. إذا بقي دفاع قانوني واحد، فهذه نقلة كش وليست مات."}'::jsonb, '{"en":"Review the rule and compare it with the position. Delivering mate","fr":"Relisez la règle et comparez-la à la position. Donner échec et mat","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. تنفيذ كش مات"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-09-q20', 'l1-09', 20, 'hard', 'find_checkmate', '{"en":"On the board, make a legal move that demonstrates Delivering mate.","fr":"Sur l’échiquier, jouez un coup légal qui illustre Donner échec et mat.","ar":"نفّذ على الرقعة نقلة قانونية توضح تنفيذ كش مات."}'::jsonb, '[{"id":"Kg5","label":{"en":"Kg5","fr":"Kg5","ar":"Kg5"}},{"id":"Qg7#","label":{"en":"Qg7#","fr":"Qg7#","ar":"Qg7#"}},{"id":"Ke7","label":{"en":"Ke7","fr":"Ke7","ar":"Ke7"}},{"id":"Kf7","label":{"en":"Kf7","fr":"Kf7","ar":"Kf7"}}]'::jsonb, 'Qg7#', '{"en":"Qg7# is checkmate: the queen checks the king and the white king protects the queen’s mating square.","fr":"Qg7# est mat : la dame attaque le roi et le roi blanc protège la case de mat.","ar":"Qg7# كش مات: تهاجم الملكة الملك ويحمي الملك الأبيض مربع المات."}'::jsonb, '{"en":"Review the rule and compare it with the position. Delivering mate","fr":"Relisez la règle et comparez-la à la position. Donner échec et mat","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. تنفيذ كش مات"}'::jsonb, '7k/8/5KQ1/8/8/8/8/8 w - - 0 1', '["Qg7#"]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_lessons (id, level_number, lesson_number, title, summary, content, published) VALUES ('l1-10', 1, 10, '{"en":"Castling, En Passant and Special Rules","fr":"Le roque, la prise en passant et les règles spéciales","ar":"التبييت والأخذ بالتجاوز والقواعد الخاصة"}'::jsonb, '{"en":"Apply castling and en passant correctly, and recognize when these special moves are legal.","fr":"Appliquez correctement le roque et la prise en passant, et vérifiez leur légalité.","ar":"طبّق التبييت والأخذ بالتجاوز بشكل صحيح وتحقق من قانونيتهما."}'::jsonb, '{"objectives":[{"en":"Castling move","fr":"Le coup de roque","ar":"نقلة التبييت"},{"en":"Castling rights","fr":"Les droits au roque","ar":"حق التبييت"},{"en":"Castling through check","fr":"Le roque en passant par l’échec","ar":"التبييت عبر الكش"},{"en":"En passant timing","fr":"Le moment de la prise en passant","ar":"توقيت الأخذ بالتجاوز"},{"en":"Promotion choice","fr":"Le choix de promotion","ar":"اختيار الترقية"}],"sections":[{"title":{"en":"Castling move","fr":"Le coup de roque","ar":"نقلة التبييت"},"paragraphs":[{"en":"Castling moves the king two squares toward a rook and moves that rook to the square next to the king.","fr":"Le roque déplace le roi de deux cases vers une tour, puis place la tour à côté du roi.","ar":"ينقل التبييت الملك مربعين نحو الرخ، ثم يضع الرخ في المربع المجاور للملك."},{"en":"Kingside castling is written O-O; queenside castling is O-O-O. It is the only move in which two of a player’s pieces move at once.","fr":"Le petit roque s’écrit O-O et le grand roque O-O-O. C’est le seul coup où deux pièces du même joueur bougent ensemble.","ar":"يُكتب التبييت القصير O-O والطويل O-O-O. وهي النقلة الوحيدة التي تتحرك فيها قطعتان للاعب نفسه معاً."},{"en":"Practice checkpoint: identify Castling move on a board, explain the rule, and check how the opponent could respond.","fr":"Mise en pratique : repérez Le coup de roque sur un échiquier, expliquez la règle et vérifiez la réponse possible de l’adversaire.","ar":"تطبيق عملي: حدّد نقلة التبييت على الرقعة، واشرح القاعدة، ثم تحقّق من رد الخصم الممكن."}]},{"title":{"en":"Castling rights","fr":"Les droits au roque","ar":"حق التبييت"},"paragraphs":[{"en":"Neither the king nor the castling rook may have moved earlier in the game.","fr":"Ni le roi ni la tour concernée ne doivent avoir déjà bougé pendant la partie.","ar":"يجب ألا يكون الملك أو الرخ المستخدم قد تحرك سابقاً في المباراة."},{"en":"A piece that returns to its starting square does not regain castling rights. The squares between the king and rook must also be empty.","fr":"Une pièce qui revient à sa case de départ ne récupère pas son droit au roque. Les cases entre le roi et la tour doivent être libres.","ar":"إذا عاد الملك أو الرخ إلى مربعه الأول فلا يستعيد حق التبييت. كما يجب أن تكون المربعات بينهما خالية."},{"en":"Practice checkpoint: identify Castling rights on a board, explain the rule, and check how the opponent could respond.","fr":"Mise en pratique : repérez Les droits au roque sur un échiquier, expliquez la règle et vérifiez la réponse possible de l’adversaire.","ar":"تطبيق عملي: حدّد حق التبييت على الرقعة، واشرح القاعدة، ثم تحقّق من رد الخصم الممكن."}]},{"title":{"en":"Castling through check","fr":"Le roque en passant par l’échec","ar":"التبييت عبر الكش"},"paragraphs":[{"en":"A player cannot castle while in check or if the king crosses or lands on an attacked square.","fr":"On ne peut pas roquer si le roi est en échec, traverse une case attaquée ou arrive sur une case attaquée.","ar":"لا يجوز التبييت إذا كان الملك في كش أو عبر مربعاً مهدداً أو وصل إلى مربع مهدد."},{"en":"The rook’s path may cross an attacked square; the restriction concerns the king’s starting, transit, and destination squares. Check all three before castling.","fr":"La tour peut traverser une case attaquée ; la restriction concerne les cases de départ, de passage et d’arrivée du roi. Vérifiez-les toutes.","ar":"قد يمر الرخ بمربع مهدد؛ لكن الشرط يتعلق بمربعات بداية الملك وعبوره ووصوله. افحصها جميعاً قبل التبييت."},{"en":"Practice checkpoint: identify Castling through check on a board, explain the rule, and check how the opponent could respond.","fr":"Mise en pratique : repérez Le roque en passant par l’échec sur un échiquier, expliquez la règle et vérifiez la réponse possible de l’adversaire.","ar":"تطبيق عملي: حدّد التبييت عبر الكش على الرقعة، واشرح القاعدة، ثم تحقّق من رد الخصم الممكن."}]},{"title":{"en":"En passant timing","fr":"Le moment de la prise en passant","ar":"توقيت الأخذ بالتجاوز"},"paragraphs":[{"en":"En passant is legal only on the move immediately after the opposing pawn advances two squares.","fr":"La prise en passant n’est légale qu’immédiatement après la double avance du pion adverse.","ar":"يصح الأخذ بالتجاوز فقط في النقلة التي تلي مباشرة تقدم بيدق الخصم مربعين."},{"en":"The right is temporary and disappears if another move is played. The capturing pawn moves diagonally to the passed-over square and removes the advanced pawn.","fr":"Ce droit est temporaire et disparaît si un autre coup est joué. Le pion preneur va sur la case traversée et retire le pion adverse.","ar":"هذا الحق مؤقت ويسقط إذا لُعبت نقلة أخرى. ينتقل البيدق الآسر إلى المربع المتجاوز ويزيل بيدق الخصم."},{"en":"Practice checkpoint: identify En passant timing on a board, explain the rule, and check how the opponent could respond.","fr":"Mise en pratique : repérez Le moment de la prise en passant sur un échiquier, expliquez la règle et vérifiez la réponse possible de l’adversaire.","ar":"تطبيق عملي: حدّد توقيت الأخذ بالتجاوز على الرقعة، واشرح القاعدة، ثم تحقّق من رد الخصم الممكن."}]},{"title":{"en":"Promotion choice","fr":"Le choix de promotion","ar":"اختيار الترقية"},"paragraphs":[{"en":"A promoting pawn may become a queen, rook, bishop, or knight, even if that piece is still on the board.","fr":"Un pion promu peut devenir dame, tour, fou ou cavalier, même si cette pièce est encore sur l’échiquier.","ar":"يمكن ترقية البيدق إلى ملكة أو رخ أو فيل أو حصان حتى لو كانت قطعة من النوع نفسه ما زالت على الرقعة."},{"en":"Promotion is not limited by captured pieces. A knight promotion may be useful to give a check or avoid stalemate; choose the piece that best fits the position.","fr":"La promotion ne dépend pas des pièces capturées. Un cavalier peut être utile pour donner échec ou éviter le pat ; choisissez selon la position.","ar":"لا تعتمد الترقية على القطع المأسورة. قد يفيد الحصان لإعطاء كش أو تجنب الجمود؛ اختر القطعة الأنسب للموقف."},{"en":"Practice checkpoint: identify Promotion choice on a board, explain the rule, and check how the opponent could respond.","fr":"Mise en pratique : repérez Le choix de promotion sur un échiquier, expliquez la règle et vérifiez la réponse possible de l’adversaire.","ar":"تطبيق عملي: حدّد اختيار الترقية على الرقعة، واشرح القاعدة، ثم تحقّق من رد الخصم الممكن."}]}],"terminology":[{"term":{"en":"Castling move","fr":"Le coup de roque","ar":"نقلة التبييت"},"definition":{"en":"Castling moves the king two squares toward a rook and moves that rook to the square next to the king.","fr":"Le roque déplace le roi de deux cases vers une tour, puis place la tour à côté du roi.","ar":"ينقل التبييت الملك مربعين نحو الرخ، ثم يضع الرخ في المربع المجاور للملك."}},{"term":{"en":"Castling rights","fr":"Les droits au roque","ar":"حق التبييت"},"definition":{"en":"Neither the king nor the castling rook may have moved earlier in the game.","fr":"Ni le roi ni la tour concernée ne doivent avoir déjà bougé pendant la partie.","ar":"يجب ألا يكون الملك أو الرخ المستخدم قد تحرك سابقاً في المباراة."}},{"term":{"en":"Castling through check","fr":"Le roque en passant par l’échec","ar":"التبييت عبر الكش"},"definition":{"en":"A player cannot castle while in check or if the king crosses or lands on an attacked square.","fr":"On ne peut pas roquer si le roi est en échec, traverse une case attaquée ou arrive sur une case attaquée.","ar":"لا يجوز التبييت إذا كان الملك في كش أو عبر مربعاً مهدداً أو وصل إلى مربع مهدد."}},{"term":{"en":"En passant timing","fr":"Le moment de la prise en passant","ar":"توقيت الأخذ بالتجاوز"},"definition":{"en":"En passant is legal only on the move immediately after the opposing pawn advances two squares.","fr":"La prise en passant n’est légale qu’immédiatement après la double avance du pion adverse.","ar":"يصح الأخذ بالتجاوز فقط في النقلة التي تلي مباشرة تقدم بيدق الخصم مربعين."}},{"term":{"en":"Promotion choice","fr":"Le choix de promotion","ar":"اختيار الترقية"},"definition":{"en":"A promoting pawn may become a queen, rook, bishop, or knight, even if that piece is still on the board.","fr":"Un pion promu peut devenir dame, tour, fou ou cavalier, même si cette pièce est encore sur l’échiquier.","ar":"يمكن ترقية البيدق إلى ملكة أو رخ أو فيل أو حصان حتى لو كانت قطعة من النوع نفسه ما زالت على الرقعة."}}],"example":{"fen":"r3k2r/8/8/8/8/8/8/R3K2R w KQkq - 0 1","solutionMoves":["O-O"],"annotation":{"en":"O-O is legal here: the king and rook have not moved, the path is clear, and the king does not cross an attacked square.","fr":"O-O est légal ici : le roi et la tour n’ont pas bougé, le chemin est libre et le roi ne traverse aucune case attaquée.","ar":"O-O قانونية هنا: لم يتحرك الملك أو الرخ، والطريق خالٍ، ولا يعبر الملك مربعاً مهدداً."}},"commonMistakes":[{"en":"Castling moves the rook two squares and leaves the king in place.","fr":"Le roque déplace la tour de deux cases et laisse le roi en place.","ar":"ينقل التبييت الرخ مربعين ويبقي الملك مكانه."},{"en":"A king may castle after moving away and returning to its original square.","fr":"Le roi peut roquer après avoir quitté puis retrouvé sa case initiale.","ar":"يستطيع الملك التبييت بعد مغادرة مربعه والعودة إليه."},{"en":"Castling is legal through check as long as the king’s final square is safe.","fr":"Le roque est permis en traversant l’échec si la case finale du roi est sûre.","ar":"يصح التبييت عبر الكش ما دام مربع الملك الأخير آمناً."},{"en":"En passant remains legal for the rest of the game after the two-square pawn move.","fr":"La prise en passant reste possible jusqu’à la fin de la partie après la double avance.","ar":"يبقى الأخذ بالتجاوز قانونياً حتى نهاية المباراة بعد حركة البيدق المزدوجة."},{"en":"You may promote only to a piece that has already been captured.","fr":"On ne peut promouvoir qu’en une pièce déjà capturée.","ar":"لا تجوز الترقية إلا إلى قطعة أُسرت سابقاً."}],"professionalTips":[{"en":"Before moving, pause and ask how Castling move affects your king safety and your opponent’s best reply.","fr":"Avant de jouer, demandez-vous comment Le coup de roque influence la sécurité de votre roi et la meilleure réponse adverse.","ar":"قبل أن تلعب، فكّر كيف يؤثر نقلة التبييت في أمان ملكك وفي أفضل رد للخصم."},{"en":"Before moving, pause and ask how Castling rights affects your king safety and your opponent’s best reply.","fr":"Avant de jouer, demandez-vous comment Les droits au roque influence la sécurité de votre roi et la meilleure réponse adverse.","ar":"قبل أن تلعب، فكّر كيف يؤثر حق التبييت في أمان ملكك وفي أفضل رد للخصم."},{"en":"Before moving, pause and ask how Castling through check affects your king safety and your opponent’s best reply.","fr":"Avant de jouer, demandez-vous comment Le roque en passant par l’échec influence la sécurité de votre roi et la meilleure réponse adverse.","ar":"قبل أن تلعب، فكّر كيف يؤثر التبييت عبر الكش في أمان ملكك وفي أفضل رد للخصم."},{"en":"Before moving, pause and ask how En passant timing affects your king safety and your opponent’s best reply.","fr":"Avant de jouer, demandez-vous comment Le moment de la prise en passant influence la sécurité de votre roi et la meilleure réponse adverse.","ar":"قبل أن تلعب، فكّر كيف يؤثر توقيت الأخذ بالتجاوز في أمان ملكك وفي أفضل رد للخصم."},{"en":"Before moving, pause and ask how Promotion choice affects your king safety and your opponent’s best reply.","fr":"Avant de jouer, demandez-vous comment Le choix de promotion influence la sécurité de votre roi et la meilleure réponse adverse.","ar":"قبل أن تلعب، فكّر كيف يؤثر اختيار الترقية في أمان ملكك وفي أفضل رد للخصم."}],"exercises":[{"en":"Set up a position that demonstrates Castling move. Name the legal choices and explain why one choice follows the rule.","fr":"Préparez une position illustrant Le coup de roque. Indiquez les choix légaux et expliquez lequel respecte la règle.","ar":"أنشئ وضعية توضّح نقلة التبييت. اذكر النقلات القانونية واشرح لماذا تتبع إحداها القاعدة."},{"en":"Set up a position that demonstrates Castling rights. Name the legal choices and explain why one choice follows the rule.","fr":"Préparez une position illustrant Les droits au roque. Indiquez les choix légaux et expliquez lequel respecte la règle.","ar":"أنشئ وضعية توضّح حق التبييت. اذكر النقلات القانونية واشرح لماذا تتبع إحداها القاعدة."},{"en":"Set up a position that demonstrates Castling through check. Name the legal choices and explain why one choice follows the rule.","fr":"Préparez une position illustrant Le roque en passant par l’échec. Indiquez les choix légaux et expliquez lequel respecte la règle.","ar":"أنشئ وضعية توضّح التبييت عبر الكش. اذكر النقلات القانونية واشرح لماذا تتبع إحداها القاعدة."},{"en":"Set up a position that demonstrates En passant timing. Name the legal choices and explain why one choice follows the rule.","fr":"Préparez une position illustrant Le moment de la prise en passant. Indiquez les choix légaux et expliquez lequel respecte la règle.","ar":"أنشئ وضعية توضّح توقيت الأخذ بالتجاوز. اذكر النقلات القانونية واشرح لماذا تتبع إحداها القاعدة."},{"en":"Set up a position that demonstrates Promotion choice. Name the legal choices and explain why one choice follows the rule.","fr":"Préparez une position illustrant Le choix de promotion. Indiquez les choix légaux et expliquez lequel respecte la règle.","ar":"أنشئ وضعية توضّح اختيار الترقية. اذكر النقلات القانونية واشرح لماذا تتبع إحداها القاعدة."}],"takeaways":[{"en":"Castling moves the king two squares toward a rook and moves that rook to the square next to the king.","fr":"Le roque déplace le roi de deux cases vers une tour, puis place la tour à côté du roi.","ar":"ينقل التبييت الملك مربعين نحو الرخ، ثم يضع الرخ في المربع المجاور للملك."},{"en":"Neither the king nor the castling rook may have moved earlier in the game.","fr":"Ni le roi ni la tour concernée ne doivent avoir déjà bougé pendant la partie.","ar":"يجب ألا يكون الملك أو الرخ المستخدم قد تحرك سابقاً في المباراة."},{"en":"A player cannot castle while in check or if the king crosses or lands on an attacked square.","fr":"On ne peut pas roquer si le roi est en échec, traverse une case attaquée ou arrive sur une case attaquée.","ar":"لا يجوز التبييت إذا كان الملك في كش أو عبر مربعاً مهدداً أو وصل إلى مربع مهدد."},{"en":"En passant is legal only on the move immediately after the opposing pawn advances two squares.","fr":"La prise en passant n’est légale qu’immédiatement après la double avance du pion adverse.","ar":"يصح الأخذ بالتجاوز فقط في النقلة التي تلي مباشرة تقدم بيدق الخصم مربعين."},{"en":"A promoting pawn may become a queen, rook, bishop, or knight, even if that piece is still on the board.","fr":"Un pion promu peut devenir dame, tour, fou ou cavalier, même si cette pièce est encore sur l’échiquier.","ar":"يمكن ترقية البيدق إلى ملكة أو رخ أو فيل أو حصان حتى لو كانت قطعة من النوع نفسه ما زالت على الرقعة."}]}'::jsonb, TRUE) ON CONFLICT (id) DO UPDATE SET level_number = EXCLUDED.level_number, lesson_number = EXCLUDED.lesson_number, title = EXCLUDED.title, summary = EXCLUDED.summary, content = EXCLUDED.content, published = TRUE, updated_at = NOW();
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-10-q01', 'l1-10', 1, 'easy', 'multiple_choice', '{"en":"Which statement correctly describes Castling move?","fr":"Quelle affirmation décrit correctement Le coup de roque ?","ar":"أي عبارة تصف نقلة التبييت بشكل صحيح؟"}'::jsonb, '[{"id":"a","label":{"en":"En passant is legal only on the move immediately after the opposing pawn advances two squares.","fr":"La prise en passant n’est légale qu’immédiatement après la double avance du pion adverse.","ar":"يصح الأخذ بالتجاوز فقط في النقلة التي تلي مباشرة تقدم بيدق الخصم مربعين."}},{"id":"b","label":{"en":"Castling moves the king two squares toward a rook and moves that rook to the square next to the king.","fr":"Le roque déplace le roi de deux cases vers une tour, puis place la tour à côté du roi.","ar":"ينقل التبييت الملك مربعين نحو الرخ، ثم يضع الرخ في المربع المجاور للملك."}},{"id":"c","label":{"en":"Neither the king nor the castling rook may have moved earlier in the game.","fr":"Ni le roi ni la tour concernée ne doivent avoir déjà bougé pendant la partie.","ar":"يجب ألا يكون الملك أو الرخ المستخدم قد تحرك سابقاً في المباراة."}},{"id":"d","label":{"en":"A player cannot castle while in check or if the king crosses or lands on an attacked square.","fr":"On ne peut pas roquer si le roi est en échec, traverse une case attaquée ou arrive sur une case attaquée.","ar":"لا يجوز التبييت إذا كان الملك في كش أو عبر مربعاً مهدداً أو وصل إلى مربع مهدد."}}]'::jsonb, 'b', '{"en":"Kingside castling is written O-O; queenside castling is O-O-O. It is the only move in which two of a player’s pieces move at once.","fr":"Le petit roque s’écrit O-O et le grand roque O-O-O. C’est le seul coup où deux pièces du même joueur bougent ensemble.","ar":"يُكتب التبييت القصير O-O والطويل O-O-O. وهي النقلة الوحيدة التي تتحرك فيها قطعتان للاعب نفسه معاً."}'::jsonb, '{"en":"Review the rule and compare it with the position. Castling move","fr":"Relisez la règle et comparez-la à la position. Le coup de roque","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. نقلة التبييت"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-10-q02', 'l1-10', 2, 'medium', 'multiple_choice', '{"en":"You are teaching a beginner about Castling move. Which rule should they apply?","fr":"Vous expliquez Le coup de roque à un débutant. Quelle règle doit-il appliquer ?","ar":"تشرح نقلة التبييت لمبتدئ. ما القاعدة التي ينبغي تطبيقها؟"}'::jsonb, '[{"id":"a","label":{"en":"A player cannot castle while in check or if the king crosses or lands on an attacked square.","fr":"On ne peut pas roquer si le roi est en échec, traverse une case attaquée ou arrive sur une case attaquée.","ar":"لا يجوز التبييت إذا كان الملك في كش أو عبر مربعاً مهدداً أو وصل إلى مربع مهدد."}},{"id":"b","label":{"en":"En passant is legal only on the move immediately after the opposing pawn advances two squares.","fr":"La prise en passant n’est légale qu’immédiatement après la double avance du pion adverse.","ar":"يصح الأخذ بالتجاوز فقط في النقلة التي تلي مباشرة تقدم بيدق الخصم مربعين."}},{"id":"c","label":{"en":"Castling moves the king two squares toward a rook and moves that rook to the square next to the king.","fr":"Le roque déplace le roi de deux cases vers une tour, puis place la tour à côté du roi.","ar":"ينقل التبييت الملك مربعين نحو الرخ، ثم يضع الرخ في المربع المجاور للملك."}},{"id":"d","label":{"en":"Neither the king nor the castling rook may have moved earlier in the game.","fr":"Ni le roi ni la tour concernée ne doivent avoir déjà bougé pendant la partie.","ar":"يجب ألا يكون الملك أو الرخ المستخدم قد تحرك سابقاً في المباراة."}}]'::jsonb, 'c', '{"en":"Kingside castling is written O-O; queenside castling is O-O-O. It is the only move in which two of a player’s pieces move at once.","fr":"Le petit roque s’écrit O-O et le grand roque O-O-O. C’est le seul coup où deux pièces du même joueur bougent ensemble.","ar":"يُكتب التبييت القصير O-O والطويل O-O-O. وهي النقلة الوحيدة التي تتحرك فيها قطعتان للاعب نفسه معاً."}'::jsonb, '{"en":"Review the rule and compare it with the position. Castling move","fr":"Relisez la règle et comparez-la à la position. Le coup de roque","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. نقلة التبييت"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-10-q03', 'l1-10', 3, 'medium', 'true_false', '{"en":"True or false: Castling moves the king two squares toward a rook and moves that rook to the square next to the king.","fr":"Vrai ou faux : Le roque déplace le roi de deux cases vers une tour, puis place la tour à côté du roi.","ar":"صح أم خطأ: ينقل التبييت الملك مربعين نحو الرخ، ثم يضع الرخ في المربع المجاور للملك."}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'true', '{"en":"Kingside castling is written O-O; queenside castling is O-O-O. It is the only move in which two of a player’s pieces move at once.","fr":"Le petit roque s’écrit O-O et le grand roque O-O-O. C’est le seul coup où deux pièces du même joueur bougent ensemble.","ar":"يُكتب التبييت القصير O-O والطويل O-O-O. وهي النقلة الوحيدة التي تتحرك فيها قطعتان للاعب نفسه معاً."}'::jsonb, '{"en":"Review the rule and compare it with the position. Castling move","fr":"Relisez la règle et comparez-la à la position. Le coup de roque","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. نقلة التبييت"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-10-q04', 'l1-10', 4, 'hard', 'identify_mistake', '{"en":"A student claims: “Castling moves the rook two squares and leaves the king in place.” Is the claim correct?","fr":"Un élève affirme : « Le roque déplace la tour de deux cases et laisse le roi en place. » Cette affirmation est-elle correcte ?","ar":"يقول طالب: «ينقل التبييت الرخ مربعين ويبقي الملك مكانه.» هل قوله صحيح؟"}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'false', '{"en":"Kingside castling is written O-O; queenside castling is O-O-O. It is the only move in which two of a player’s pieces move at once.","fr":"Le petit roque s’écrit O-O et le grand roque O-O-O. C’est le seul coup où deux pièces du même joueur bougent ensemble.","ar":"يُكتب التبييت القصير O-O والطويل O-O-O. وهي النقلة الوحيدة التي تتحرك فيها قطعتان للاعب نفسه معاً."}'::jsonb, '{"en":"Review the rule and compare it with the position. Castling move","fr":"Relisez la règle et comparez-la à la position. Le coup de roque","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. نقلة التبييت"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-10-q05', 'l1-10', 5, 'easy', 'multiple_choice', '{"en":"Which statement correctly describes Castling rights?","fr":"Quelle affirmation décrit correctement Les droits au roque ?","ar":"أي عبارة تصف حق التبييت بشكل صحيح؟"}'::jsonb, '[{"id":"a","label":{"en":"En passant is legal only on the move immediately after the opposing pawn advances two squares.","fr":"La prise en passant n’est légale qu’immédiatement après la double avance du pion adverse.","ar":"يصح الأخذ بالتجاوز فقط في النقلة التي تلي مباشرة تقدم بيدق الخصم مربعين."}},{"id":"b","label":{"en":"A promoting pawn may become a queen, rook, bishop, or knight, even if that piece is still on the board.","fr":"Un pion promu peut devenir dame, tour, fou ou cavalier, même si cette pièce est encore sur l’échiquier.","ar":"يمكن ترقية البيدق إلى ملكة أو رخ أو فيل أو حصان حتى لو كانت قطعة من النوع نفسه ما زالت على الرقعة."}},{"id":"c","label":{"en":"Neither the king nor the castling rook may have moved earlier in the game.","fr":"Ni le roi ni la tour concernée ne doivent avoir déjà bougé pendant la partie.","ar":"يجب ألا يكون الملك أو الرخ المستخدم قد تحرك سابقاً في المباراة."}},{"id":"d","label":{"en":"A player cannot castle while in check or if the king crosses or lands on an attacked square.","fr":"On ne peut pas roquer si le roi est en échec, traverse une case attaquée ou arrive sur une case attaquée.","ar":"لا يجوز التبييت إذا كان الملك في كش أو عبر مربعاً مهدداً أو وصل إلى مربع مهدد."}}]'::jsonb, 'c', '{"en":"A piece that returns to its starting square does not regain castling rights. The squares between the king and rook must also be empty.","fr":"Une pièce qui revient à sa case de départ ne récupère pas son droit au roque. Les cases entre le roi et la tour doivent être libres.","ar":"إذا عاد الملك أو الرخ إلى مربعه الأول فلا يستعيد حق التبييت. كما يجب أن تكون المربعات بينهما خالية."}'::jsonb, '{"en":"Review the rule and compare it with the position. Castling rights","fr":"Relisez la règle et comparez-la à la position. Les droits au roque","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. حق التبييت"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-10-q06', 'l1-10', 6, 'medium', 'multiple_choice', '{"en":"You are teaching a beginner about Castling rights. Which rule should they apply?","fr":"Vous expliquez Les droits au roque à un débutant. Quelle règle doit-il appliquer ?","ar":"تشرح حق التبييت لمبتدئ. ما القاعدة التي ينبغي تطبيقها؟"}'::jsonb, '[{"id":"a","label":{"en":"A player cannot castle while in check or if the king crosses or lands on an attacked square.","fr":"On ne peut pas roquer si le roi est en échec, traverse une case attaquée ou arrive sur une case attaquée.","ar":"لا يجوز التبييت إذا كان الملك في كش أو عبر مربعاً مهدداً أو وصل إلى مربع مهدد."}},{"id":"b","label":{"en":"En passant is legal only on the move immediately after the opposing pawn advances two squares.","fr":"La prise en passant n’est légale qu’immédiatement après la double avance du pion adverse.","ar":"يصح الأخذ بالتجاوز فقط في النقلة التي تلي مباشرة تقدم بيدق الخصم مربعين."}},{"id":"c","label":{"en":"A promoting pawn may become a queen, rook, bishop, or knight, even if that piece is still on the board.","fr":"Un pion promu peut devenir dame, tour, fou ou cavalier, même si cette pièce est encore sur l’échiquier.","ar":"يمكن ترقية البيدق إلى ملكة أو رخ أو فيل أو حصان حتى لو كانت قطعة من النوع نفسه ما زالت على الرقعة."}},{"id":"d","label":{"en":"Neither the king nor the castling rook may have moved earlier in the game.","fr":"Ni le roi ni la tour concernée ne doivent avoir déjà bougé pendant la partie.","ar":"يجب ألا يكون الملك أو الرخ المستخدم قد تحرك سابقاً في المباراة."}}]'::jsonb, 'd', '{"en":"A piece that returns to its starting square does not regain castling rights. The squares between the king and rook must also be empty.","fr":"Une pièce qui revient à sa case de départ ne récupère pas son droit au roque. Les cases entre le roi et la tour doivent être libres.","ar":"إذا عاد الملك أو الرخ إلى مربعه الأول فلا يستعيد حق التبييت. كما يجب أن تكون المربعات بينهما خالية."}'::jsonb, '{"en":"Review the rule and compare it with the position. Castling rights","fr":"Relisez la règle et comparez-la à la position. Les droits au roque","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. حق التبييت"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-10-q07', 'l1-10', 7, 'medium', 'true_false', '{"en":"True or false: Neither the king nor the castling rook may have moved earlier in the game.","fr":"Vrai ou faux : Ni le roi ni la tour concernée ne doivent avoir déjà bougé pendant la partie.","ar":"صح أم خطأ: يجب ألا يكون الملك أو الرخ المستخدم قد تحرك سابقاً في المباراة."}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'true', '{"en":"A piece that returns to its starting square does not regain castling rights. The squares between the king and rook must also be empty.","fr":"Une pièce qui revient à sa case de départ ne récupère pas son droit au roque. Les cases entre le roi et la tour doivent être libres.","ar":"إذا عاد الملك أو الرخ إلى مربعه الأول فلا يستعيد حق التبييت. كما يجب أن تكون المربعات بينهما خالية."}'::jsonb, '{"en":"Review the rule and compare it with the position. Castling rights","fr":"Relisez la règle et comparez-la à la position. Les droits au roque","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. حق التبييت"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-10-q08', 'l1-10', 8, 'hard', 'identify_mistake', '{"en":"A student claims: “A king may castle after moving away and returning to its original square.” Is the claim correct?","fr":"Un élève affirme : « Le roi peut roquer après avoir quitté puis retrouvé sa case initiale. » Cette affirmation est-elle correcte ?","ar":"يقول طالب: «يستطيع الملك التبييت بعد مغادرة مربعه والعودة إليه.» هل قوله صحيح؟"}'::jsonb, '[{"id":"true","label":{"en":"True","fr":"Vrai","ar":"صح"}},{"id":"false","label":{"en":"False","fr":"Faux","ar":"خطأ"}}]'::jsonb, 'false', '{"en":"A piece that returns to its starting square does not regain castling rights. The squares between the king and rook must also be empty.","fr":"Une pièce qui revient à sa case de départ ne récupère pas son droit au roque. Les cases entre le roi et la tour doivent être libres.","ar":"إذا عاد الملك أو الرخ إلى مربعه الأول فلا يستعيد حق التبييت. كما يجب أن تكون المربعات بينهما خالية."}'::jsonb, '{"en":"Review the rule and compare it with the position. Castling rights","fr":"Relisez la règle et comparez-la à la position. Les droits au roque","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. حق التبييت"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
INSERT INTO public.academy_questions (id, lesson_id, question_number, difficulty, question_type, prompt, choices, correct_answer, explanation, hint, fen, solution_moves) VALUES ('l1-10-q09', 'l1-10', 9, 'easy', 'multiple_choice', '{"en":"Which statement correctly describes Castling through check?","fr":"Quelle affirmation décrit correctement Le roque en passant par l’échec ?","ar":"أي عبارة تصف التبييت عبر الكش بشكل صحيح؟"}'::jsonb, '[{"id":"a","label":{"en":"En passant is legal only on the move immediately after the opposing pawn advances two squares.","fr":"La prise en passant n’est légale qu’immédiatement après la double avance du pion adverse.","ar":"يصح الأخذ بالتجاوز فقط في النقلة التي تلي مباشرة تقدم بيدق الخصم مربعين."}},{"id":"b","label":{"en":"A promoting pawn may become a queen, rook, bishop, or knight, even if that piece is still on the board.","fr":"Un pion promu peut devenir dame, tour, fou ou cavalier, même si cette pièce est encore sur l’échiquier.","ar":"يمكن ترقية البيدق إلى ملكة أو رخ أو فيل أو حصان حتى لو كانت قطعة من النوع نفسه ما زالت على الرقعة."}},{"id":"c","label":{"en":"Castling moves the king two squares toward a rook and moves that rook to the square next to the king.","fr":"Le roque déplace le roi de deux cases vers une tour, puis place la tour à côté du roi.","ar":"ينقل التبييت الملك مربعين نحو الرخ، ثم يضع الرخ في المربع المجاور للملك."}},{"id":"d","label":{"en":"A player cannot castle while in check or if the king crosses or lands on an attacked square.","fr":"On ne peut pas roquer si le roi est en échec, traverse une case attaquée ou arrive sur une case attaquée.","ar":"لا يجوز التبييت إذا كان الملك في كش أو عبر مربعاً مهدداً أو وصل إلى مربع مهدد."}}]'::jsonb, 'd', '{"en":"The rook’s path may cross an attacked square; the restriction concerns the king’s starting, transit, and destination squares. Check all three before castling.","fr":"La tour peut traverser une case attaquée ; la restriction concerne les cases de départ, de passage et d’arrivée du roi. Vérifiez-les toutes.","ar":"قد يمر الرخ بمربع مهدد؛ لكن الشرط يتعلق بمربعات بداية الملك وعبوره ووصوله. افحصها جميعاً قبل التبييت."}'::jsonb, '{"en":"Review the rule and compare it with the position. Castling through check","fr":"Relisez la règle et comparez-la à la position. Le roque en passant par l’échec","ar":"راجع القاعدة وقارنها بالوضع على الرقعة. التبييت عبر الكش"}'::jsonb, NULL, '[]'::jsonb) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, question_number = EXCLUDED.question_number, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, hint = EXCLUDED.hint, fen = EXCLUDED.fen, solution_moves = EXCLUDED.solution_moves;
